import { Book } from "@/lib/types";

export const jeremiah: Book = {
  id: "jeremiah",
  name: "Jeremia",
  shortName: "Jer",
  testament: "old",
  introduction: `Von Judas Rebellion und Verbannung ins Exil\n**Jeremia** war noch sehr jung, als er im 13. Regierungsjahr des jüdischen Königs Joschija (626 v.Chr.) **zum Propheten berufen** wurde. Er hatte eine schwere Last zu tragen, denn seine Botschaft war Gottes letzte Warnung an das Volk, das aber nicht hören wollte. Er wurde bedroht, vor Gericht gestellt, in Fesseln gelegt, öffentlich gedemütigt, in den Schlamm einer Zisterne geworfen usw. Jede seiner Ankündigungen erfüllte sich, doch folgte man stets den falschen Propheten und nicht ihm. Der Niedergang war schon so weit fortgeschritten, dass das Volk trotz der Reformen Joschijas, die es nur halbherzig mitmachte, geistlich immer mehr verfiel. Über die Niederschrift eines Teils seiner Weissagungen berichtet Jeremia in Kapitel 36 selbst. Er erlebte die Belagerung und Zerstörung Jerusalems und wurde vom Rest des Volkes gegen seinen Willen mit nach Ägypten genommen. Damals müsste er etwa 70 Jahre alt gewesen sein. In Ägypten schrieb er offenbar die Endform seines Buches, wobei er die Weissagungen aber nicht chronologisch ordnete. Er stellte oft Prophezeiungen nebeneinander, die zeitlich weit auseinander lagen. Sein Werk ist das längste Einzelbuch der Bibel und besteht zum großen Teil aus poetischen Texten. Nach jüdischer Überlieferung wurde Jeremia von Leuten aus seinem eigenen Volk in Ägypten gesteinigt.\n****Wie der Prophet einem rebellischen Volk Gottes Strafbotschaft bringen muss und selbst schwer darunter leidet.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Das sind die Worte von Jeremia Ben-Hilkija, der zu den Priestern aus Anatot* gehörte, einem Ort im Stammesgebiet von Benjamin.", heading: "1-20: Frommer König – rebellisches Volk\nJeremias Botschaft kompakt (1)", footnotes: ["Anatot. Der kleine Ort lag 5 km nordöstlich von Jerusalem."] },
      { number: 2, text: "Im 13. Regierungsjahr des Königs Joschija Ben-Amon* von Juda kam das Wort Jahwes zu ihm", footnotes: ["Joschija regierte von 640-609 v. Chr. Jeremias Prophetendienst begann also 626 v. Chr."] },
      { number: 3, text: "und dann weiter in der Zeit des Königs Jojakim Ben-Joschija* bis zum Ende der Regierung des Königs Zidkija Ben-Joschija*, als im August* seines elften Regierungsjahrs die Bevölkerung Jerusalems verschleppt wurde.", footnotes: ["Jojakim regierte von 609-598 v. Chr. Vor ihm hatte Joahas drei Monate regiert und nach ihm Jojachin ebenfalls drei Monate.", "Zidkija regierte von 597-586 v. Chr.", "August. Wörtlich: im 5. Monat. Im Jahr 586 v.Chr. Zum Datum siehe unter Schaltmonat im Vorwort des Übersetzers."] },
      { number: 4, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Die Berufung Jeremias" },
      { number: 5, text: "\"Noch bevor ich dich im Mutterleib formte, hatte ich dich erwählt. / Noch ehe du geboren wurdest, hatte ich dich geweiht: / Zum Propheten für die Völker bist du bestimmt!\"" },
      { number: 6, text: "Doch ich erwiderte: \"Ach mein Herr, Jahwe! Ich kann doch nicht reden, ich bin ja noch so jung!\"" },
      { number: 7, text: "Da sagte Jahwe zu mir: \"Sag nicht, ich bin zu jung! Geh, wohin ich dich sende, und rede, was ich dir befehle!" },
      { number: 8, text: "Hab keine Angst vor den Menschen, denn ich bin mit dir und beschütze dich, spricht Jahwe.\"" },
      { number: 9, text: "Dann berührte Jahwe meine Lippen mit seiner Hand und sagte: \"Hiermit lege ich meine Worte in deinen Mund." },
      { number: 10, text: "Pass auf:Von heute an bist du damit betraut, / in Königreichen und Völkern / auszureißen und abzureißen, / zu vernichten und zu verwüsten, / zu bauen und zu pflanzen.\"" },
      { number: 11, text: "Wieder kam das Wort Jahwes zu mir: \"Was siehst du, Jeremia?\" – \"Einen Mandelzweig*\", erwiderte ich.", heading: "Zwei Visionen", footnotes: ["Der Mandelbaum blüht im Frühjahr als erster von allen Bäumen und scheint im Winter gar nicht \"geschlafen\" zu haben."] },
      { number: 12, text: "\"Du hast richtig gesehen\", sagte Jahwe. \"Denn ich wache* über mein Wort, damit geschieht, was ich sage.\"", footnotes: ["ich wache. Das hebräische Wort für wachen (schoked) klingt ähnlich wie das für Mandelbaum (schaked)."] },
      { number: 13, text: "Das Wort Jahwes kam noch einmal zu mir: \"Was siehst du?\" – \"Ich sehe einen siedenden Kessel\", sagte ich, \"sein Rand neigt sich von Norden her gegen mich.\"" },
      { number: 14, text: "Da sagte Jahwe zu mir: \"Von Norden her ergießt sich das Unheil über alle Bewohner dieses Landes." },
      { number: 15, text: "Ja, ich rufe alle Stämme des Nordens herbei\", spricht Jahwe, \"dass ihre Könige kommen und ihre Throne ringsum an die Eingänge der Tore Jerusalems stellen und um die Mauern aller anderen Städte Judas." },
      { number: 16, text: "Dann werde ich mein Urteil über die Judäer sprechen und sie strafen für all das Böse, das sie getan haben: Sie haben mich verlassen und anderen Göttern Rauchopfer gebracht, sie haben das Werk ihrer eigenen Hände angebetet." },
      { number: 17, text: "Du aber mach dich bereit, steh auf und sag ihnen alles, was ich dir auftrage! Hab keine Angst vor ihnen, sonst mache ich dir vor ihnen Angst." },
      { number: 18, text: "Pass auf! Ich mache dich heute zu einer befestigten Stadt, einer eisernen Säule, einer stählernen Mauer gegen das ganze Land, gegen seine Könige und Beamten, gegen seine Priester und gegen das Volk." },
      { number: 19, text: "Sie werden gegen dich kämpfen, dich aber nicht bezwingen, denn ich bin mit dir, um dich zu retten\", spricht Jahwe." },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Auf Untreue folgt Gericht (2-6)\nDas treulose Volk" },
      { number: 2, text: "\"Geh und ruf es Jerusalem in die Ohren: So spricht Jahwe:'Ich denke an deine Jugendtreue, / an die Liebe deiner Brautzeit, / wie du mir folgtest in der Wüste, / in dem Land, wo gar nichts wächst." },
      { number: 3, text: "Israel war Jahwe geweiht, / es war die Erstfrucht seiner Ernte. / Wer davon aß, machte sich schuldig, / Unglück kam über ihn', spricht Jahwe." },
      { number: 4, text: "Hört das Wort Jahwes, ihr Nachkommen Jakobs, / ihr Sippen vom Haus Israel!" },
      { number: 5, text: "So spricht Jahwe: / Welches Unrecht fanden eure Väter an mir, / dass sie sich von mir entfernten, / dass sie dem Nichts nachliefen / und so selbst zu Nichts geworden sind." },
      { number: 6, text: "Sie fragten nicht: / 'Wo ist Jahwe, der uns aus Ägypten geführt, / der uns den Weg wies durch die Wüste, / durch ein wildes, zerklüftetes Land, / ein Land des Durstes und des Dunkels, / das niemand bewohnt und niemand durchzieht.'" },
      { number: 7, text: "Ich brachte euch ins Gartenland, / damit ihr dessen Frucht und Güter genießt. / Doch kaum wart ihr dort, habt ihr es besudelt, / habt mir mein Eigentum zum Abscheu gemacht." },
      { number: 8, text: "Die Priester fragten nicht: 'Wo ist Jahwe?' / Die Hüter des Gesetzes kannten mich nicht, / die Hüter des Volkes brachen mit mir. / Die Propheten weissagten für Baal*, / liefen den Nichtsnutzen nach.", footnotes: ["Baal bedeutet \"Herr\" oder \"Gebieter\". Er wurde als Fruchtbarkeitsgott in Kanaan verehrt."] },
      { number: 9, text: "Darum klage ich euch weiterhin an, spricht Jahwe. / Auch eure Enkel verklage ich noch!" },
      { number: 10, text: "Fahrt doch zu den Inseln der Kittäer*, / schaut euch dort um! / Schickt Leute nach Kedar*, / erkundigt euch genau! / Ist jemals so etwas geschehen?", footnotes: ["Die Kittäer bewohnten Zypern und die griechischen Inseln.", "Kedar. Arabischer Stamm südöstlich von Israel. Nomadisierende Händler, als Kämpfer gefürchtet."] },
      { number: 11, text: "Hat je ein Volk seine Götter getauscht? / Dabei sind es noch nicht einmal Götter! / Doch mein Volk tauscht seine Herrlichkeit ein / gegen das, was gar nichts nützen kann!" },
      { number: 12, text: "Schaudert, ihr Himmel, / bebt vor Entsetzen, / spricht Jahwe." },
      { number: 13, text: "Denn mein Volk hat doppeltes Unrecht verübt: Mich verließen sie, / die Quelle lebendigen Wassers, / um sich Regengruben auszuhauen, / Zisternen mit Rissen, / die das Wasser nicht halten." },
      { number: 14, text: "Ist Israel denn ein Sklave, / gar ein Sklave von Geburt? / Warum ist es zur Beute geworden? /" },
      { number: 15, text: "Junglöwen brüllten über ihm. / Sie haben sein Land zur Wüste gemacht. / Seine Städte sind verbrannt und menschenleer. /" },
      { number: 16, text: "Nun kommen auch noch die Ägypter / von Memphis* und Tachpanhes* / und weiden dir den Scheitel ab.", footnotes: ["Memphis war die alte Hauptstadt Ägyptens, 21 km südlich vom heutigen Kairo.", "Tachpanhes war eine Grenzfestung gegen Syrien und Israel in der Nähe von Pelusium im äußersten Nordosten von Ägypten."] },
      { number: 17, text: "Das hast du dir selbst zuzuschreiben, / denn du hast Jahwe, deinen Gott, verlassen, / als er dich noch auf seinem Weg führte." },
      { number: 18, text: "Was nützt es jetzt, nach Ägypten zu laufen? / Willst du das Nilwasser trinken? / Was nützt es, nach Assyrien zu gehen? / Willst du aus dem Euphrat schöpfen?" },
      { number: 19, text: "Deine Bosheit bringt dich ins Unglück, / dein treuloses Treiben führt die Strafe herbei. / Sieh doch ein, wie schlimm und bitter es ist, / Jahwe, deinen Gott, zu verlassen / und keine Ehrfurcht zu haben vor mir, / spricht Jahwe, der Herr, / der allmächtige Gott*.", footnotes: ["der allmächtige Gott. Hebräisch: Zebaoth, das heißt \"Heere\" oder \"Kriege\". In der LXX wird der Begriff immer mit \"pantokrator\", \"Allherrscher\" oder \"Allmächtiger\" wiedergegeben."] },
      { number: 20, text: "Denn von jeher zerbrachst du dein Joch*, / sprengtest deine Fesseln. / 'Ich will nicht dienen!', sagtest du / und legtest dich als Hure / auf jeden hohen Hügel / und unter jeden grünen Baum.", footnotes: ["Ein Joch war der Holzrahmen, mit dem zwei Rinder vor Wagen oder Pflug gespannt wurden. Im übertragenen Sinn bedeutet es die Herrschaft, unter der man steht."] },
      { number: 21, text: "Ich hatte dich als Edelrebe gepflanzt, / du warst ein erlesenes Gewächs. / Wie hast du dich verwandelt! / Ich sehe nur noch entartete Reben, / einen fremden, verwilderten Weinstock." },
      { number: 22, text: "Auch wenn du dich mit Lauge wäschst, / wenn du noch so viel Waschpaste nimmst, / der Schmutz deiner Schuld bleibt immer vor mir, / spricht Jahwe, der Herr." },
      { number: 23, text: "Wie kannst du nur sagen: / 'Ich bin nicht befleckt, / hatte nichts mit Götzen* zu tun!'? / Schau auf dein Treiben im Tal*, / denk über deine Taten nach! / Du brünstiges Kamel / läufst ständig hin und her.", footnotes: ["Götzen. Wörtlich: Baalen. Baal bedeutet \"Herr\" oder \"Gebieter\" und war der Name des kanaanäischen Fruchtbarkeitsgottes. In der Mehrzahlform sind allgemein die fremden Götter gemeint oder die vielen Baalsheiligtümer im Land.", "im Tal. Gemeint ist wohl das Hinnom-Tal bei Jerusalem, ein Zentrum götzendienerischen Treibens."] },
      { number: 24, text: "Die wilde Eselin, / an die Wüste gewöhnt: / Vor lauter Gier schnappt sie nach Luft, / ihre Brunst ist nicht zu bremsen. / Wer sie sucht, muss sich nicht müde laufen, / in ihrer Brunstzeit findet er sie." },
      { number: 25, text: "Erspare deinem Fuß die Blöße, / deiner Kehle den Durst! / Doch du sagst: 'Nein, verdammt noch Mal! / Ich liebe die Fremden, / ich muss ihnen nach!'" },
      { number: 26, text: "Wie ein ertappter Dieb beschämt dasteht, / so muss sich das Haus Israel schämen: / alle, die dazu gehören, / ihre Könige und hohen Beamten, / ihre Priester und ihre Propheten." },
      { number: 27, text: "Sie sagen zum Holzstück: 'Du bist mein Vater!', / zur Steinfigur: 'Du hast mich geboren!' / Denn mir haben sie den Rücken gekehrt / und nicht das Gesicht. / Doch wenn das Unglück sie trifft, dann schreien sie: / 'Steh auf und rette uns!'" },
      { number: 28, text: "Wo sind denn deine Götter, / die du dir selber machst? / Lass sie doch aufstehen, / falls sie helfen können, / wenn das Unglück kommt. / Denn so zahlreich wie deine Städte / sind deine Götter, Juda!" },
      { number: 29, text: "Warum klagt ihr mich an? / Ihr habt doch mit mir gebrochen, / spricht Jahwe." },
      { number: 30, text: "Vergeblich schlug ich eure Söhne, / sie ließen sich nicht erziehen. / Euer eigenes Schwert / fraß eure Propheten / wie ein hungriger Löwe." },
      { number: 31, text: "O gegenwärtiges Geschlecht! / Beachtet doch das Wort Jahwes! / War ich für Israel denn eine Wüste, / war ich ein finsteres Land? / Warum sagt mein Volk: / 'Los, wir gehen! / Wir kommen nicht zu dir zurück.'" },
      { number: 32, text: "Vergisst ein Mädchen seinen Schmuck, / eine Braut ihren prächtigen Gürtel? / Doch mein Volk vergaß mich / schon unendlich lange Zeit." },
      { number: 33, text: "In der Jagd nach Liebhabern bist du unübertrefflich. / So hast du dich an deine Verbrechen gewöhnt." },
      { number: 34, text: "Ja, an deinen Säumen findet sich das Lebensblut schuldloser Armer, / und die hast du nicht beim Einbruch ertappt! / Der Fluch all dieser Taten wird dich sicher treffen!" },
      { number: 35, text: "Und bei allem sagst du immer noch: 'Ich bin doch ohne Schuld! Er ist ja nicht mehr zornig auf mich!' Deshalb mache ich dir den Prozess." },
      { number: 36, text: "Warum hast du es nur so eilig, deine Politik zu verändern? / Ägypten wird dich genauso enttäuschen, / wie dich Assyrien enttäuschte." },
      { number: 37, text: "Auch von dort kommst du ratlos zurück, / die Hände vorm Gesicht. / Jahwe hat verworfen / auf die du vertraust. / Mit ihnen gelingt es dir nicht.\"" },
    ] },
    { number: 3, verses: [
      { number: 1, text: "Er sagt: \"Wenn ein Mann seine Frau verstößt / und sie geht von ihm weg / und wird die Frau eines anderen, / darf sie dann wieder zu ihm kommen? / Würde dieses Land nicht ganz und gar entweiht? / Doch du hast viele Liebhaber gehabt! / Und du willst zu mir zurück?\", / spricht Jahwe.", heading: "Bundesbruch ist Ehebruch" },
      { number: 2, text: "\"Schau doch die kahlen Höhen an: / Wo trieb man es noch nicht mit dir? / An allen Wegen hast du auf sie gewartet / wie ein Nomade in der Wüste. / Dein Huren hat das Land entweiht / und deine Bosheit ebenfalls." },
      { number: 3, text: "Darum fiel auch kein Regen im Herbst / und auch im Frühjahr nicht. / Doch du hattest die Stirn einer Hure, / du wolltest dich nicht schämen." },
      { number: 4, text: "Jetzt freilich rufst du mir zu: 'Du bist doch mein Vater, / mein Freund aus meiner Jugendzeit!" },
      { number: 5, text: "Willst du denn ewig böse / und immer nachtragend sein?' / Ja, so hast du geredet und Böses getan / und meintest, dich durchzusetzen.\"" },
      { number: 6, text: "Als König Joschija* regierte, sagte Jahwe zu mir: \"Hast du gesehen, was Israel, diese treulose Frau, getan hat? Sie ist auf jede Anhöhe gestiegen, hat sich unter jeden grünen Baum gelegt und sich dort mit anderen eingelassen.", footnotes: ["Joschija regierte von 640-609 v.Chr."] },
      { number: 7, text: "Ich dachte: 'Wenn sie genug davon hat, wird sie wieder zu mir zurückkehren.' Aber sie kam nicht zurück. Und ihre treulose Schwester Juda sah zu." },
      { number: 8, text: "Ich gab Israel, dieser treulosen Frau, deshalb den Scheidebrief und schickte sie weg. Doch ihre treulose Schwester Juda ließ sich nicht abschrecken, sondern ließ sich selbst mit anderen ein." },
      { number: 9, text: "So kam es, dass sie durch ihre leichtfertige Unmoral das Land entweihte. Mit Steinmalen und Holzfiguren hat sie Ehebruch getrieben." },
      { number: 10, text: "Und nach all dem ist Juda, die treulose Schwester, immer noch nicht mit ihrem ganzen Herzen zu mir zurückgekehrt. Es war nur geheuchelt, spricht Jahwe.\"" },
      { number: 11, text: "Weiter sagte Jahwe zu mir: \"Das abtrünnige Israel steht gerechter da als das treulose Juda." },
      { number: 12, text: "Geh und rufe folgende Worte in Richtung Norden:'Du treuloses Israel, / kehre zurück!', spricht Jahwe. / 'Ich blicke nicht mehr finster auf dich, / denn ich bin gütig', spricht Jahwe. / 'Ich werde nicht ewig nachtragend sein." },
      { number: 13, text: "Doch du musst deine Schuld einsehen: / Du hast Jahwe, deinem Gott, die Treue gebrochen / und bist fremden Göttern nachgelaufen. / Unter jedem grünen Baum hast du es getan, / aber auf meine Stimme hast du nicht gehört', / spricht Jahwe.\"" },
      { number: 14, text: "\"Kehrt doch um, ihr abtrünnigen Kinder!\", spricht Jahwe, \"denn ihr gehört doch zu mir! Ich hole euch – einen aus einer Stadt und zwei aus einer Sippe und werde euch nach Zion bringen." },
      { number: 15, text: "Dann werde ich euch Hirten geben, die nach meinem Herzen sind. Sie werden euch hüten mit Einsicht und Verstand.\"" },
      { number: 16, text: "Weiter sagte Jahwe: \"Wenn ihr euch dann im Land wieder vermehrt und fruchtbar seid, wird man nicht mehr nach der Bundeslade Jahwes fragen. Sie wird keinem mehr in den Sinn kommen, niemand denkt mehr an sie, und keiner vermisst sie. Man stellt auch keine neue wieder her." },
      { number: 17, text: "Dann wird man Jerusalem als den Thron Jahwes bezeichnen, und alle Völker werden sich dort zum Namen Jahwes hin versammeln. Sie werden nicht mehr dem Trieb ihres bösen Herzens folgen." },
      { number: 18, text: "Dann werden die Leute von Juda sich mit denen von Israel zusammenschließen. Miteinander werden sie aus dem Land im Norden in das Land zurückkehren, das ich euren Vorfahren als bleibenden Besitz gegeben habe.\"" },
      { number: 19, text: "\"Ich war entschlossen, / dir die Ehrenstellung eines Sohnes zu geben, / dazu ein wunderschönes Land, / den herrlichsten Besitz, / den die Völker nur kennen. / Ich dachte, ihr würdet mich nun Vater nennen, / euch nie wieder abwenden von mir.", heading: "Ruf zur Umkehr" },
      { number: 20, text: "Doch wie eine Frau ihren Mann betrügt, / so habt ihr Israeliten mir die Treue gebrochen\", / spricht Jahwe." },
      { number: 21, text: "Auf kahlen Höhen hört man eine Stimme, / ein Weinen, / ein Flehen der Israeliten. / Sie haben ihren Weg verfehlt / und Jahwe, ihren Gott, vergessen." },
      { number: 22, text: "\"Kehrt doch um, ihr abtrünnigen Kinder! / Ich will eure Untreue heilen!\" / \"Hier sind wir, Jahwe, / wir kommen zu dir; / denn du bist unser Gott." },
      { number: 23, text: "Ja, es war alles Betrug, / was von den Hügeln her kam, / das Toben auf den Bergen. / Ja, die Rettung Israels / kommt nur von Jahwe, unserem Gott." },
      { number: 24, text: "Der schändliche Götze hat alles gefressen, / was unsere Väter erarbeitet haben: / ihre Schafe und Rinder, / ihre Söhne und Töchter. / Es geschah von unserer Jugend an." },
      { number: 25, text: "Wir liegen in unserer Schmach / und unsere Schande bedeckt uns. / Wir haben uns versündigt / an Jahwe, unserem Gott, / wir und unsere Väter, / von unserer Jugend an bis jetzt. / Wir haben nicht auf ihn gehört, / auf Jahwe, unseren Gott.\"" },
    ] },
    { number: 4, verses: [
      { number: 1, text: "\"Wenn du umkehrst, Israel\", spricht Jahwe, \"wenn du zu mir umkehrst und mir deine Scheusale aus den Augen schaffst, so wirst du nicht mehr umherirren." },
      { number: 2, text: "Und wenn du beim Schwören ehrlich sagst: 'So wahr Jahwe lebt!' und aufrichtig zu deinem Wort stehst, dann werden auch die anderen Völker sich in meinem Namen segnen und stolz darauf sein, mich zu kennen.\"" },
      { number: 3, text: "Denn so spricht Jahwe zu den Männern von Juda und Jerusalem:\"Pflügt euch Neuland / und sät nicht unter Dornen!" },
      { number: 4, text: "Beschneidet* euch so, wie es Jahwe gefällt, / und entfernt die Vorhaut eures Herzens, / ihr Leute von Juda und Jerusalem. / Sonst bricht mein Zorn wie Feuer los / über euer boshaftes Tun; / er brennt, / und niemand kann ihn löschen.\"", footnotes: ["beschneiden. Siehe 1. Mose 17,9-14!"] },
      { number: 5, text: "\"Verkündigt es in Juda, / meldet es Jerusalem: / Stoßt ins Horn auf dem Land! / Schreit aus voller Kehle: / 'Bringt euch in Sicherheit! / Hinein in die befestigten Städte!", heading: "Der Feind aus dem Norden" },
      { number: 6, text: "Stellt Wegweiser auf nach Zion! / Vorwärts, bleibt nicht stehen!' / Ich bringe Tod und Verderben über euch, / ich führe den Feind aus dem Norden herbei!" },
      { number: 7, text: "Ein Löwe kommt aus seinem Dickicht, / der Völkervernichter bricht auf. / Er verlässt seinen Ort, / um dein Land zur Wüste zu machen. / Deine Städte werden veröden, / weil keiner darin wohnt.\"" },
      { number: 8, text: "Darum zieht den Trauersack an, / jammert und heult, / weil die Zornglut Jahwes / sich nicht von uns abgewandt hat." },
      { number: 9, text: "\"Der Tag wird kommen\", spricht Jahwe, \"an dem der König und seine Oberen den Mut verlieren. Die Priester werden entsetzt sein und die Propheten verstört.\"" },
      { number: 10, text: "Da sagte ich: \"Ach Herr, Jahwe! Du hast dieses Volk und Jerusalem bitter getäuscht. Du hast uns Frieden angekündigt, während wir das Schwert im Nacken haben.\"" },
      { number: 11, text: "\"Dann werde ich diesem Volk und Jerusalem sagen:'Ein Glutwind von den kahlen Wüstenhöhen / stürzt sich auf mein Volk herab. / Er ist nicht zum Worfeln geeignet, / zum Reinigen von Getreide," },
      { number: 12, text: "dafür ist er viel zu stark. / Der Sturm kommt von mir / und bringt euch das Urteil meines Gerichts." },
      { number: 13, text: "Seht, wie Wetterwolken kommen sie! / Ihre Streitwagen sind wie ein Sturm, / ihre Pferde schneller als Adler. / Weh uns, wir sind verloren!" },
      { number: 14, text: "Jerusalem, wasch dir das Böse vom Herzen, / damit du gerettet wirst! / Wie lange noch wohnen die bösen Gedanken in dir?" },
      { number: 15, text: "Horch nur, man meldet aus Dan, / verkündet Unheil vom Bergland Efraïms*!'", footnotes: ["Efraïm war der einflussreichste Stamm im Nordreich Israel. Der Name konnte deshalb auch für das ganze Nordreich stehen."] },
      { number: 16, text: "Lasst es die Völker wissen, / verkündet es in Jerusalem: / Belagerer kommen aus fernem Land, / Geschrei drängt gegen Judas Städte." },
      { number: 17, text: "Wie Wächter auf dem Feld / stehen sie rings um die Stadt, / denn gegen mich hat sie sich aufgelehnt\", spricht Jahwe." },
      { number: 18, text: "Das hat dein Tun und Treiben dir gebracht. / Deine Bosheit stürzte dich in dieses Leid. / Nun ist es bitter und dringt an dein Herz!", heading: "Jeremia leidet mit seiner Stadt" },
      { number: 19, text: "Diese Qual in meinen Eingeweiden! / Ich krümme mich vor Schmerz. / Mein Herz tobt, / dass es fast zerspringt. / Ich kann nicht mehr schweigen. / Ich höre schon den Hörnerschall, / das Geschrei in der Schlacht." },
      { number: 20, text: "Niederlage und Zerstörung ruft man aus. / Das ganze Land wird verwüstet. / Plötzlich sind die Zelte umgestürzt, / im Nu alle Decken zerfetzt." },
      { number: 21, text: "Wie lange noch muss ich das Feldzeichen sehen, / den Lärm des Hornes ertragen?" },
      { number: 22, text: "\"Wie verblendet ist mein Volk, / mich, Jahwe, kennen sie nicht! / Närrische Kinder ohne Verstand! / Sie wissen wie man Böses tut, / doch Gutes zu tun verstehen sie nicht.\"" },
      { number: 23, text: "Ich sah die Erde an – sie war formlos und leer. / Ich schaute zum Himmel – er war ohne Licht." },
      { number: 24, text: "Ich sah auf die Berge, / sie erzitterten, / die Hügel erbebten." },
      { number: 25, text: "Ich sah nach den Menschen, / da war keiner mehr. / Und alle Vögel waren fort." },
      { number: 26, text: "Ich sah nach dem fruchtbaren Land, / es war eine Wüste. / Und alle Städte waren zerstört, / zerstört von Jahwe, / von der Glut seines Zorns." },
      { number: 27, text: "Denn so spricht Jahwe: \"Zur Öde wird das ganze Land, / doch vollkommen vernichte ich es nicht." },
      { number: 28, text: "Darüber trauert die Erde, / der Himmel wird schwarz. / Denn ich habe gesprochen, / ich habe entschieden und bereue es nicht. / Es bleibt nun dabei!\"" },
      { number: 29, text: "Vor dem Lärm der Reiter / und vor den Bogenschützen / flüchtet das Volk aus der Stadt. / Sie ersteigen Felsen und kriechen in Höhlen, / verstecken sich im Dickicht. / Die Städte sind verlassen, / kein Mensch wohnt mehr darin." },
      { number: 30, text: "Du Stadt, / dem Untergang geweiht, / was wirst du tun? / Auch wenn du dich kleidest in leuchtendes Rot, / wenn du dich mit Goldschmuck behängst / und dir die Augen größer schminkst: / Du machst dich vergeblich schön! / Deine Liebhaber haben dich satt. / Sie trachten dir jetzt nach dem Leben." },
      { number: 31, text: "Denn ich höre schon das Schreien. / Es klingt wie von einer Frau, / die zum ersten Mal in Wehen liegt. / Es ist die Stimme der Zionsstadt. / Sie keucht, / sie breitet ihre Hände aus: / \"O weh mir, / sie bringen mich um!\"" },
    ] },
    { number: 5, verses: [
      { number: 1, text: "\"Zieht durch Jerusalems Straßen, / schaut euch auf allen Plätzen um, / erkundigt euch genau, ob es einen dort gibt, / nur einen, der das Rechte tut, / nur einen, der nach Treue strebt. / Dann will ich ihr verzeihn!", heading: "Keine Vergebung mehr!" },
      { number: 2, text: "Doch selbst wenn sie sagen: / 'So wahr Jahwe lebt!', / schwören sie falsch.\"" },
      { number: 3, text: "Jahwe, kommt es dir nicht auf Wahrhaftigkeit an? / Du hast sie geschlagen, doch es schmerzte sie nicht. / Du hast sie fast vernichtet, doch sie lernte nichts daraus. / Ihre Stirn ist härter als Stein, / sie weigerte sich umzukehren." },
      { number: 4, text: "Ich dachte: So sind nur die einfachen Leute. / Sie kennen den Weg von Jahwe nicht, / und nicht die Forderungen ihres Gottes." },
      { number: 5, text: "Ich will nun zu den Großen gehen / und mit ihnen reden. / Denn sie kennen den Weg Jahwes, / die Forderungen ihres Gottes. / Doch gerade sie haben das Joch zerbrochen, / sie alle haben die Fesseln gesprengt." },
      { number: 6, text: "\"Darum schlägt sie der Löwe aus dem Wald, / ein Wolf der Steppe überwältigt sie, / ein Leopard lauert vor ihrer Stadt. / Jeder, der herauskommt, wird zerrissen. / Denn zahlreich sind ihre Verbrechen, / schwer wiegt ihre Untreue." },
      { number: 7, text: "Weshalb sollte ich dir vergeben? / Deine Kinder haben mich verlassen. / Sie schwören bei Göttern, die gar keine sind. / Nachdem ich sie gesättigt hatte, / trieben sie nur Ehebruch / und laufen scharenweise ins Bordell." },
      { number: 8, text: "Fette, geile Hengste sind sie geworden, / jeder wiehert nach der Nachbarsfrau." },
      { number: 9, text: "Soll ich das noch hinnehmen?\", spricht Jahwe. / \"Soll ich mich an solch einem Volk nicht rächen?\"" },
      { number: 10, text: "\"Hinauf also auf seine Mauern! Verwüstet den Weinberg! Doch vernichtet ihn nicht ganz! Reißt seine Ranken ab, denn Jahwe gehören sie nicht!" },
      { number: 11, text: "Die Leute von Israel und Juda sind mir völlig untreu geworden\", spricht Jahwe." },
      { number: 12, text: "\"Sie haben Jahwe verleugnet, sie haben gesagt: 'Er ist nicht da! Kein Unglück wird über uns kommen, Krieg und Hunger sehen wir nicht." },
      { number: 13, text: "Die Propheten reden ja nur Wind, das Wort Jahwes ist nicht in ihnen, was sie sagen, soll sie selber treffen!'\"" },
      { number: 14, text: "Darum spricht Jahwe, der allmächtige Gott: \"Weil man solche Reden führt, sorge ich dafür, dass meine Worte in dir zu einem Feuersturm werden. Und dieses Volk lasse ich das Brennholz sein, das vom Feuer verzehrt wird.\"" },
      { number: 15, text: "\"Seht, ich bringe über euch / ein weit entferntes Volk, / ihr Israeliten\", spricht Jahwe. / \"Es ist ein uraltes Volk, / ein unverwüstlicher Stamm, / ein Volk, dessen Sprache ihr nicht kennt, / mit dem ihr euch nicht verständigen könnt." },
      { number: 16, text: "Sein Köcher ist wie ein offenes Grab, / seine Soldaten erfahrene Kämpfer." },
      { number: 17, text: "Es verzehrt deine Ernte und dein Brot, / es frisst deine Söhne und Töchter. / Es verzehrt dein Schaf und dein Rind, / den Weinstock und den Feigenbaum. / Es zerstört deine Festungen, / auf die du vertraust, mit dem Schwert.\"" },
      { number: 18, text: "\"Doch auch dann lösche ich euch noch nicht völlig aus\", spricht Jahwe." },
      { number: 19, text: "\"Wenn sie dann fragen: 'Weshalb hat uns Jahwe, unser Gott, dies alles angetan?', so antworte ihnen: 'Genauso wie ihr mich verlassen und im eigenen Land fremden Göttern gedient habt, so werdet ihr Fremden dienen müssen in einem Land, das euch nicht gehört!'\"" },
      { number: 20, text: "\"Sagt das den Nachkommen Jakobs, / lasst es hören in Juda:" },
      { number: 21, text: "Höre das, du Volk ohne Sinn und Verstand. / Augen habt ihr, seht aber nicht, / Ohren habt ihr, hört aber nicht.*", footnotes: ["Wird im Neuen Testament von Jesus Christus zitiert: Markus 8,18."] },
      { number: 22, text: "Solltet ihr mich nicht fürchten\", / spricht Jahwe, / \"nicht zittern und beben vor mir? / Ich habe dem Meer eine Grenze gesetzt, / eine Schranke, die es nie überschreiten wird. / Mag es auch toben, es richtet nichts aus, / seine Wellen kommen nicht darüber hinaus." },
      { number: 23, text: "Aber dieses Volk hat ein störrisches, trotziges Herz. / Sie wandten sich ab und gingen davon." },
      { number: 24, text: "Sie haben sich nicht etwa gesagt: / 'Lasst uns doch Jahwe fürchten, unseren Gott, / der uns den Regen gibt im Herbst / und im Frühjahr zur richtigen Zeit, / der uns die Wochen der Ernte erhält.'" },
      { number: 25, text: "Eure Vergehen haben das verhindert, / eure Sünden haben euch das Gute verwirkt." },
      { number: 26, text: "Ja, es gibt Gottlose in meinem Volk. / Wie Vogelsteller ducken sie sich, / sie stellen Fallen auf und fangen Menschen." },
      { number: 27, text: "Wie Käfige voller Vögel / sind ihre Häuser voller Gaunergut. / So wurden sie groß und reich. /" },
      { number: 28, text: "Sie wurden fett und voll, / ihre Bosheit übertrifft jedes Maß. / Um das Recht kümmern sie sich nicht, / für das Recht der Waisen treten sie nicht ein, / den Rechtsanspruch der Armen setzen sie nicht durch." },
      { number: 29, text: "Sollte ich das das nicht ahnden?\", spricht Jahwe. / \"Muss ich mich nicht an solch einem Volk rächen?" },
      { number: 30, text: "Entsetzliches, Abscheuliches geschieht im Land:" },
      { number: 31, text: "Die Propheten weissagen falsch, / die Priester herrschen eigenmächtig, / und mein Volk liebt es so. / Was aber werdet ihr am Ende tun?\"" },
    ] },
    { number: 6, verses: [
      { number: 1, text: "Flieht, ihr Leute von Benjamin, / flieht aus Jerusalem! / Blast das Horn in Tekoa*, / gebt Rauchzeichen über Bet-Kerem*! / Von Norden droht Unheil, / gewaltiger Zusammenbruch.", heading: "Das Volk aus dem Norden", footnotes: ["Tekoa war der Heimatort des Propheten Amos. Das Städtchen lag 16 km südlich von Jerusalem.", "Bet-Kerem lag 5 km südlich von Jerusalem."] },
      { number: 2, text: "Die verwöhnte Schöne, / die Tochter Zion*! / Ich vernichte die Stadt. /", footnotes: ["Zion. Poetischer Ausdruck für Jerusalem."] },
      { number: 3, text: "Hirten mit Herden kommen über sie / und weiden sie ab, / jeder seinen Bereich. / Ihre Zelte stehen ringsherum." },
      { number: 4, text: "\"Auf, zum Kampf gegen die Stadt! / Noch am Mittag schlagen wir los!\" – \"Zu spät, die Zeit reicht nicht aus, / es wird ja schon dunkel!\"" },
      { number: 5, text: "\"Los! Greifen wir an in der Nacht, / zerstören wir ihre Paläste!\"" },
      { number: 6, text: "Denn so sprach Jahwe, der allmächtige Gott: / \"Fällt Bäume und baut damit die Rampe gegen Jerusalem! / Das ist die Stadt, die Strafe verdient, / denn sie ist voll mit Bedrückung." },
      { number: 7, text: "Wie ein Brunnen Wasser sprudelt, / so sprudelt sie die Bosheit aus. / Man hört von Raub und Gewalt, / man sieht nur Weh und Wunden!" },
      { number: 8, text: "Lass dich warnen, Jerusalem, / sonst trenne ich mich von dir / und mache dich zur Wüste, / einem unbewohnten Land!\"" },
      { number: 9, text: "So spricht Jahwe, / der allmächtige Gott: /\"Wie am Weinstock wird man Nachlese halten / an dem, was von Israel übrig bleibt. / Man legt noch einmal Hand an, / wie ein Winzer, der die Reben durchgeht!\"" },
      { number: 10, text: "\"Ach, mit wem soll ich noch reden, / wen noch warnen, dass sie hören? / Ihr Ohr ist verschlossen, / sie können nicht hören. / Das Wort Jahwes empfinden sie als Hohn, / sie wollen es nicht haben." },
      { number: 11, text: "Auch ich bin nun von Jahwes Glut erfüllt / und halte sie nicht mehr zurück.\" – \"Sie kommt auf das Kind, das auf der Straße spielt, / und auf die Runde der jungen Männer. / Getroffen werden Mann und Frau, / alte Menschen, Hochbetagte." },
      { number: 12, text: "Ihre Häuser nehmen andere in Besitz, / ihre Felder und Frauen dazu, / denn ich erhebe meine Hand / gegen die Bewohner des Landes\", / spricht Jahwe." },
      { number: 13, text: "\"Denn vom Kleinsten bis zum Größten / raffen alle Raub. / Vom Propheten bis zum Priester / begehen alle Betrug." },
      { number: 14, text: "Die schwere Wunde meines Volkes / behandeln sie nur äußerlich. / 'Heile, heile, Segen', sagen sie, / aber nichts und niemand ist heil.\"" },
      { number: 15, text: "\"Schämen müssten sie sich wegen ihres schändlichen Treibens. Aber sie denken gar nicht daran. Sie kennen keine Scham. Deshalb werden sie fallen, wenn alles fällt. Und wenn ich komme, um sie zur Rechenschaft zu ziehen, werden sie stürzen\", spricht Jahwe." },
      { number: 16, text: "So spricht Jahwe: / \"Stellt euch an die Wege und schaut, / fragt nach den ewigen Pfaden: / 'Wo ist hier der Weg zum Glück?' / Dann geht ihn und findet Erfüllung!\"\"Aber sie sagen: 'Wir wollen nicht!'" },
      { number: 17, text: "Ich habe Wächter für euch bestellt. Achtet auf den Hall ihres Horns! Aber sie sagen nur: 'Das tun wir nicht!'" },
      { number: 18, text: "Darum hört es, ihr Völker, erkennt ihr Leute, was jetzt mit ihnen geschieht!" },
      { number: 19, text: "Die ganze Welt soll es hören: Ja, ich bringe Unheil über dieses Volk. Es ist die Folge ihres Denkens, denn sie haben nicht auf meine Worte gehört. Mein Gesetz haben sie abgelehnt.\"" },
      { number: 20, text: "\"Was soll ich mit dem Weihrauch aus Saba, / feinen Gewürzen aus fernem Land? / Eure Brandopfer* gefallen mir nicht, / eure Freudenopfer* sind mir nicht angenehm!\"", footnotes: ["Brandopfer. Bei dieser Opferart wurde das Tier mit Ausnahme der Haut vollständig auf dem Altar verbrannt.", "Beim Freudenopfer wurde im Gegensatz zum Brandopfer nur das Fett auf dem Altar verbrannt. Der größte Teil des Tieres durfte bei einer fröhlichen Opfermahlzeit gemeinsam mit Verwandten und Freunden verzehrt werden."] },
      { number: 21, text: "\"Darum\", spricht Jahwe, \"passt auf! Ich lege diesem Volk jetzt Hindernisse in den Weg, damit Väter und Söhne zusammen darüber stürzen. Nachbar und Freund gehen zugrunde.\"" },
      { number: 22, text: "So spricht Jahwe: / \"Seht, da kommt ein Volk / aus seinem Land im Norden, / eine große Nation macht sich auf / vom äußersten Ende der Erde." },
      { number: 23, text: "Sie kommen mit Bogen und Langschwert, / sind grausam und ohne Erbarmen. / Ihr Lärm ist wie das tosende Meer. / Auf Pferden reiten sie heran, / gerüstet wie ein Mann zum Krieg. / Tochter Zion, es geht gegen dich.\"" },
      { number: 24, text: "\"Wir haben von ihnen gehört, / unsere Arme sind niedergesunken, / die Angst hat uns gepackt / wie die Wehen eine Frau." },
      { number: 25, text: "'Geht ja nicht aufs Feld! / Nur weg von der Straße! / Der Feind hat ein Schwert!' / Schrecken lauern überall.\"" },
      { number: 26, text: "Tochter meines Volkes, / leg den Trauersack an, / wälz dich in der Asche, / trauere wie um den einzigen Sohn! / Stimm die Totenklage an, / denn der Verwüster wird plötzlich über uns sein." },
      { number: 27, text: "\"Zum Prüfer meines Volkes / habe ich dich eingesetzt. / Du sollst sein Verhalten prüfen, / wie man Metalle erkennt und prüft." },
      { number: 28, text: "Sie alle sind schlimmste Rebellen, / sie laufen als Verleumder herum, / hart wie Bronze und Eisen, / alle zusammen Verbrecher." },
      { number: 29, text: "Der Blasebalg ist vom Feuer versengt, / was herauskam war Blei. / Umsonst hat man geschmolzen, / das Böse schied sich nicht aus." },
      { number: 30, text: "Wertloses Silber nennt man sie nun, / denn Jahwe hat sie verworfen.\"" },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Wort Jahwes, das zu Jeremia kam:", heading: "Auf Heuchelei folgt Götzendienst (7-10)\nJeremias erste Tempelrede" },
      { number: 2, text: "Stell dich ins Tor vom Haus Jahwes und rufe: \"Hört das Wort Jahwes, ihr Judäer! Ihr geht durch diese Tore, um Jahwe anzubeten." },
      { number: 3, text: "So spricht Jahwe, der allmächtige Gott Israels: 'Ändert euer Leben und Tun! Nur dann lasse ich euch an diesem Ort bleiben." },
      { number: 4, text: "Verlasst euch nicht auf solche Lügenworte wie: 'Das hier ist der Tempel Jahwes! Es ist der Tempel Jahwes! Jahwes Tempel ist das!'" },
      { number: 5, text: "Denn nur, wenn ihr euer Leben und Tun von Grund auf bessert, wenn ihr wirklich Recht schafft untereinander," },
      { number: 6, text: "wenn ihr Fremde, Waisen und Witwen nicht ausnutzt und hier nicht das Blut unschuldiger Menschen vergießt und wenn ihr nicht den fremden Göttern nachlauft zu eurem eigenen Schaden," },
      { number: 7, text: "nur dann werde ich euch für immer an diesem Ort wohnen lassen, in dem Land, das ich euren Vorfahren gegeben habe.'" },
      { number: 8, text: "'Seht doch ein, dass ihr euch nur auf Lügen verlasst, die euch gar nichts nützen!" },
      { number: 9, text: "Wie? Ihr stehlt und mordet, ihr brecht die Ehe, schwört Meineide, bringt dem Baal Räucheropfer und lauft anderen Göttern nach, die euch gar nichts angehen!" },
      { number: 10, text: "Und dann kommt ihr her und tretet in diesem Haus vor mich hin – in diesem Haus, das meinen Namen trägt – und sagt: 'Wir sind doch gerettet!', um dann weiter all diese Gräuel zu verüben." },
      { number: 11, text: "Ist denn dieses Haus, das meinen Namen trägt, für euch zu einer Räuberhöhle geworden?* – Gut, dann sehe ich es auch so an', spricht Jahwe.", footnotes: ["Wird im Neuen Testament von Jesus Christus zusammen mit Jesaja 56,7 zitiert: Matthäus 21,13; Markus 11,17; Lukas 19,46."] },
      { number: 12, text: "'Geht doch zu meiner Stätte in Schilo*, wo ich früher meinen Namen wohnen ließ, und seht euch an, was ich ihr angetan habe wegen der Bosheit meines Volkes Israel!", footnotes: ["Schilo. Nach der Eroberung Kanaans wurde das heilige Zelt in Schilo, 32 km nördlich von Jerusalem, aufgebaut (Josua 18,1). Um das Jahr 1050 v.Chr. wurden die Gebäude, die um das Zelt herum errichtet worden waren, offenbar von den Philistern zerstört."] },
      { number: 13, text: "Nun denn, ihr habt genau das Gleiche getan', spricht Jahwe. 'Ich habe zu euch geredet, habe mich beizeiten aufgemacht, geredet und geredet, aber ihr habt einfach nicht gehört. Ich habe euch gerufen, aber ihr habt nicht geantwortet." },
      { number: 14, text: "Darum werde ich jetzt mit diesem Haus, das meinen Namen trägt und auf das ihr euch verlasst, genauso verfahren wie mit Schilo. Ich werde diesem Ort, den ich euch und euren Vorfahren gegeben habe, dasselbe Schicksal bereiten." },
      { number: 15, text: "Und ich werde euch aus meiner Gegenwart wegschleudern, so wie ich es mit euren Brüdern, den Leuten von Efraïm, getan habe.'\"" },
      { number: 16, text: "\"Du aber, hör auf für dieses Volk zu bitten! Kein Gebet mehr, kein Flehen! Hör auf, in mich zu dringen, denn ich werde nicht auf dich hören!", heading: "Jeremia darf nicht für sein Volk beten" },
      { number: 17, text: "Siehst du nicht, was sie in den Städten Judas und auf den Straßen Jerusalems treiben?" },
      { number: 18, text: "Die Kinder lesen das Holz zusammen, die Väter zünden das Feuer an und die Frauen kneten den Teig und backen Kuchen als Opfer für die Himmelskönigin*. Und anderen Göttern spendet man Trankopfer, nur um mich zu kränken.", footnotes: ["Himmelskönigin war ein babylonischer Name für die Göttin Ischtar (Astarte), eine Liebes- und Fruchtbarkeitsgöttin, deren Verehrung auch kultische Prostitution einschloss."] },
      { number: 19, text: "Doch kränken sie denn mich damit?\", spricht Jahwe. \"Ist es nicht zu ihrem eigenen Schaden?\"" },
      { number: 20, text: "Darum spricht Jahwe, der Herr: \"Passt auf! Ich werde meinen grimmigen Zorn über diesen Ort gießen, über Menschen und Tiere, über die Bäume und die ganze Ernte. Er brennt wie ein Feuer, das niemand löschen kann.\"" },
      { number: 21, text: "So spricht Jahwe, der allmächtige Gott Israels: \"Esst ruhig auch das Fleisch eurer Brandopfer*, wie ihr es bei den Freudenopfern macht.", heading: "Ein Volk, das nicht hört", footnotes: ["Brandopfer. Normalerweise musste es vollständig verbrannt werden."] },
      { number: 22, text: "Denn als ich eure Vorfahren aus Ägypten herausführte, habe ich ihnen nicht befohlen, mir Brand- oder Freudenopfer darzubringen," },
      { number: 23, text: "sondern ich habe ihnen gesagt: 'Gehorcht mir, dann will ich euer Gott sein und ihr seid mein Volk! Lebt nach meinen Weisungen, dann geht es euch gut!'" },
      { number: 24, text: "Aber sie wollten nicht gehorchen, ja, sie hörten noch nicht einmal zu, sondern machten eigensinnig, was sie wollten, und drehten mir den Rücken zu." },
      { number: 25, text: "Von dem Tag an, als eure Vorfahren aus Ägypten zogen, bis heute habe ich immer wieder von neuem meine Diener, die Propheten, zu euch geschickt." },
      { number: 26, text: "Aber keinen von euch hat das gekümmert. Niemand hörte auf mich. Alle blieben starrsinnig und trieben es schlimmer als ihre Väter." },
      { number: 27, text: "Wenn du ihnen das alles vorhältst, werden sie auch auf dich nicht hören. Dein Rufen wird ohne Antwort bleiben." },
      { number: 28, text: "Sag dann zu ihnen: 'Das ist das Volk, das nicht auf Jahwe, seinen Gott, hört und das sich gar nichts sagen lässt. Treue und Wahrheit sind verschwunden, es ist keine Rede mehr davon.'\"" },
      { number: 29, text: "\"Schneid ab dein langes Haar* und wirf es weg. Stimm Trauerlieder auf den kahlen Höhen an, denn Jahwe zürnt dieser Generation. Er hat sie verstoßen, will nichts mehr von ihr wissen. –", heading: "Das Tal der Toten", footnotes: ["dein Langes Haar. Gemeint ist die Tochter Zion."] },
      { number: 30, text: "Ja, die Judäer taten, was mir missfällt\", spricht Jahwe. \"Sie haben ihre Scheusale in das Haus gestellt, das meinen Namen trägt, und haben es so entweiht." },
      { number: 31, text: "Im Hinnomtal haben sie die Opferhöhe des Tofet* errichtet, um ihre Söhne und Töchter dort zu verbrennen, was ich ihnen nie befohlen habe. Niemals ist mir so etwas in den Sinn gekommen!", footnotes: ["Tofet heißt Feuerstelle und meint eine Feuergrube, in die hilflose Kinder geworfen wurden."] },
      { number: 32, text: "Darum passt auf! Es wird die Zeit kommen\", spricht Jahwe, \"da wird man diesen Ort nicht mehr Tofet oder Hinnomtal nennen, sondern Mordtal. Man wird die Toten im Tofet begraben müssen, weil man sonst keinen Platz mehr dazu hat." },
      { number: 33, text: "Die Leichen dieses Volkes werden den Vögeln und den wilden Tieren zum Fraß dienen, und niemand wird sie verscheuchen." },
      { number: 34, text: "In den Städten Judas und den Straßen von Jerusalem wird jeder Jubelruf verstummen. Ich lasse alles Freudengeschrei enden, auch den Ruf von Bräutigam und Braut, denn das Land wird ein einziges Trümmerfeld sein.\"" },
    ] },
    { number: 8, verses: [
      { number: 1, text: "\"Wenn das geschieht\", spricht Jahwe, \"wird man die Knochen der Könige von Juda und die ihrer hohen Beamten, die Knochen der Priester, der Propheten und die der Bewohner von Jerusalem aus ihren Gräbern herausholen." },
      { number: 2, text: "Man wird sie ausbreiten vor Sonne, Mond und dem ganzen Sternenheer, die sie geliebt und denen sie gedient haben, denen sie nachgelaufen sind, die sie befragt haben und vor denen sie sich niederwarfen. Niemand wird die Knochen wieder einsammeln. Sie sollen zum Dünger für die Äcker werden." },
      { number: 3, text: "Und für den Rest von dieser bösen Sippschaft wird der Tod besser als das Leben sein, und zwar überall, wohin ich sie vertreiben werde\", spricht Jahwe, der Allmächtige. \"Und sage ihnen Folgendes: So spricht Jahwe:" },
      { number: 4, text: "'Fällt man denn und steht nicht gleich wieder auf? / Wendet man sich ab und dreht sich nicht wieder um?", heading: "Beispiellose Sturheit" },
      { number: 5, text: "Warum wendet das Volk Jerusalems sich ab / und bleibt in seiner Abkehrhaltung? / Weshalb halten sie am Irrtum fest / und weigern sich zurückzukehren?" },
      { number: 6, text: "Ich habe gehört, was sie sagen – die Wahrheit ist es nicht. / Keiner bereut seine Bosheit und sagt: / Was habe ich nur getan? / Alle stürzen auf ihrem falschen Weg weiter, / stürmen wie Pferde in die Schlacht." },
      { number: 7, text: "Selbst der Storch am Himmel kennt seine Zeiten, / Turteltaube, Kranich und Schwalbe / halten die Frist ihres Heimkommens ein. / Nur mein Volk kennt die Ordnung Jahwes nicht." },
      { number: 8, text: "Wie könnt ihr sagen: Wir wissen Bescheid, / wir haben doch Jahwes Gesetz! / Gewiss! Aber deine Gelehrten / haben es völlig verfälscht." },
      { number: 9, text: "Eure Weisen werden sich schämen, / ertappt und bestürzt. / Ja, sie haben Jahwes Wort verworfen. / Und was für eine Weisheit haben sie nun?" },
      { number: 10, text: "Darum gebe ich Fremden ihre Frauen, / ihre Felder neuen Besitzern. / Denn vom Kleinsten bis zum Größten / wollen sie Gewinn um jeden Preis. / Auch Propheten und Priester / täuschen das Volk." },
      { number: 11, text: "Die schwere Wunde meines Volkes / behandeln sie nur äußerlich. / 'Heile, heile, Segen', sagen sie, / aber nichts und niemand ist heil.\"" },
      { number: 12, text: "\"Schämen müssten sie sich wegen ihres schändlichen Treibens. Aber sie denken gar nicht daran. Sie kennen keine Scham. Deshalb werden sie fallen, wenn alles fällt. Und wenn ich komme, um sie zur Rechenschaft zu ziehen, werden sie stürzen\", spricht Jahwe." },
      { number: 13, text: "\"Will ich bei ihnen ernten\", spricht Jahwe, / \"so sind keine Trauben am Weinstock, / keine Feigen am Baum / und alle Blätter verwelkt. / Da gebe ich sie denen, die sie zertreten!\"" },
      { number: 14, text: "\"Wozu sitzen wir herum? / Sammelt euch! Gehen wir los! / Hinein in die befestigten Städte! / Sterben wir dort! / Denn Jahwe, unser Gott, / beschloss unseren Tod. / Vergiftetes Wasser / gab er uns zu trinken, / weil wir gegen ihn gesündigt haben." },
      { number: 15, text: "Wir warteten auf Frieden, / doch es kam nichts Gutes. / Wir hofften auf Heilung – und nun das Entsetzen!" },
      { number: 16, text: "Von Dan* vernimmt man schon das Schnauben der Pferde, / das Wiehern der Starken erschüttert das Land. / Sie kommen und fressen alles auf, / auch die Städte und ihre Bewohner.\"", footnotes: ["Dan war eine Stadt an der Nordgrenze Israels."] },
      { number: 17, text: "\"Passt auf!\", spricht Jahwe. / \"Ich lasse Schlangen auf euch los, / Vipern, die man nicht beschwören kann, / und sie werden euch beißen!\"" },
      { number: 18, text: "Mein fröhliches Gesicht verbirgt meinen Kummer. / Er lastet auf mir und macht mein Herz krank.", heading: "Jeremia leidet mit seinem Volk" },
      { number: 19, text: "Hört, wie mein Volk aus fernem Land schreit: / \"Ist Jahwe nicht in Zion? / Ist sein König nicht darin?\"\"Warum haben sie mich denn mit ihren Bildern provoziert, / diesen geschnitzten Nichtigkeiten fremder Völker?\"" },
      { number: 20, text: "\"Die Ernte ist vorüber, / der Herbst ist vorbei, / und es ist keine Hilfe gekommen!\"" },
      { number: 21, text: "Der Zusammenbruch von meinem Volk / hat auch mich gebrochen. / Ich bin voller Trauer, mich packt das Entsetzen." },
      { number: 22, text: "Gibt es in Gilead* keine Salbe mehr? / Gibt es dort keinen Arzt? / Gibt es keine Heilung für mein Volk? / Weshalb wächst die Wunde nicht zu?", footnotes: ["Gilead. Das ostjordanische Bergland war offenbar bekannt für Heilkräuter und Ärzte (Jeremia 46,11)."] },
      { number: 23, text: "Wäre mein Kopf ein Gewässer / und meine Augen Tränenquellen, / dann würde ich unsere Toten / Tag und Nacht beweinen." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "O hätte ich nur in der Wüste / einen Platz zum Übernachten. / Dann würde ich mein Volk verlassen, / ich würde von ihnen gehen! / Denn sie sind alle Ehebrecher, / eine Bande voller Treulosigkeit!", heading: "Jeremias Klage über sein Volk" },
      { number: 2, text: "\"Ihre Zunge ist ein gespannter Bogen, / der Lügen im ganzen Land verschießt. / Nicht durch Wahrheit wurden sie stark. / Eine Bosheit folgte der nächsten; / mich aber kennen sie nicht\", / spricht Jahwe." },
      { number: 3, text: "\"Seid auf der Hut vor euren Freunden, / und traut selbst eurem Bruder nicht. / Denn jeder Bruder betrügt, / und ein Freund legt den andern herein." },
      { number: 4, text: "Jeder betrügt den andern, / die Wahrheit sagen sie nicht. / Sie haben ihre Zunge ans Lügen gewöhnt / und können das Böse nicht lassen." },
      { number: 5, text: "– Du wohnst mitten unter Betrügern. – Sie wollen mich nicht kennen\", spricht Jahwe." },
      { number: 6, text: "Darum spricht Jahwe, der Allmächtige: / \"Ich werde sie schmelzen und läutern! / Denn was soll ich sonst mit meinem Volk tun?" },
      { number: 7, text: "Ihre Worte sind tödliche Pfeile, / sie lügen unentwegt. / Nach außen täuschen sie Freundschaft vor, / doch im Herzen planen sie den Überfall." },
      { number: 8, text: "Sollte ich das etwa nicht bestrafen?\", spricht Jahwe. / \"Muss ich solch ein Volk nicht zur Rechenschaft ziehen?\"" },
      { number: 9, text: "Über das Bergland muss ich weinen, / über die Weiden in der Steppe / stimme ich ein Klagelied an. / Denn alles ist verwüstet und verbrannt. / Kein Hirte zieht hindurch, / und man hört auch keine Herden mehr. / Die Tiere sind geflohen, / selbst die Vögel sind fort." },
      { number: 10, text: "\"So mache ich Jerusalem zum Trümmerhaufen, / in dem nur noch Schakale hausen. / Judas Städte werden zum Ödland, / wo niemand mehr wohnt.\"" },
      { number: 11, text: "Wer ist der weise Mann, der das versteht? Zu wem hat Jahwe geredet, dass er uns erklären kann, warum das Land zugrunde geht, warum es verbrannt wird wie eine Wüste, die niemand durchzieht?" },
      { number: 12, text: "Da erwiderte Jahwe: \"Weil sie meine Weisung in den Wind schlugen, weil sie nicht auf das hörten, was ich sagte," },
      { number: 13, text: "sondern taten, wozu ihr Trotz sie trieb. Sie liefen den Baalen nach, wie sie es von ihren Vorfahren gelernt hatten.\"" },
      { number: 14, text: "Darum sagt Jahwe, der Allmächtige, Israels Gott: \"Passt auf! Ich werde diesem Volk Bitteres zu essen und Giftiges zu trinken geben." },
      { number: 15, text: "Ich werde sie unter fremde Völker zerstreuen, die weder sie noch ihre Vorfahren gekannt haben. Und ich schicke ihnen das Schwert hinterher, bis ich sie vernichtet habe.\"" },
      { number: 16, text: "So spricht Jahwe, der Allmächtige: / \"Begreift es! Ruft die Klagefrauen her, / lasst die weisen Frauen kommen! /" },
      { number: 17, text: "Beeilen sollen sie sich / und mit dem Klagen beginnen, / dass unsere Augen schwimmen / und die Tränen fließen." },
      { number: 18, text: "Aus Zion hört man schon die Klage: / 'Ach, wir können es nicht fassen! / Wie jämmerlich sind wir geschändet! / Wir mussten unser Land verlassen, / alle Häuser riss man ein.'\"" },
      { number: 19, text: "Ihr Frauen, hört das Wort Jahwes! / Nehmt auf, was er gesagt hat! / Singt euren Töchtern das Klagelied vor, / und bringt es euch gegenseitig bei:" },
      { number: 20, text: "\"Der Tod ist durch unsere Fenster gestiegen, / er drang in unsere Paläste ein. / Er raffte das Kind von der Straße weg, / von den Märkten die jungen Männer.\"" },
      { number: 21, text: "Sag: \"So spricht Jahwe: / 'Die Leichen der Leute / fallen wie Dünger auf das Feld, / wie Garben hinter dem Schnitter, / und niemand sammelt sie ein.'\"" },
      { number: 22, text: "So spricht Jahwe: / \"Der Weise rühme sich nicht seiner Weisheit, / der Starke sei nicht stolz auf seine Stärke, / und der Reiche gebe nicht an mit seinem Geld.", heading: "Worauf man nicht stolz sein kann" },
      { number: 23, text: "Grund zum Rühmen hat nur, / wer mich erkennt und begreift, was ich will; / wer einsieht, dass ich Jahwe bin,* / der auf der Erde Gnade, Recht und Gerechtigkeit schafft! / Denn das gefällt mir\", spricht Jahwe.", footnotes: ["Wird im Neuen Testament von Paulus zitiert: 1. Korinther 1,31; 2. Korinther 10,17."] },
      { number: 24, text: "\"Passt auf! Es wird eine Zeit kommen\", spricht Jahwe, \"da ziehe ich alle zur Rechenschaft, die nur äußerlich beschnitten sind:", heading: "Israel ein unbeschnittenes Volk" },
      { number: 25, text: "Ägypten und Juda, die Edomiter und die Ammoniter*, die Moabiter* und die Wüstenstämme, die sich die Schläfenlocken stutzen. Denn alle nichtjüdischen Völker sind für mich unbeschnitten, und auch Israel hat ein unbeschnittenes Herz.\"", footnotes: ["Die Ammoniter waren nordöstliche Nachbarn der Moabiter.", "Die Moabiter lebten östlich vom Toten Meer zwischen den Flüssen Arnon und Zered."] },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Hört das Wort Jahwes, ihr Israeliten!", heading: "Gott und Götzen" },
      { number: 2, text: "So spricht Jahwe:\"Gewöhnt euch nicht den Stil der Völker an, / erschreckt nicht vor Erscheinungen des Himmels, / auch wenn das die Völker in Angst versetzt." },
      { number: 3, text: "Denn ihre Gebräuche sind ohne Sinn, / ihre Götzen ohne Verstand. / Da holt einer Holz aus dem Wald, / der Schnitzer macht daraus eine Figur." },
      { number: 4, text: "Man schmückt sie mit Silber und Gold, / befestigt sie mit Hammer und Nagel, / damit der Gott nicht wackeln kann." },
      { number: 5, text: "Wie Vogelscheuchen im Gurkenfeld / stehen sie und reden nicht. / Man muss sie tragen, sie können nicht gehen. / Habt keine Angst vor ihnen! / Sie können euch nichts Böses tun, / und Gutes noch viel weniger.\"" },
      { number: 6, text: "Niemand ist wie du, Jahwe! / Du bist groß und bekannt für deine Macht." },
      { number: 7, text: "Wer wollte dich nicht fürchten, / du König aller Völker! / Darauf hast du ein Recht! / Denn unter allen Weisen dieser Welt, / in keinem ihrer Reiche ist jemand dir gleich." },
      { number: 8, text: "Sie alle sind dumm und ohne Verstand, / denn ihre Nichtse lehren sie nichts, / sie sind ja nur aus Holz," },
      { number: 9, text: "die Werke von Goldschmied und Schnitzer. Aus Tarschisch* stammt ihr Silberblech, / ihr Goldbelag aus Ufas*. / Künstler schufen ihre Gewänder / in Purpurblau und –rot.", footnotes: ["Tarschisch.Von Tyrus gegründete südspanische Küstenstadt.", "Ufas.Der Ort ist unbekannt, vielleicht handelt es sich um eine Verschreibung von Ofir. Dann siehe die Fußnote zu 2. Chronik 8,18!"] },
      { number: 10, text: "Doch in Wirklichkeit ist Jahwe Gott. / Er ist der lebendige Gott, der ewige König. / Die Erde bebt vor seinem Zorn, / kein Volk hält seinen Unwillen aus." },
      { number: 11, text: "Sagt den Völkern: \"Diese Götter, die weder Himmel noch Erde geschaffen haben, werden unter diesem Himmel von der Erde verschwinden.\"*", footnotes: ["Dieser Vers steht im Grundtext in aramäischer Sprache."] },
      { number: 12, text: "Gott schuf die Erde durch seine Kraft, / durch Weisheit gründete er das feste Land / und durch Einsicht breitete er den Himmel aus." },
      { number: 13, text: "Wenn er es befiehlt, stürzt das Wasser vom Himmel, / steigen Wolken am Horizont auf. / Er lässt es blitzen und regnen, / den Wind aus seinem Lager brausen." },
      { number: 14, text: "Dumm steht da der Mensch mit seinem Können, / jeder Goldschmied mit dem Götzenbild. / Denn diese Bilder sind Betrug, sie haben kein Leben." },
      { number: 15, text: "Sie sind Nichtse, Figuren zum Spott. / Wenn er mit ihnen abrechnet, sind sie verloren." },
      { number: 16, text: "Wie anders ist da Jakobs Gott! / Denn er hat das Weltall geschaffen / und sich Israel zum Eigentum bestimmt. / Jahwe, der Allmächtige, heißt er." },
      { number: 17, text: "Rafft euren Kram zusammen, ihr Bewohner der belagerten Stadt,", heading: "Erste Ankündigung der Verbannung" },
      { number: 18, text: "denn so spricht Jahwe: \"Passt auf! Diesmal werde ich die Bewohner des Landes wegschleudern, ich werde sie bedrängen, damit ihre Feinde sie finden.\"" },
      { number: 19, text: "Weh mir wegen meiner Wunde, / ich bin zu Tode getroffen! / Dabei hatte ich gedacht: / Es ist nur eine leichte Krankheit, / die ich gut ertragen kann." },
      { number: 20, text: "Nun ist mein Zelt zerstört, / die Stricke sind zerrissen. / Meine Kinder sind fort, / keines ist mehr da. / Niemand baut mein Zelt wieder auf / und spannt die Decken darüber." },
      { number: 21, text: "Denn die Hirten waren dumm, / haben Jahwe nicht gesucht. / Deshalb merkten sie nichts, / und ihre Herde wurde zerstreut." },
      { number: 22, text: "Horch, eine Meldung! Da kommt es: / großes Getöse vom Nordland her, / um Judas Städte zur Öde zu machen, / zur Behausung für Schakale." },
      { number: 23, text: "Ich weiß, Jahwe: / Der Mensch hat sein Schicksal nicht in der Hand, / keiner bestimmt selbst, / wohin sein Lebensweg führt.", heading: "Jeremia betet" },
      { number: 24, text: "Bestrafe mich Jahwe, / doch mit dem rechten Maß, / nicht in deinem Zorn, / denn das wäre mein Ende." },
      { number: 25, text: "Gieß deinen Zorn über die Völker aus, / die dich nicht anerkennen, / über die Geschlechter, / die deinen Namen nicht rufen! / Denn sie haben Jakob* gefressen, / ihn verzehrt und vernichtet / und seinen Weideplatz öde gemacht.", footnotes: ["Jakob. Gemeint sind die Nachkommen Jakobs, also Israel."] },
    ] },
    { number: 11, verses: [
      { number: 1, text: "Folgendes Wort kam von Jahwe an Jeremia:", heading: "Auf Bundesbruch folgt Strafe (11-20)\nDer Bund ist gebrochen" },
      { number: 2, text: "\"Hört auf die Bestimmungen dieses Bundes! Verkündigt sie den Leuten von Juda und den Bewohnern von Jerusalem!" },
      { number: 3, text: "Sag zu ihnen: 'So spricht Jahwe, Israels Gott: Fluch über jeden, der nicht auf die Bestimmungen des Bundes hört," },
      { number: 4, text: "den ich euren Vorfahren auferlegte, als ich sie aus dem Schmelzofen Ägyptens herausholte. Damals sagte ich zu ihnen: Hört auf mich und haltet euch an alles, was ich anordne, dann seid ihr mein Volk und ich bin euer Gott." },
      { number: 5, text: "Nur dann kann ich den Eid halten, den ich euren Vorfahren geschworen habe, dass ich ihnen ein Land gebe, das von Milch und Honig überfließt – das Land, in dem ihr heute lebt.'\" Ich erwiderte: \"Amen*, Jahwe!\"", footnotes: ["Amen. Hebräisch: Es werde wahr! Oder: So sei es!"] },
      { number: 6, text: "Darauf sagte Jahwe zu mir: \"Verkünde es in allen Städten Judas und auf den Straßen von Jerusalem: 'Hört auf die Bestimmungen des Bundes und handelt danach!" },
      { number: 7, text: "Seit ich eure Vorfahren aus Ägypten herausführte, habe ich sie bis heute immer wieder dringend ermahnt. Ich habe mich beizeiten aufgemacht und sie beschworen, auf mich zu hören." },
      { number: 8, text: "Aber sie dachten gar nicht daran. Sie haben nicht einmal zugehört, sondern machten eigensinnig, was sie wollten. So musste ich alles wahr machen, was ich ihnen für den Fall angedroht hatte, dass sie die Vorschriften meines Bundes nicht befolgten.'\"" },
      { number: 9, text: "Jahwe sagte zu mir: \"Es gibt eine Verschwörung unter den Leuten von Juda und den Einwohnern von Jerusalem." },
      { number: 10, text: "Sie sind zu den Verfehlungen ihrer Vorfahren zurückgekehrt, die sich auch schon geweigert hatten, mir zu gehorchen. Sie sind fremden Göttern nachgelaufen und haben ihnen gedient. Das Volk von Israel und Juda hat den Bund gebrochen, den ich mit ihren Vorfahren geschlossen hatte.\"" },
      { number: 11, text: "Darum sagt Jahwe: \"Jetzt bringe ich Unheil über sie, dem sie nicht ausweichen können. Wenn sie dann zu mir um Hilfe schreien, werde ich nicht auf sie hören." },
      { number: 12, text: "Dann mögen sie in den Städten Judas und in Jerusalem zu den Göttern um Hilfe schreien, denen sie Räucheropfer brachten; aber die werden sie in ihrer Not nicht retten können." },
      { number: 13, text: "Inzwischen sind deine Götter ja so zahlreich wie deine Städte geworden, Juda. Und an jeder Straßenecke von Jerusalem habt ihr dem schändlichen Baal einen Altar gebaut, um ihm Weihrauch darauf zu opfern." },
      { number: 14, text: "Du aber sollst nicht für dieses Volk bitten! Kein Gebet, kein Flehen! Und wenn sie dann in ihrer Not zu mir schreien, werde ich auch auf dich nicht hören." },
      { number: 15, text: "Was hat denn mein geliebtes Juda in meinem Haus zu suchen, wenn es nur ein böses Spiel mit mir treibt? Schaff die Götzendiener und das Opferfleisch fort. Doch so böse wie du bist, freust du dich noch darüber.\"" },
      { number: 16, text: "Einen üppig grünenden Ölbaum mit schön gewachsenen Früchten nannte Jahwe dich einmal. Doch nun – ein großes Geprassel: Er legt Feuer an dich, und alle Äste knacken." },
      { number: 17, text: "Jahwe, der Allmächtige, der dich pflanzte, hat deinen Untergang beschlossen. Denn du hast ihn gereizt und dem Baal Weihrauch verbrannt. Das ist nun die Folge der Bosheit der Leute von Israel und Juda." },
      { number: 18, text: "Jahwe ließ es mich wissen, da wusste ich es. Damals ließ er mich das Treiben meiner Nachbarn durchschauen.", heading: "Mordpläne gegen Jeremia" },
      { number: 19, text: "Ich war wie ein zutrauliches Lamm, das zum Schlachten geführt wird. Ich wusste nichts von ihren Plänen gegen mich. Sie sagten zueinander: \"Hauen wir den Baum um, wenn er solche Früchte trägt! Lassen wir ihn vom Erdboden verschwinden, dann wird sein Name bald vergessen sein!\"" },
      { number: 20, text: "Aber du, Jahwe, allmächtiger Gott, du richtest gerecht, denn du kennst die geheimsten Wünsche und Gedanken. Lass mich sehen, wie du Vergeltung an ihnen übst, denn dir habe ich meinen Fall anvertraut." },
      { number: 21, text: "Darum – so spricht Jahwe über die Männer von Anatot, die dich umbringen wollen und sagen: \"Hör auf, im Namen Jahwes zu weissagen, sonst bringen wir dich eigenhändig um!\"" },
      { number: 22, text: "Darum spricht Jahwe der Allmächtige: \"Pass auf! Ich ziehe sie zur Rechenschaft. Ihre jungen Männer werden umkommen durch das Schwert, ihre Kinder durch den Hunger." },
      { number: 23, text: "Keiner von ihnen wird übrig bleiben. Im Jahr der Abrechnung lasse ich das Unglück über die Männer von Anatot kommen.\"" },
    ] },
    { number: 12, verses: [
      { number: 1, text: "Du bist gerecht, Jahwe, wie könnte ich nur mit dir streiten? / Dennoch muss ich über das Recht mit dir reden. / Warum haben die Bösen Erfolg? / Weshalb können Abtrünnige sorglos sein?", heading: "Jeremia in innerer Not" },
      { number: 2, text: "Du hast sie gepflanzt, und sie haben Wurzeln geschlagen; / sie wachsen heran und bringen auch Frucht. / Doch nur in ihrem Reden bist du nah, / in ihrem Gewissen aber fern." },
      { number: 3, text: "Du kennst mich, Jahwe, / du hast mich durchschaut / und meine Gesinnung geprüft. / Zerre sie fort wie Schafe zum Schlachten, / sondere sie zum Abschlachten aus!" },
      { number: 4, text: "Wie lange soll das Land vertrocknen, / das Grün auf den Feldern verdorren? / Wegen der Bosheit seiner Bewohner / gehen Vieh und Vögel zugrunde. / Denn sie sagen von mir: / \"Der sieht unsere Zukunft nicht!\"" },
      { number: 5, text: "\"Wenn du mit Fußgängern läufst, / und sie dich schon ermüden, / wie willst du den Lauf gegen Pferde bestehen? / Wenn du dich nur im Land des Friedens sicher fühlst, / wie wirst du dich dann im Jordandickicht verhalten?" },
      { number: 6, text: "Selbst deine Brüder und deine Verwandten haben dich verraten. / Sie schreien laut hinter dir her. / Trau ihnen nicht, / auch wenn sie freundlich mit dir reden.\"" },
      { number: 7, text: "\"Ich habe mein Haus verlassen, / mein Eigentum verstoßen. / Das Volk, das ich von Herzen liebe, / gab ich in die Gewalt seiner Feinde.", heading: "Gottes Klage über sein Land" },
      { number: 8, text: "Mein Erbteil ist mir fremd geworden. / Es ist wie ein Löwe im Wald / und brüllt mich feindselig an. / Darum musste ich es hassen." },
      { number: 9, text: "Nun ist es wie ein bunter Vogel, / über dem die Raubvögel kreisen. / Los! Bringt die wilden Tiere herbei! / Hier gibt es genug zu fressen." },
      { number: 10, text: "Viele Hirten haben meinen Weinberg verwüstet, / meinen Acker zerstampft, / meine herrlichen Felder / zu einer trostlosen Wüste gemacht." },
      { number: 11, text: "Alles ist zur Öde geworden, / verwüstet trauert es mich an. / Das ganze Land ist eine Wüste, / weil niemand es sich zu Herzen nahm.\"" },
      { number: 12, text: "Über alle Wüstenhöhen kamen Zerstörer ins Land, denn das Schwert Jahwes verwüstet es von einem Ende bis zum anderen. Kein Mensch kann sicher sein." },
      { number: 13, text: "Sie haben Weizen gesät und Dornen geerntet. Sie haben sich geplagt, aber ohne Erfolg. Nun stehen sie enttäuscht vor ihren Erträgen, vor der Glut von Jahwes Zorn." },
      { number: 14, text: "So spricht Jahwe: \"Ich werde die unverschämten Nachbarn, die das Eigentum meines Volkes Israel antasten, ebenso aus ihrem Land herausreißen, wie ich das mit Juda tue." },
      { number: 15, text: "Doch nachdem ich sie herausgerissen habe, werde ich mich wieder über sie erbarmen: Ich lasse jedes Volk in sein Land und seinen Grundbesitz zurückkehren." },
      { number: 16, text: "Und wenn die Nachbarn dann die Lebensweise meines Volkes lernen, sodass sie bei meinem Namen schwören: 'So wahr Jahwe lebt!', so wie sie früher mein Volk lehrten, beim Baal zu schwören, dann werden sie mitten in meinem Volk wiederhergestellt werden." },
      { number: 17, text: "Wenn solch ein Volk aber nicht hört, werde ich es endgültig ausreißen und vernichten\", spricht Jahwe." },
    ] },
    { number: 13, verses: [
      { number: 1, text: "Jahwe sagte zu mir: \"Kauf dir einen Lendenschurz aus Leinen und lege ihn an! Sorge aber dafür, dass er nie ins Wasser kommt!\"", heading: "Der Lendenschurz" },
      { number: 2, text: "Ich kaufte den Lendenschurz und trug ihn, wie Jahwe es gesagt hatte." },
      { number: 3, text: "Das Wort Jahwes kam zum zweiten Mal zu mir. Er sagte:" },
      { number: 4, text: "\"Geh mit dem Lendenschurz, den du gekauft und getragen hast, nach Perat* und verstecke ihn dort in einer Felsspalte.\"", footnotes: ["Perat meint wahrscheinlich Para (Josua18,23), in der Nähe des modernen Wadi Farah 5 km nördlich von Anatot. In anderen Zusammenhängen bezieht sich Perat auf den Euphrat."] },
      { number: 5, text: "Ich tat, was Jahwe mir gesagt hatte." },
      { number: 6, text: "Viele Tage später sagte Jahwe zu mir: \"Geh wieder nach Perat und hole den Lendenschurz, den du dort auf meinen Befehl hin versteckt hast.\"" },
      { number: 7, text: "Da ging ich hin und holte ihn aus seinem Versteck. Er war verrottet und zu nichts mehr zu gebrauchen." },
      { number: 8, text: "Da kam das Wort Jahwes zu mir:" },
      { number: 9, text: "So spricht Jahwe: \"Genauso werde ich den Hochmut von Juda und Jerusalem verrotten lassen." },
      { number: 10, text: "Dieses böse Volk, das sich weigert, auf mich zu hören, das in seiner Sturheit fremden Göttern nachläuft, sie verehrt und sich vor ihnen niederwirft: Es soll wie dieser Lendenschurz werden, der zu nichts mehr zu gebrauchen ist." },
      { number: 11, text: "Denn so, wie der Lendenschurz den Körper des Mannes umschließt, wollte ich Israel und Juda um mich haben\", spricht Jahwe. \"Sie sollten das Volk sein, das zu mir passt, das mein Ruhm und meine Zierde ist, aber sie wollten nicht hören.\"" },
      { number: 12, text: "Richte ihnen Folgendes aus: \"So spricht Jahwe, Israels Gott: 'Weinkrüge sollten immer voll sein!' Wenn sie dir darauf erwidern: 'Das wissen wir auch. Jeder Weinkrug sollte voll sein!',", heading: "Die Weinkrüge" },
      { number: 13, text: "sage zu ihnen: 'So spricht Jahwe: Passt auf! Ich werde die Bewohner dieses Landes abfüllen, bis sie betrunken sind: Die Könige auf Davids Thron, die Priester, die Propheten und alle Bewohner Jerusalems." },
      { number: 14, text: "Dann schlage ich sie gegeneinander, dass einer am anderen zerbricht, und zwar die Väter an den Söhnen, spricht Jahwe. Schonungslos, ohne Mitleid und Erbarmen werde ich sie vernichten.'\"" },
      { number: 15, text: "Hört und merkt auf! / Seid nicht überheblich! / Denn Jahwe hat geredet.", heading: "Warnung vor Hochmut" },
      { number: 16, text: "Gebt Jahwe, eurem Gott, die Ehre, / bevor er die Dunkelheit bringt, / bevor eure Füße sich stoßen auf dämmrigen Bergen / und ihr das Licht erwartet, / das er in Finsternis / und Todesdunkel verwandelt." },
      { number: 17, text: "Wenn ihr nicht darauf hört, / weint meine Seele im Verborgenen. / Sie weint über euren Stolz. / Ich muss weinen und weinen, / meine Tränen fließen ununterbrochen, / weil die Herde Jahwes / in die Gefangenschaft abgeführt wird." },
      { number: 18, text: "Sag zum König und zur Herrscherin*: / \"Setzt euch tief herunter! / Denn die Krone eurer Herrlichkeit / fällt euch vom Kopf herab.", footnotes: ["Herrscherin. Das war die Königsmutter."] },
      { number: 19, text: "Die Städte im Negev* sind verschlossen, / und niemand ist da, der öffnet*. / Ganz Juda wird verschleppt / und in die Verbannung geführt.", footnotes: ["Negev. Das heiße Südland Israels, zum Teil gebirgige Wüste.", "niemand ... öffnet. Weil sie in Trümmern liegen und menschenleer sind."] },
      { number: 20, text: "Schaut auf und seht! / Die Feinde kommen von Norden. / Wo ist die Herde, die dir gegeben war, / wo sind deine herrlichen Schafe?", heading: "Die Schändung Jerusalems" },
      { number: 21, text: "Was wirst du sagen, wenn Jahwe deine Liebhaber, / die du an dich gebunden hast, / als Herren über dich setzt? / Vor Schmerz wirst du schreien / wie eine Frau, die in Wehen liegt." },
      { number: 22, text: "Und wenn du dich fragst: 'Warum traf es gerade mich?' / Dann wisse: Wegen deiner großen Schuld / hat man dir das Kleid gehoben / und dich vergewaltigt." },
      { number: 23, text: "Kann ein Schwarzer seine Hautfarbe wechseln, / ein Leopard sein geflecktes Fell? / Dann könntet auch ihr Gutes tun! / Ihr seid ja ans Böse gewöhnt." },
      { number: 24, text: "\"Ich werde sie zerstreuen wie die Spreu, / die der Wüstenwind verweht." },
      { number: 25, text: "Dieses Los erwartet dich, / das habe ich dir zugeteilt\", spricht Jahwe, / \"weil du mich vergessen hast / und auf Lügen vertrautest." },
      { number: 26, text: "Nun hebe auch ich dir das Kleid hoch / bis über dein Gesicht, / dass alle deine Schande sehen," },
      { number: 27, text: "deine Ehebrüche, dein geiles Wiehern, / deine schändliche Unmoral. / Auf den Hügeln und auf dem Feld / habe ich deine abscheulichen Götzen gesehen. / Weh dir, Jerusalem! / Wie lange noch wirst du so besudelt sein?\"" },
    ] },
    { number: 14, verses: [
      { number: 1, text: "Wegen der großen Dürre kam folgendes Wort Jahwes an Jeremia:", heading: "Eine Dürrekatastrophe" },
      { number: 2, text: "\"Juda verzweifelt, / seine Städte sterben / trauernd zu Boden gebeugt. / Man hört Jerusalems Schrei." },
      { number: 3, text: "Die Reichen schicken ihre Diener nach Wasser, / die kommen an die Zisternen, / finden aber nichts. / Sie kehren mit leeren Krügen zurück. / Enttäuscht und beschämt verhüllen sie ihr Gesicht." },
      { number: 4, text: "Erstarrt ist der Acker, / kein Regen fällt aufs Land. / Die Bauern sind beschämt, / verhüllen ihr Gesicht." },
      { number: 5, text: "Selbst die Hirschkuh draußen / lässt ihr Neugeborenes im Stich, / denn Grünes findet sie nicht mehr." },
      { number: 6, text: "Auf kahlen Kuppen stehen wilde Esel, / sie schnappen nach Luft, / japsen wie Schakale. / Ihre Augen sind erloschen, / denn nirgends ist Gras.\"" },
      { number: 7, text: "\"Obwohl unsere Sünden uns verklagen, / hilf uns deinetwegen, Jahwe! / Zahlreich sind unsere Vergehen. / Gegen dich haben wir gesündigt." },
      { number: 8, text: "Du Hoffnung Israels, / du bist der Retter in der Not! / Warum bist du so wie ein Fremder im Land, / wie ein Wanderer, nur zum Übernachten da?" },
      { number: 9, text: "Warum bist du wie ein ratloser Mann, / wie ein Krieger, der nicht retten kann? / Du bist doch unter uns, Jahwe, / über uns wurde dein Name genannt! / Verlass uns nicht!\"" },
      { number: 10, text: "So spricht Jahwe zu diesem Volk: \"Sie lieben es, davonzulaufen, sie gönnen ihren Füßen keine Ruhe. Jahwe hat keine Freude mehr an ihnen. Er wird sie nicht verschonen und zieht sie jetzt zur Rechenschaft.\"", heading: "Von Gott verworfen" },
      { number: 11, text: "Zu mir sagte Jahwe: \"Bitte nicht mehr für das Wohl dieses Volkes!" },
      { number: 12, text: "Auch wenn sie fasten, höre ich nicht auf ihr Rufen, auch wenn sie mir Brand- und Speisopfer bringen, stimmen sie mich nicht um. Ich werde sie vernichten durch Hunger, Krieg und Pest.\"" },
      { number: 13, text: "\"Ach, Jahwe\", klagte ich, \"die Propheten sagen zu ihnen: 'Es gibt keinen Krieg und keine Hungersnot. Jahwe wird dieser Stadt dauerhaft Frieden geben.'\"" },
      { number: 14, text: "Da sagte Jahwe zu mir: \"Was die Propheten in meinem Namen verkünden, sind Lügen. Ich habe sie nicht geschickt, sie nicht beauftragt und nie zu ihnen gesprochen. Sie verkünden euch erfundene Visionen, Götzenorakel, selbst erdachten Betrug." },
      { number: 15, text: "Ich sage dir, was ich mit diesen Propheten mache, die in meinem Namen weissagen, obwohl ich sie nicht geschickt habe, die behaupten, dass das Land von Krieg und Hunger verschont bleibt: Sie selbst werden durch Krieg und Hunger enden!" },
      { number: 16, text: "Und das Volk, dem sie weissagen, wird auf den Straßen von Jerusalem liegen, niedergeworfen durch Hunger und Schwert. Niemand wird ihre Leichen und die ihrer Frauen und Kinder begraben. So gieße ich ihre eigene Bosheit über sie aus.\"" },
      { number: 17, text: "\"Lass sie wissen, wie betroffen du bist:'Meine Tränen fließen Tag und Nacht, / meine Augen sind nass und ruhen nicht. / Denn meine unberührte Tochter, / mein Volk, liegt schwer verletzt am Boden, / zerbrochen an einem furchtbaren Schlag.", heading: "Jeremia soll klagen" },
      { number: 18, text: "Gehe ich aufs Feld hinaus, / finde ich vom Schwert Getötete, / komme ich zurück in die Stadt, / finde ich vom Hunger Gequälte. / Priester und Propheten laufen herum / und finden keinen Rat.'\"" },
      { number: 19, text: "Hast du Juda ganz verworfen? / Widert dich Zion jetzt an? / Warum hast du uns so geschlagen, / dass es keine Heilung mehr gibt? / Wir hofften auf Heil, / doch es kam nichts Gutes. / Wir hofften auf die Zeit der Heilung, / doch es wurde immer schlimmer." },
      { number: 20, text: "Wir kennen unseren Frevel, Jahwe, / auch die Schuld unserer Väter: / Ja, wir haben gegen dich gesündigt." },
      { number: 21, text: "Um deines Namens willen verachte uns doch nicht! / Entehre nicht den Thron deiner Herrlichkeit! / Denk an deinen Bund mit uns und löse ihn nicht!" },
      { number: 22, text: "Gibt es Regenspender bei den Nichtsen der Völker? / Macht der Himmel etwa selbst den Regen? / Nein, du bist Jahwe, unser Gott! / Wir hoffen auf dich, / denn du hast das alles gemacht." },
    ] },
    { number: 15, verses: [
      { number: 1, text: "Da sagte Jahwe zu mir: \"Selbst wenn Mose und Samuel jetzt vor mir stünden, würde ich mich diesem Volk nicht zuwenden. Jage sie aus meiner Nähe fort! Sie sollen mir aus den Augen gehen!", heading: "Das Urteil ist gesprochen" },
      { number: 2, text: "Und wenn sie dich fragen: 'Wohin sollen wir denn gehen?', dann sage ihnen: 'So spricht Jahwe:Wer zum Pesttod bestimmt ist, bekomme die Pest; / wer zum Schwerttod bestimmt ist, laufe ins Schwert; / wer zum Hungertod bestimmt ist, sterbe an Hunger; / wer zur Verbannung bestimmt ist, ziehe in die Verbannung!'" },
      { number: 3, text: "'Ein vierfaches Verderben lasse ich gegen dieses Volk los', spricht Jahwe, 'das Schwert zum Umbringen, die Hunde zum Fortzerren, die Vögel und die wilden Tiere zum Zerfleischen und zum Fressen." },
      { number: 4, text: "Ich mache sie zu einem Bild des Entsetzens für alle Völker der Erde, und zwar wegen König Manasse Ben-Hiskija* von Juda und dem, was er in Jerusalem getan hat.'\"", footnotes: ["Ben-Hiskija. Vergleiche 2. Chronik 33."] },
      { number: 5, text: "\"Wer hat noch Mitleid mit Jerusalem? / Wer wird dir sein Beileid bekunden? / Wer wird dich besuchen / und fragen, wie es dir geht?" },
      { number: 6, text: "Du hast mich zurückgestoßen, / spricht Jahwe, / du hast mir den Rücken gekehrt. / Deshalb habe ich dich angegriffen* / und zugrunde gerichtet. / Ich bin es leid, nachsichtig zu sein!", footnotes: ["habe ich dich angegriffen. Es handelt sich bis V. 8 offenbar um ein prophetisches Perfekt, d.h. Zukünftiges wird als bereits geschehen geschildert."] },
      { number: 7, text: "Mit der Worfschaufel habe ich sie / aus dem Land hinausgeworfen. / Ich machte mein Volk kinderlos, / ich gab es verloren, / denn sie kehrten nicht um." },
      { number: 8, text: "Es wird mehr Witwen bei ihnen geben, / als Sandkörner an den Stränden. / Über die Soldatenmütter / brachte ich am hellen Tag den Tod, / Angst und Entsetzen / kam plötzlich über sie." },
      { number: 9, text: "Nun welkt die Frau dahin, haucht ihr Leben aus, / sie, die sieben Söhne gebar. / Ihre Sonne ging unter mitten am Tag, / sie wurde beschämt und enttäuscht. / Der Rest von ihnen fällt im Krieg, / ausgeliefert ihren Feinden\", / spricht Jahwe." },
      { number: 10, text: "Weh mir, Mutter, dass du mich geboren hast! / Jeder streitet und zankt mit mir, / das ganze Land feindet mich an! / Ich habe weder Geld verliehen / noch habe ich welches geborgt. / Trotzdem verfluchen mich alle.", heading: "Jeremias Klage" },
      { number: 11, text: "Jahwe spricht: / \"Habe ich dich nicht zum Guten stark gemacht? / Ich werde dafür sorgen, / dass dein Feind dich anfleht, / wenn er in Not und Bedrängnis gerät.", heading: "Gottes Antwort" },
      { number: 12, text: "Kann man Eisen zerbrechen, / Eisen aus dem Norden / und Bronze dazu?" },
      { number: 13, text: "Juda, dein Vermögen und deinen Besitz / gebe ich zur Plünderung frei. / Das ist der Lohn für eure Sünden, / die ihr überall im ganzen Land begangen habt." },
      { number: 14, text: "Ich mache dich zum Sklaven deiner Feinde / in einem Land, das du nicht kennst. / Wie Feuer lodert mein Gesicht, / und euch wird es verbrennen.\"" },
      { number: 15, text: "Jahwe, du weißt alles, / denk an mich und setz dich für mich ein! / Nimm Rache für mich an meinen Verfolgern! / Nicht, dass deine Langmut / mich zugrunde gehen lässt! / Du weißt doch, dass sie mich / deinetwegen beschimpfen.", heading: "Jeremias \"Warum?\"" },
      { number: 16, text: "Wenn du zu mir sprachst, verschlang ich jedes Wort. / Deine Worte haben mich mit Glück und Freude erfüllt. / Denn ich gehöre ja dir*, / Jahwe, allmächtiger Gott.", footnotes: ["ich gehöre ja dir. Wörtlich: Dein Name ist über mir ausgerufen, was eine Eigentumserklärung war."] },
      { number: 17, text: "Nie saß ich in fröhlicher Runde, / nie scherzte ich mit. / Von deiner Hand gepackt sitze ich allein, / denn deine Erbitterung erfüllt auch mich." },
      { number: 18, text: "Warum hört mein Schmerz nicht auf? / Warum schließt sich meine Wunde nicht? / Warum will sie nicht heilen? / Du hast mich enttäuscht, / du bist für mich wie ein Bach, der im Sommer versiegt." },
      { number: 19, text: "Da sagte Jahwe zu mir: / \"Wenn du umkehrst, nehme ich dich wieder an, / dann darfst du mir wieder dienen. / Wenn du deine Worte überlegst, / und nicht mehr solchen Unsinn von dir gibst, / dann darfst du wieder mein Mund sein. / Sie müssen auf dich hören, / aber du nicht auf sie!", heading: "Gottes Antwort" },
      { number: 20, text: "Dann mache ich dich für dieses Volk / zu einer festen eisernen Mauer. / Sie werden dich bekämpfen – doch ohne Erfolg, / denn ich bin bei dir und werde dich retten. / Ich schütze dich, ich, Jahwe." },
      { number: 21, text: "Ich rette dich aus der Hand der Bösen, / aus brutalen Fäusten befreie ich dich.\"" },
    ] },
    { number: 16, verses: [
      { number: 1, text: "Das Wort Jahwes kam zu mir. Er sagte:", heading: "Jeremias Einsamkeit – Zeichen des Gerichts" },
      { number: 2, text: "\"Du sollst nicht heiraten, du sollst keine Söhne und Töchter hier haben." },
      { number: 3, text: "Denn so spricht Jahwe über die Söhne und Töchter, die hier geboren werden, über ihre Mütter, die sie gebären, und ihre Väter, die sie hier zeugen:" },
      { number: 4, text: "'Sie werden an qualvollen Seuchen sterben; niemand wird sie beklagen und begraben. Wie Dünger werden sie auf der Erde liegen. Durch Krieg und Hunger kommen sie um. Sie dienen Vögeln und wilden Tieren zum Fraß.'\"" },
      { number: 5, text: "Weiter sagte Jahwe: \"Du sollst kein Trauerhaus betreten! Bleib Trauerfeiern fern, bekunde niemand dein Beileid! Denn ich habe diesem Volk meinen Frieden entzogen, die Gnade und das Erbarmen\", spricht Jahwe." },
      { number: 6, text: "\"Große und kleine Leute müssen in diesem Land sterben, ohne dass jemand sie begräbt. Niemand wird sie betrauern, niemand wird sich aus Trauer die Haut ritzen oder den Kopf kahl scheren.*", footnotes: ["... kahl scheren. Das waren kanaanäische Trauerbräuche, die Gott dem Volk Israel verboten hatte (siehe 3. Mose 19,28; 5. Mose 14,1)."] },
      { number: 7, text: "Mit keinem wird man das Trauerbrot teilen, um ihn wegen eines Toten zu trösten. Keinem wird man den Trostbecher reichen, auch nicht wegen Vater oder Mutter." },
      { number: 8, text: "Du sollst auch kein Hochzeitshaus betreten! Setz dich nicht zu den Gästen, um mitzuessen und mitzutrinken!" },
      { number: 9, text: "Denn so spricht Jahwe, der Allmächtige: 'Ihr werdet es noch selbst erleben, dass ich allem Jubel und aller Freude hier ein Ende mache. Auch den Jubelruf von Bräutigam und Braut wird man hier nicht mehr hören.'" },
      { number: 10, text: "Wenn du ihnen das alles gesagt hast, werden sie fragen: 'Warum kündigt Jahwe uns so ein schweres Unheil an? Was haben wir denn Böses getan? Worin haben wir uns gegen Jahwe, unseren Gott, vergangen?'" },
      { number: 11, text: "Sag ihnen dann Folgendes: 'So spricht Jahwe: Schon eure Vorfahren haben mich verlassen und sind anderen Göttern nachgelaufen. Ihnen haben sie gedient, vor ihnen sich niedergeworfen, mich aber haben sie verlassen; meine Weisungen schlugen sie in den Wind." },
      { number: 12, text: "Ihr jedoch habt es noch schlimmer getrieben als eure Väter. Jeder von euch macht nur, was sein trotziges und böses Herz ihm eingibt. Keiner hört auf mich!" },
      { number: 13, text: "Deshalb schleudere ich euch weg von hier in ein Land, das weder ihr noch eure Vorfahren kannten. Dort werdet ihr dann Tag und Nacht anderen Göttern dienen, weil ich euch nicht mehr gnädig bin.'\"" },
      { number: 14, text: "So spricht Jahwe: \"Es kommt der Tag, an dem man beim Schwören nicht mehr sagt: 'So wahr Jahwe lebt, der Israel aus Ägypten herausgeführt hat',", heading: "Ausblick auf die Rückkehr der Verschleppten" },
      { number: 15, text: "sondern: 'So wahr Jahwe lebt, der Israel aus dem Land im Norden herausgeführt hat und aus allen anderen Ländern, in die er sie vertrieben hatte.' Ja, ich werde sie in ihr Land zurückbringen, das ich ihren Vorfahren gab.\"" },
      { number: 16, text: "\"Ja, ich rufe dann viele Fischer herbei\", spricht Jahwe, \"die sollen die Israeliten wie Fische fangen. Danach rufe ich viele Jäger, die sie von jedem Berg und Hügel herunterjagen und aus jedem Felsspalt holen." },
      { number: 17, text: "Ich sehe ja alles, was sie tun; sie können sich vor mir nicht verstecken, auch ihre Schuld ist meinen Augen nicht verborgen." },
      { number: 18, text: "Doch zuerst lasse ich sie doppelt* büßen für ihre Schuld und Sünde, denn sie haben mein Land durch das Aas ihrer Scheusale entweiht, überall auf meinem Grundbesitz haben sie ihre abscheulichen Götzen hingestellt.\"", footnotes: ["doppelt. Nach dem Gesetz die übliche Forderung zum Schadenersatz (2. Mose 22,3.6.8)."] },
      { number: 19, text: "\"Jahwe, du bist meine Stärke und mein Schutz, / meine Zuflucht in der Bedrängnis. / Zu dir kommen Völker vom Ende der Welt. / 'Nur Lügen haben wir geerbt', sagen sie. / 'Wahngebilde sind die Götter unserer Väter. / Nicht einer nützt etwas!'\"", heading: "Die Bekehrung der Völker" },
      { number: 20, text: "\"Kann denn ein Mensch sich Götter machen? Das sind doch keine Götter!" },
      { number: 21, text: "Darum seht, ich lasse es die Völker begreifen: Diesmal erkennen sie meine gewaltige Macht und verstehen, dass mein Name Jahwe ist.\"" },
    ] },
    { number: 17, verses: [
      { number: 1, text: "Mit Eisengriffeln ist Judas Sünde aufgeschrieben, / mit Diamantenspitze eingegraben / in die Tafeln ihrer Herzen / und die Hörner ihrer Altäre.", heading: "Judas Sünde und Strafe" },
      { number: 2, text: "\"Wie an ihre Kinder – so denken sie an ihre Altäre und Aschera-Pfähle* bei den grünen Bäumen auf den Opferhöhen.", footnotes: ["Die Aschera war eine Fruchtbarkeitsgöttin, die in handlichen Figuren, geweihten Bäumen oder Pfählen verehrt wurde."] },
      { number: 3, text: "Du Volk von Berg- und Hügelpilgern! Deinen Besitz und all deine Schätze und auch deine Opferhöhen gebe ich zur Plünderung frei. Das ist der Lohn für deine Sünden in deinem ganzen Wohngebiet." },
      { number: 4, text: "Du bist selbst daran schuld, wenn du den Erbbesitz, den ich dir gegeben habe, loslassen musst. Ich mache dich zum Sklaven deiner Feinde in einem fremden, unbekannten Land. Ihr habt Feuer in mein Gesicht gebracht, das ist mein Zorn, der ewig brennt.\"" },
      { number: 5, text: "So spricht Jahwe: / \"Verflucht ist der Mann, der auf Menschen vertraut, / der sich auf Menschenkraft verlässt / und sein Herz von Jahwe abkehrt!", heading: "Fluch oder Segen" },
      { number: 6, text: "Er ist wie ein kahler Strauch in der Steppe, / der vergeblich auf Regen hofft. / Er steht auf dürrem Wüstenboden, / im salzigen Land, wo niemand wohnt." },
      { number: 7, text: "Gesegnet ist der Mann, der auf Jahwe vertraut, / dessen Hoffnung Jahwe ist!" },
      { number: 8, text: "Er ist wie ein Baum, der am Wasser steht / und seine Wurzeln zum Bach hinstreckt. / Er hat nichts zu fürchten, wenn Hitze kommt, / seine Blätter bleiben grün und frisch. / Ihm ist nicht bange vor dem Dürrejahr; / er trägt immer seine Frucht.\"" },
      { number: 9, text: "Abgründig ist das menschliche Herz, / beispiellos und unverbesserlich. / Wer kann es durchschauen?", heading: "Weisheitssprüche" },
      { number: 10, text: "Ich, Jahwe, sehe bis auf den Grund. / Ich prüfe die geheimsten Wünsche, / um jedem zu geben, was er verdient, / und zwar aufgrund seiner Taten." },
      { number: 11, text: "Wie ein Rebhuhn*, das Eier ausbrütet, / die es nicht selbst gelegt hat, / so ist ein Mensch, / der Reichtum durch Unrecht erwirbt. / In der Mitte seines Lebens muss er ihn lassen, / und am Ende steht er als Trottel da.", footnotes: ["Rebhuhn. Gemeint ist wohl das Wüstenhuhn. Diese brüten oft zu mehreren Paaren gleichzeitig in derselben Felsspalte. Man findet daher viele Eier auf einmal, und es ist nicht zu erkennen, welche Eier zu welchem Huhn gehören."] },
      { number: 12, text: "Der Ort unseres Heiligtums / ist ein Thron der Herrlichkeit, / erhaben von Anfang an.", heading: "Gebet Jeremias" },
      { number: 13, text: "Jahwe, du Hoffnung Israels! / Die dich verlassen, werden scheitern, / werden in den Staub geschrieben, / denn sie verließen Jahwe, / die Quelle frischen Wassers." },
      { number: 14, text: "Heile mich, Jahwe, dann werd ich geheilt! / Hilf du mir, dann ist mir wirklich geholfen! / Du gibst mir Anlass, dich zu preisen." },
      { number: 15, text: "Sieh doch, wie sie zu mir sagen: \"Wo bleibt denn Jahwes Wort? / Es soll sich doch erfüllen!\"" },
      { number: 16, text: "Ich gab den Hirtendienst nicht auf, / wünschte das Unheil nicht herbei, / wie du ja weißt. / Was von meinen Lippen kam, / ist dir wohlbekannt." },
      { number: 17, text: "Mach mir keine Angst, / du bist doch meine Zuflucht, / wenn das Unheil kommt." },
      { number: 18, text: "Bring Schande über meine Verfolger, / aber nicht über mich! / Sie soll das Entsetzen packen, / nicht aber mich. / Bring über sie den Unheilstag, / zerschmettere sie im völligen Zusammenbruch!" },
      { number: 19, text: "So sprach Jahwe zu mir: \"Stell dich an das Tor des Volkes, durch das die Könige Judas ein- und ausziehen, und auch an alle anderen Tore Jerusalems", heading: "Der Sabbat gehört Gott" },
      { number: 20, text: "und rufe dort aus: 'Hört die Botschaft Jahwes, Könige von Juda, Volk von Juda, Einwohner von Jerusalem und alle, die durch diese Tore kommen!" },
      { number: 21, text: "So spricht Jahwe: Wenn euch das Leben lieb ist, dann hütet euch davor, am Sabbat irgendeine Last durch diese Tore hereinzutragen!" },
      { number: 22, text: "Auch aus euren Häusern dürft ihr am Sabbat nichts hinaustragen. An diesem Tag muss jede Arbeit ruhen. Ehrt den Sabbat als heiligen Tag, wie ich es schon euren Vätern befahl!" },
      { number: 23, text: "Leider haben sie nicht gehorcht, ja nicht einmal hingehört. Sie stellten sich stur und wollten sich nichts sagen lassen." },
      { number: 24, text: "Wenn ihr mir aber gehorcht, spricht Jahwe, wenn ihr am Sabbat keine Last durch diese Tore tragt, wenn ihr ihn als heiligen Tag ehrt und keine Arbeit verrichtet," },
      { number: 25, text: "dann werden auch weiterhin Könige durch die Tore dieser Stadt einziehen, die auf dem Thron Davids sitzen; mit Wagen und Pferden werden sie sich fortbewegen, sie und ihre Oberen, die Männer von Juda und die Einwohner Jerusalems. Diese Stadt wird dann für immer bewohnt bleiben." },
      { number: 26, text: "Dann werden Leute aus den Städten Judas und aus der Umgebung Jerusalems kommen, aus dem Land Benjamin, aus der Schefela*, vom Gebirge und aus dem Negev. Sie bringen ihre Opfergaben in das Haus Jahwes: Brand- und Freudenopfer, Speise- und Lobopfer und Weihrauch.", footnotes: ["Schefela. Niedriges, sehr fruchtbares Hügelland, das sich in nordsüdlicher Richtung zwischen dem Gebirge und der Küstenebene des Mittelmeeres erstreckt."] },
      { number: 27, text: "Wenn ihr aber nicht auf mich hört, wenn ihr den Sabbat nicht als heiligen Tag ehrt, wenn ihr am Sabbat mit Lasten durch die Tore Jerusalems kommt, dann werde ich ein unlöschbares Feuer in diesen Toren entfachen, das die Paläste der Stadt verzehrt.'\"" },
    ] },
    { number: 18, verses: [
      { number: 1, text: "Wort Jahwes, das zu Jeremia kam:", heading: "Gleichnis vom Töpfer" },
      { number: 2, text: "\"Geh zum Haus des Töpfers hinunter, denn dort habe ich dir etwas zu sagen!\"" },
      { number: 3, text: "Ich ging hinunter und sah den Töpfer bei seiner Arbeit auf der Töpferscheibe." },
      { number: 4, text: "Wenn ihm ein Gefäß unter den Händen misslang, machte er aus dem Ton ein anderes, das ihm besser gefiel." },
      { number: 5, text: "Da kam das Wort Jahwes zu mir. Er sagte:" },
      { number: 6, text: "\"So spricht Jahwe: 'Kann ich es mit euch nicht genauso machen wie dieser Töpfer, ihr Leute von Israel? Wie der Ton in der Hand des Töpfers, so seid ihr in meiner Hand." },
      { number: 7, text: "Wenn ich irgendwann einem Volk oder Reich androhe, es auszureißen, niederzubrechen und zu vernichten," },
      { number: 8, text: "dieses Volk aber umkehrt und seine Bosheit unterlässt, tut es mir leid, dass ich das Unheil über sie bringen wollte, und tue es nicht." },
      { number: 9, text: "Ein anderes Mal sage ich zu einem Volk oder Reich, dass ich es aufbauen und einpflanzen will." },
      { number: 10, text: "Wenn dieses Volk aber tut, was mir missfällt, und nicht auf mich hört, tut es mir leid, dass ich ihnen das Gute bringen wollte, und ich tue es nicht.'" },
      { number: 11, text: "Rede nun zu den Leuten von Juda und den Einwohnern Jerusalems. Sag ihnen: 'So spricht Jahwe: Passt auf! Ich mache einen Plan gegen euch, ich bereite das Unglück für euch vor. Kehrt um von euren falschen Wegen und ändert euer Leben von Grund auf! Das gilt jedem von euch!'" },
      { number: 12, text: "Aber sie sagen: 'Daraus wird nichts! Wir folgen unsren eigenen Gedanken. Jeder kann das machen, was er selber will, ganz egal, ob das eigensinnig oder böse heißt.'\"" },
      { number: 13, text: "\"Deshalb spricht Jahwe: 'Erkundigt euch bei allen Völkern! Wo hat man je so etwas gehört? Etwas ganz Abscheuliches hat Israel, die junge Frau, getan.", heading: "Unbegreifliche Absage an Gott" },
      { number: 14, text: "Taut jemals der Schnee vom Gipfelfelsen des Libanon? Hört das Wasser auf zu fließen, das aus fernen Quellen kommt?" },
      { number: 15, text: "Mein Volk aber hat mich vergessen. Den Nichtsen opfern sie Weihrauch, und das brachte sie zu Fall. Nun gehen sie nicht mehr die guten Wege, die sie seit alter Zeit kennen. Von ihren Götzen wurden sie auf gefährliche, ungesicherte Steige geführt." },
      { number: 16, text: "Deshalb wird ihr Land für immer zu einem Ort des Grauens und der Verachtung. Wer an ihm vorüberzieht, schüttelt entsetzt den Kopf." },
      { number: 17, text: "Wie ein Ostwind werde ich mein Volk vor seinem Feind zerstreuen. Wenn das Unheil über sie kommt, kehre ich ihnen den Rücken zu und nicht das Gesicht.'\"" },
      { number: 18, text: "Da gibt es Leute, die sagen: \"Los, wir müssen etwas gegen Jeremia tun! Niemals wird unseren Priestern das Gesetz abhanden kommen, unseren Weisen der gute Rat und unseren Propheten das Wort. Los, schlagen wir ihn mit seinen eigenen Worten! Auf ihn wollen wir auf keinen Fall hören!\"", heading: "Jeremias Rachegebet" },
      { number: 19, text: "\"Achte auf mich, Jahwe! / Hör doch das Gerede meiner Gegner! /" },
      { number: 20, text: "Wird Gutes denn mit Bösem vergolten? / Eine Fallgrube haben sie mir geschaufelt. / Denk daran, wie ich vor dir stand, / um für sie einzutreten / und deinen Zorn von ihnen abzuwenden!" },
      { number: 21, text: "Darum: Lass ihre Kinder den Hungertod sterben / und übergib sie alle dem Schwert! / Ihre Frauen sollen kinderlose Witwen sein! / Ihren alten Männern wünsche ich die Pest / und ihren jungen den Tod durch das Schwert!" },
      { number: 22, text: "Schreie soll man aus den Häusern hören, / wenn plündernde Soldaten über sie kommen! / Denn sie hoben die Fallgrube aus, / um mich zu fangen. / Sie haben mir die Fallen gestellt." },
      { number: 23, text: "Aber du, Jahwe, kennst / ihre Mordpläne gegen mich. / Vergib ihnen nicht diese Schuld, / lösch ihre Sünde bei dir nicht aus! / Lass sie niederstürzen vor dir / und rechne im Zorn mit ihnen ab!\"" },
    ] },
    { number: 19, verses: [
      { number: 1, text: "Jahwe sagte zu mir: \"Kauf dir einen Krug vom Töpfer! Dann hol dir ein paar Älteste vom Volk und von den Priestern", heading: "Der zerschlagene Krug" },
      { number: 2, text: "und geh mit ihnen zum Scherbentor hinaus ins Hinnomtal. Dort rufe Folgendes aus:" },
      { number: 3, text: "'Hört das Wort Jahwes, ihr Könige von Juda und ihr Bewohner Jerusalems! So spricht Jahwe, der allmächtige Gott Israels: Passt auf! Ich bringe solches Unheil über diesen Ort, dass es jedem, der davon hört, in den Ohren dröhnt." },
      { number: 4, text: "Denn sie haben mich verlassen und mir diesen Ort durch Räucheropfer entfremdet, die sie anderen Göttern brachten, die weder sie noch ihre Vorfahren, noch die Könige von Juda gekannt haben. Dazu haben sie dieses Tal mit dem Blut unschuldiger Menschen getränkt." },
      { number: 5, text: "Dann haben sie Opferstätten für den Baal gebaut, um ihre Kinder darauf zu verbrennen, was ich ihnen nie befohlen habe. Niemals ist mir so etwas in den Sinn gekommen!" },
      { number: 6, text: "Deshalb wird die Zeit kommen, spricht Jahwe, in der man diesen Ort nicht mehr Tofet oder Hinnomtal nennen wird, sondern Mordtal." },
      { number: 7, text: "An diesem Ort werde ich die Pläne der Leute von Juda und Jerusalem vereiteln. Ich lasse sie ihren Todfeinden in die Hände fallen und mit dem Schwert erschlagen. Ihre Leichen werde ich den Vögeln und den wilden Tieren zum Fraß vorwerfen." },
      { number: 8, text: "Ich werde diese Stadt zu einem Ort des Grauens und der Verachtung machen. Wer an ihr vorüberzieht, schüttelt über ihre Wunden entsetzt den Kopf." },
      { number: 9, text: "Und wenn eure Todfeinde die Stadt belagern, werdet ihr vor lauter Hunger das Fleisch eurer eigenen Kinder essen und euch zuletzt gegenseitig schlachten.'" },
      { number: 10, text: "Dann zerschlage den Krug vor den Augen deiner Begleiter" },
      { number: 11, text: "und sage zu ihnen: 'So spricht Jahwe, der Allmächtige: Dieses Volk und diese Stadt werde ich zerschmettern wie dieses Tongeschirr, das man nicht wiederherstellen kann. Man wird die Toten im Tofet begraben müssen, weil man sonst keinen Platz mehr dazu hat." },
      { number: 12, text: "Auch diese Stadt mache ich samt ihren Bewohnern dem Tofet gleich', spricht Jahwe." },
      { number: 13, text: "'Die Häuser in Jerusalem und die Paläste der Könige sollen genauso unrein werden wie der Tofet, und zwar alle Häuser, auf deren Terrassen sie den Sternen Weihrauch verbrannt und anderen Göttern Trankopfer ausgegossen haben.'\"" },
      { number: 14, text: "Als Jeremia vom Tofet zurückkam, wo er im Auftrag Jahwes geweissagt hatte, stellte er sich in den Tempelvorhof und rief allen Leuten dort zu:", heading: "Jeremia wird misshandelt" },
      { number: 15, text: "\"So spricht Jahwe, der allmächtige Gott Israels: 'Ich will über diese Stadt und alle dazugehörenden Städte all das Unheil bringen, das ich ihnen angedroht habe; denn sie haben sich hartnäckig geweigert, auf meine Worte zu hören.'\"" },
    ] },
    { number: 20, verses: [
      { number: 1, text: "Als der Priester Paschhur Ben-Immer – er war der Oberaufseher im Haus Jahwes – diese Weissagung Jeremias hörte," },
      { number: 2, text: "ließ er den Propheten schlagen und im oberen Benjamintor beim Haus Jahwes in den Block* spannen.", footnotes: ["Der Block war ein Balkengerüst, in das der Gefangene an Händen, Füßen und Hals eingespannt wurde, um den Körper zu verdrehen, was schwere Schmerzen verursachte."] },
      { number: 3, text: "Am nächsten Morgen ließ Paschhur Jeremia wieder frei. Da sagte dieser zu ihm: \"Jahwe nennt dich nicht mehr Paschhur, sondern Magor-Missabib, 'Schrecken überall'." },
      { number: 4, text: "Denn so spricht Jahwe: 'Pass auf! Ich mache dich zum Schrecken für dich selbst und alle deine Freunde. Mit eigenen Augen wirst du sehen, wie sie durch das Schwert ihrer Feinde fallen. Ich liefere ganz Juda dem König von Babylon aus. Die einen wird er nach Babylonien verschleppen und die anderen mit dem Schwert erschlagen." },
      { number: 5, text: "Den ganzen Reichtum dieser Stadt überlasse ich ihren Feinden, allen Besitz, alle Kostbarkeiten, auch die Schätze der Könige von Juda. Alles wird geplündert, geraubt und nach Babylonien gebracht." },
      { number: 6, text: "Auch du, Paschhur, wirst mit allen Bewohnern deines Hauses in die Gefangenschaft gehen. Du wirst zusammen mit deinen Freunden, denen du falsch geweissagt hast, nach Babylonien kommen, dort sterben und dort begraben werden.'\"" },
      { number: 7, text: "Jahwe, du hast mich mitgerissen, / und ich ließ mich mitreißen. / Du hast mich gepackt und überwältigt. / Nun verspotten sie mich den ganzen Tag, / alle lachen mich aus. /", heading: "Jeremias Klage und Selbstverfluchung" },
      { number: 8, text: "Denn sooft ich den Mund auftue, muss ich schreien: / \"Verbrechen! Unterdrückung!\" / Nichts als täglich Spott und Hohn / bringt mir das Wort Jahwes." },
      { number: 9, text: "Aber wenn ich mir sagte: \"Ich will nicht mehr an ihn denken, / ich will nicht mehr sein Sprecher sein!\", / dann brennt es in meinem Herzen wie Feuer, / dann glüht mein Inneres. / Ich quälte mich, es auszuhalten, / doch ich konnte es nicht." },
      { number: 10, text: "Ja, viele höre ich tuscheln. / Schrecken ist überall! / \"Zeigt ihn an! Wir wollen es tun!\" / Selbst meine nächsten Bekannten / warten nur auf meinen Fall. / \"Vielleicht lässt er sich verleiten! / Dann kommen wir ihm endlich bei, / dann rächen wir uns an ihm!\"" },
      { number: 11, text: "Aber Jahwe steht mir bei / wie ein gewaltiger Held. / Darum straucheln meine Verfolger / und erreichen nichts. / Sie werden völlig blamiert, / weil es ihnen nicht gelingt. / Unvergesslich wird ihre große Schande sein." },
      { number: 12, text: "Und du, Jahwe, allmächtiger Gott, / schaust den Gerechten an, / prüfst ihn auf Herz und Nieren. / Lass mich sehen, wie du sie bestrafst, / denn dir vertraute ich meine Sache an." },
      { number: 13, text: "Singt Jahwe und lobt ihn, / denn er rettet den Armen aus der Gewalt des Bösen." },
      { number: 14, text: "Verflucht der Tag, an dem ich geboren! / Der Tag sei nicht gesegnet, an dem mich meine Mutter bekam!" },
      { number: 15, text: "Verflucht der Mann, der meinem Vater die frohe Botschaft brachte: /\"Es ist ein Junge! Du hast einen Sohn!\" / und ihn damit sehr erfreute." },
      { number: 16, text: "Es möge ihm ergehen wie den Städten, / die Jahwe ohne Erbarmen zerstörte! / Schon am Morgen soll er Schreckensschreie hören, / und am Mittag Kriegeslärm," },
      { number: 17, text: "weil Gott mich nicht sterben ließ im Mutterleib. / Dann wäre meine Mutter mein Grab geworden / und ihr Bauch für immer schwanger geblieben." },
      { number: 18, text: "Warum musste ich den Mutterschoß verlassen? / Um nichts als Elend und Kummer zu sehen? / Um mein Leben in Schande zu beenden?" },
    ] },
    { number: 21, verses: [
      { number: 1, text: "Wort Jahwes, das zu Jeremia kam, als König Zidkija Paschhur Ben-Malkija und den Priester Zefanja Ben-Maaseja zu ihm schickte und ihm sagen ließ:", heading: "21-39: Rebellische Führer – Gottes Gericht\nEmpfehlung an Zedekija (21-24)\nAuskunft an den König" },
      { number: 2, text: "\"König Nebukadnezzar von Babylon führt Krieg gegen uns. Frag doch Jahwe, was geschehen wird, ob er vielleicht wie früher ein Wunder für uns tut, sodass Nebukadnezzar abziehen muss.\"" },
      { number: 3, text: "Da sagte Jeremia zu den Männern: \"Gebt dem König folgenden Bescheid:" },
      { number: 4, text: "'So spricht Jahwe, Israels Gott: Passt auf! Noch kämpft ihr außerhalb der Mauern gegen den König von Babylon und die Chaldäer*, die euch belagern. Ich werde euch zum Rückzug zwingen, sodass ihr eure Waffen ins Innere der Stadt holen müsst.", footnotes: ["Chaldäer. Ursprünglich Bewohner von Süd-Babylonien, später wurden alle Babylonier Chaldäer genannt."] },
      { number: 5, text: "Ich selbst kämpfe gegen euch mit starker Hand und mächtigem Arm, mit Zorn und Grimm und großer Wut." },
      { number: 6, text: "Ich werde alles sterben lassen, was in dieser Stadt lebt, Menschen und Vieh. An einer schweren Seuche werden sie zugrunde gehen." },
      { number: 7, text: "Und danach, spricht Jahwe, werde ich König Zidkija von Juda und seine hohen Beamten und alles Volk in dieser Stadt, das von Hunger, Schwert und Pest noch verschont wurde, ihren Todfeinden ausliefern. Nebukadnezzar wird euch alle mit dem Schwert umbringen lassen, schonungslos, ohne Mitleid und Erbarmen.'\"" },
      { number: 8, text: "Dem Volk aber musste Jeremia ausrichten: \"So spricht Jahwe: 'Ihr habt die Wahl zwischen Leben und Tod." },
      { number: 9, text: "Wer in dieser Stadt bleibt, wird durch den Krieg, durch Hunger oder Pest sterben. Wer aber die Stadt verlässt und zu den Chaldäern überläuft, kommt mit dem Leben davon." },
      { number: 10, text: "Denn ich bin fest entschlossen, Unglück über die Stadt zu bringen und ihr nicht zu helfen', spricht Jahwe. 'Sie wird dem König von Babylon in die Hände fallen, und der wird sie in Schutt und Asche legen.'\"" },
      { number: 11, text: "An das Königshaus von Juda: / \"Hört das Wort Jahwes,", heading: "Die Botschaft an die Regierung" },
      { number: 12, text: "ihr Nachkommen Davids! / So spricht Jahwe: 'Haltet jeden Morgen gerechtes Gericht! / Befreit den Beraubten von seinem Bedrücker! / Sonst kommt wie ein Feuer mein Zorn über euch, / unlöschbar wegen der Bosheit eures Tuns!" },
      { number: 13, text: "Passt auf! Ich komme über euch, / die ihr dort unten auf dem Felsen* wohnt!', / spricht Jahwe. / 'Meint ihr, niemand kommt zu euch herab / und dringt in eure Bauten ein?", footnotes: ["auf dem Felsen. Der Königspalast war unterhalb des Tempels auf einem Felsen gebaut."] },
      { number: 14, text: "Ich ziehe euch zur Rechenschaft / für alle eure Taten', / spricht Jahwe. / 'Ich lege Feuer in eure Paläste*, / das ringsum alles verzehrt.'\"", footnotes: ["eure Paläste. Wörtlich: in ihren Wald. Gemeint sind die Zedernsäulen und –balken der Paläste."] },
    ] },
    { number: 22, verses: [
      { number: 1, text: "Jahwe sagte zu mir: \"Geh hinunter in den Palast des Königs von Juda und rufe diese Botschaft aus:", heading: "Gegen die Könige" },
      { number: 2, text: "'Höre, was Jahwe dir zu sagen hat, König von Juda, der auf dem Thron Davids sitzt. Höre es mitsamt deinen Dienern und dem Volk, das durch diese Tore kommt!" },
      { number: 3, text: "So spricht Jahwe: Sorgt für Recht und Gerechtigkeit, befreit die Beraubten aus der Gewalt ihrer Unterdrücker! Bedrängt weder Fremde, noch Waisen und Witwen, und misshandelt sie nicht! Vergießt hier kein unschuldiges Blut!" },
      { number: 4, text: "Nur wenn ihr euch wirklich daran haltet, werden auch weiterhin Könige durch diese Tore einziehen, Könige, die auf dem Thron Davids sitzen; mit Pferd und Wagen werden sie fahren, sie und ihre Diener und das Volk." },
      { number: 5, text: "Wenn ihr aber nicht auf diese Worte hört, dann schwöre ich bei mir selbst: Dieser Palast wird zu einem Trümmerhaufen werden!'\"" },
      { number: 6, text: "Denn so spricht Jahwe über den Palast der Könige von Juda: \"Du warst schön wie Gilead und wie der Gipfel des Libanon. Trotzdem mache ich eine Wüste aus dir, einen unbewohnten Ort." },
      { number: 7, text: "Ich schicke dir eine Abrisskolonne, die mit ihrem Werkzeug deine herrlichen Zedernstämme herausbricht und ins Feuer wirft." },
      { number: 8, text: "Menschen aus vielen Ländern werden dann hier vorüberziehen und sich fragen: 'Warum hat Jahwe dieser großen Stadt das angetan?'" },
      { number: 9, text: "Dann wird man ihnen antworten: 'Weil sie den Bund mit Jahwe, ihrem Gott, gebrochen haben. Sie haben sich vor anderen Götter niedergeworfen und sie verehrt.'\"" },
      { number: 10, text: "Weint nicht um den Toten*, trauert nicht um ihn. Weint vielmehr über den, der fortziehen muss*, denn er wird seine Heimat nie wiedersehen.", heading: "Trauer um Schallum", footnotes: ["den Toten. Gemeint ist Joschija, siehe Vers 11, der 609 v.Chr. in der Schlacht von Megiddo fiel.", "der fortziehen muss. Gemeint ist König Joahas (sein Geburtsname war Schallum, siehe auch 1. Chronik 3,15), der von Pharao Necho abgesetzt und nach Ägypten gebracht wurde (siehe 2. Könige 23,30-34)."] },
      { number: 11, text: "Denn so spricht Jahwe über Schallum Ben-Joschija, den König von Juda, der seinem Vater auf dem Thron folgte und die Stadt verlassen musste: \"Er wird niemals wieder hierher zurückkehren!" },
      { number: 12, text: "Er wird dort sterben, wohin man ihn verschleppt hat. Dieses Land wird er nie wiedersehen!\"" },
      { number: 13, text: "Weh dem, der seinen Palast mit unrechten Mitteln erbaut, / der ihn aufstockt mit Unrecht, / der die Leute umsonst arbeiten lässt, / sie nicht entlohnt,", heading: "Gegen König Jojakim" },
      { number: 14, text: "der sagt: \"Ich baue mir einen Riesenpalast / mit geräumigen Zimmern im Obergeschoss!\" / Er setzt ihm hohe Fenster ein, / täfelt ihn mit Zedernholz / und streicht ihn mit roter Farbe an." },
      { number: 15, text: "Bist du dadurch König, dass du wetteifern kannst mit Prachtbauten aus Zedernholz? Hat dein Vater nicht auch gut gegessen und getrunken und trotzdem für Recht und Gerechtigkeit gesorgt? Ging es ihm damals nicht gut?" },
      { number: 16, text: "Den Unterdrückten und Armen verhalf er zum Recht. Deshalb stand es gut! \"Sieht man nicht gerade daran, ob jemand mich kennt?\", spricht Jahwe." },
      { number: 17, text: "Aber du hast nichts anderes im Sinn als deinen eigenen Vorteil. Dafür vergießt du das Blut unschuldiger Menschen, wendest Erpressung an und gebrauchst Gewalt." },
      { number: 18, text: "Darum spricht Jahwe über König Jojakim Ben-Joschija von Juda: \"Für ihn wird es keine Totenklage geben: 'Ach, Bruder, ach, Schwester!' Niemand wird um ihn klagen: 'Ach, unser König, ach, seine Majestät!'" },
      { number: 19, text: "Man wird ihn wie einen toten Esel verscharren; man schleift ihn fort und wirft ihn weit draußen vor den Toren Jerusalems hin.*\"", footnotes: ["wirft ihn ... hin. In 2. Könige 24,6 wird auffälligerweise nur der Tod Jojakims erwähnt, kein Begräbnis, keine Trauer."] },
      { number: 20, text: "\"Ersteig den Libanon und schreie! / Lass deine Stimme auf dem Baschan erschallen / und rufe vom Gebirge Abarim* herab, / dass all deine Liebhaber zerschmettert sind.", footnotes: ["Libanon – Baschan – Abarim sind Bergregionen; die erste ganz im Norden Israels, die zweite östlich vom See Gennesaret und die dritte südöstlich vom Toten Meer."] },
      { number: 21, text: "Als es dir noch gut ging, sprach ich dich an. / Aber du sagtest: 'Lass mich in Ruh!' / Das war schon immer deine Art, / nie hörtest du auf mich!" },
      { number: 22, text: "Der Wind wird deine Hirten weiden, / und deine Liebhaber werden verbannt. / Schmach und Schande wirst du ernten / wegen all deiner Bosheit." },
      { number: 23, text: "Noch thronst du wie auf dem Libanon, / wohnst in Palästen aus Zedern. / Wie erbärmlich wirst du sein, / wenn die Schmerzen über dich kommen / wie die Wehen über die Frau!\"" },
      { number: 24, text: "\"So wahr ich lebe\", spricht Jahwe, \"selbst wenn du ein Siegelring an meiner rechten Hand wärst, König Konja* Ben-Jojakim von Juda, würde ich dich doch von dort wegreißen.", heading: "Gegen König Jojachin", footnotes: ["Konja ist die Kurzform von Jechonja und gleichbedeutend mit Jojachin (siehe 2. Könige 24,6-12)."] },
      { number: 25, text: "Ich werde dich deinen Todfeinden ausliefern, vor denen du Angst hast, und zwar den Chaldäern und ihrem König Nebukadnezzar von Babylon." },
      { number: 26, text: "Dich und deine Mutter werde ich in ein fremdes Land schleudern, aus dem keiner von euch beiden stammt. Dort werdet ihr sterben." },
      { number: 27, text: "Eure Heimat werdet ihr nie wiedersehen, so sehr ihr euch auch danach sehnt.\"" },
      { number: 28, text: "Ist dieser Konja denn ein zerbrochener Krug, ein Ding, das keinem gefällt? Warum werden er und seine Kinder in ein Land fortgeschleudert, das keiner von ihnen kennt?" },
      { number: 29, text: "O Land, Land, Land! Höre das Wort Jahwes!" },
      { number: 30, text: "So spricht Jahwe: \"Halte diesen Mann als kinderlos in der Chronik fest, als einen, der sein Leben lang nur Misserfolg hat. Denn keinem seiner Nachkommen wird es gelingen, auf dem Thron Davids zu sitzen und Juda zu regieren.\"" },
    ] },
    { number: 23, verses: [
      { number: 1, text: "\"Weh den Hirten, die meine Schafe auf der Weide zugrunde richten und sie zerstreuen!\", spricht Jahwe.", heading: "Ein König, der Gott gefällt" },
      { number: 2, text: "\"Darum sage ich, Jahwe, der Gott Israels, über die Hirten meines Volkes: 'Ihr habt meine Schafe auseinandergetrieben, ihr habt sie zerstreut, ihr habt euch nicht um sie gekümmert! Jetzt ziehe ich euch für die Bosheit eurer Taten zur Rechenschaft!', spricht Jahwe." },
      { number: 3, text: "'Ich selbst werde den Rest meiner Schafe aus allen Ländern zusammenholen, in die ich sie versprengt habe. Ich bringe sie auf ihre Weideplätze zurück. Dort werden sie gedeihen und sich vermehren." },
      { number: 4, text: "Ich werde ihnen Hirten geben, die wirklich für sie sorgen. Sie sollen keine Angst mehr haben, nicht mehr erschrecken und verloren gehen'\", spricht Jahwe." },
      { number: 5, text: "\"Seht, es kommt der Tag\", spricht Jahwe, \"da werde ich einen Nachkommen Davids zum König machen, der weise und gerecht regieren wird und der im Land für Recht und Gerechtigkeit sorgt." },
      { number: 6, text: "Dann wird Juda gerettet werden und Israel in Sicherheit leben. 'Jahwe, unsere Gerechtigkeit' wird man ihn nennen." },
      { number: 7, text: "Seht, es kommen Tage\", spricht Jahwe, \"da wird man nicht mehr sagen: 'So wahr Jahwe lebt, der Israel aus Ägypten herausgeführt hat'," },
      { number: 8, text: "sondern 'So wahr Jahwe lebt, der die Israeliten aus dem Land im Norden herausgeführt hat und aus allen anderen Ländern, in die er sie vertrieben hatte.' Dann werden sie wieder in ihrem eigenen Land wohnen.\"" },
      { number: 9, text: "Über die Propheten:Es bricht mir das Herz, / ich zittere am ganzen Leib / vor Jahwe und seinen heiligen Worten. / Ich bin wie ein Betrunkener, / wie ein Mann, der vom Wein benommen ist.", heading: "Gegen die falschen Propheten" },
      { number: 10, text: "Das Land ist voll von Ehebrechern, / und wegen des Fluchs vertrocknet der Boden, / sind die Weideplätze der Steppe verdorrt. / Alle haben nur Böses im Sinn, / ihre Stärke liegt im Unrechttun." },
      { number: 11, text: "\"Selbst Propheten und Priester sind gemein. / Ihre Bosheit fand ich sogar in meinem Haus\", / spricht Jahwe." },
      { number: 12, text: "\"Doch die Wege, die sie gehen, / werden glatt und schlüpfrig sein; / sie stürzen in der Dunkelheit / und kommen alle zu Fall. / Denn ich bringe Unheil über sie; / das Jahr der Abrechnung kommt\", / spricht Jahwe." },
      { number: 13, text: "\"Was ich bei den Propheten Samarias gesehen habe, war schon abscheulich genug: Sie weissagten im Namen des Götzen Baal und haben mein Volk Israel in die Irre geführt." },
      { number: 14, text: "Aber bei den Propheten Jerusalems habe ich Schauderhaftes gesehen: Sie begehen Ehebruch und leben in der Lüge! Und dann bestärken sie die Gottlosen noch in ihrem Treiben, sodass niemand daran denkt, sein Leben zu ändern. Für mich sind sie alle wie Sodom und die Bewohner der Stadt wie Gomorra.*\"", footnotes: ["Sodom ... Gomorra. Städte, die Gott wegen der Bosheit ihrer Bewohner durch Feuer vernichtet hat (siehe 1. Mose 19,24-25)."] },
      { number: 15, text: "Darum spricht Jahwe, der Allmächtige, über die Propheten: \"Passt auf! Ich werde ihnen Bitteres zu essen geben und Giftwasser zu trinken, denn die Propheten Jerusalems haben die Gottlosigkeit im ganzen Land verbreitet.\"" },
      { number: 16, text: "So spricht Jahwe, der Allmächtige: \"Hört nicht auf das, was diese Propheten euch weissagen. Sie halten euch zum Narren. Ihre Visionen kommen aus ihrem Bauch und nicht von Jahwe." },
      { number: 17, text: "Zu denen, die mich verworfen haben, sagen sie: 'Jahwe hat gesagt: Das Heil ist euch sicher!' Und zu denen, die eigensinnig ihrem bösen Herzen folgen, sagen sie: 'Ihr habt nichts Schlimmes zu befürchten!'\"" },
      { number: 18, text: "Wer von ihnen stand je in der Ratsversammlung Jahwes? Wer schaute und hörte sein Wort? Wer lauschte und hörte überhaupt?" },
      { number: 19, text: "Passt auf! Ein verheerender Sturm Jahwes bricht los: sein Grimm. Ein Wirbelsturm entlädt sich über dem Kopf dieser Gottlosen." },
      { number: 20, text: "Der Zorn Jahwes wird nicht nachlassen, bis Jahwe alles ausgeführt hat, was er sich vornahm. Ganz werdet ihr das erst am Ende der von Gott bestimmten Zeit verstehen." },
      { number: 21, text: "\"Ich habe die Propheten nicht geschickt, und doch sind sie gelaufen. Ich habe nicht zu ihnen gesprochen, und doch haben sie geweissagt." },
      { number: 22, text: "Hätten sie an meiner Ratsversammlung teilgenommen, dann könnten sie meinem Volk meine Worte verkünden. Und dann würden sie es abbringen von seinem gottlosen Lebensstil und seiner Bosheit." },
      { number: 23, text: "Bin ich denn nur ein Gott in der Nähe\", spricht Jahwe, \"und nicht auch einer in der Ferne?" },
      { number: 24, text: "Oder kann sich jemand so verstecken, dass ich ihn nicht sehen könnte?\", spricht Jahwe. \"Ich bin es doch, der den Himmel und die Erde erfüllt\", spricht Jahwe." },
      { number: 25, text: "\"Ich habe gehört, was die Propheten reden, die in meinem Namen weissagen. 'Ich träumte, ich träumte', sagen sie. Doch es ist nichts als Lug und Trug." },
      { number: 26, text: "Wie lange soll das noch gehen? Haben diese Propheten, die Lügen verbreiten und ihre Hirngespinste als Weissagung ausgeben, etwa im Sinn," },
      { number: 27, text: "meinen Namen bei meinem Volk in Vergessenheit zu bringen, so wie ihre Vorfahren mich über dem Baal vergaßen? Ist das ihre Absicht, wenn sie einander ihre Träume erzählen?" },
      { number: 28, text: "Der Prophet, der einen Traum hatte, mag einen Traum erzählen. Wer aber mein Wort hat, richte mein Wort zuverlässig aus! Spreu hat doch nichts mit Weizen zu tun!\", spricht Jahwe." },
      { number: 29, text: "\"Ist mein Wort nicht wie ein Feuer\", spricht Jahwe, \"und wie ein Hammer, der Felsen zerschlägt?\"" },
      { number: 30, text: "\"Darum passt auf\", spricht Jahwe, \"jetzt gehe ich gegen die Propheten vor, die sich gegenseitig die Worte stehlen." },
      { number: 31, text: "Passt auf, jetzt gehe ich gegen die Propheten vor\", spricht Jahwe, \"die ihr eigenes Gerede Botschaft nennen." },
      { number: 32, text: "Passt auf, jetzt gehe ich gegen die vor, die erlogene Träume erzählen\", spricht Jahwe, \"und mein Volk mit ihren Lügen und ihrem Geflunker in die Irre führen. Ich habe sie weder gesandt, noch ihnen irgendetwas befohlen. Sie nützen diesem Volk überhaupt nichts\", spricht Jahwe." },
      { number: 33, text: "\"Wenn dieses Volk dich fragt oder auch ein Priester oder Prophet: 'Gibt es ein Lastwort* Jahwes?', dann sag zu ihnen: 'Ihr seid die Last! Aber ich bin schon dabei, euch abzuwerfen, spricht Jahwe.'", heading: "Die \"Last\" Jahwes", footnotes: ["Lastwort. Der hebräische Ausdruck bedeutet \"Last\" und meint in diesem und ähnlichen Zusammenhängen (z.B. Sacharja 9,1; 12,1) das Wort Jahwes, das wie eine Last auf dem Propheten liegt."] },
      { number: 34, text: "Und jeden Propheten, jeden Priester und jeden aus dem Volk, der sagt: 'Lastwort Jahwes', werde ich mit seiner ganzen Familie zur Rechenschaft ziehen." },
      { number: 35, text: "Stattdessen sollt ihr einander fragen: 'Was hat Jahwe geantwortet? Was hat Jahwe gesagt?'" },
      { number: 36, text: "Aber den Begriff 'Lastwort Jahwes' sollt ihr nicht mehr gebrauchen. Denn jedem wird sein eigenes Wort zur Last, weil er die Worte des lebendigen Gottes verdreht hat, die Worte Jahwes, des Allmächtigen, unseres Gottes!" },
      { number: 37, text: "Fragt einen Propheten also: 'Was hat Jahwe dir geantwortet?' oder: 'Was hat Jahwe gesagt?'" },
      { number: 38, text: "Wenn ihr aber weiterhin 'Lastwort Jahwes' sagt, obwohl ich euch ausrichten ließ, den Begriff 'Lastwort Jahwes' nicht mehr zu gebrauchen\", spricht Jahwe," },
      { number: 39, text: "\"dann passt auf! Ich werde euch ganz vergessen und euch samt der Stadt, die ich euch und euren Vorfahren gegeben habe, aus meiner Gegenwart entfernen." },
      { number: 40, text: "Ich stürze euch in Schimpf und Schande, was immer an euch hängen bleibt.\"" },
    ] },
    { number: 24, verses: [
      { number: 1, text: "Jahwe ließ mich zwei Feigenkörbe sehen, die vor seinem Tempel standen. Es war in der Zeit, als König Nebukadnezzar von Babylon den König Jechonja Ben-Jojakim von Juda samt den hohen Beamten Judas, den Bau- und den Metallhandwerkern als Gefangene von Jerusalem nach Babylonien verschleppt hatte.*", heading: "Gleichnis von den Feigen", footnotes: ["verschleppt hatte. Das geschah im Jahr 597 v.Chr."] },
      { number: 2, text: "Die Feigen in dem einen Korb waren sehr gut, wie Frühfeigen. Die in dem anderen Korb waren so schlecht, dass man sie nicht mehr essen konnte." },
      { number: 3, text: "Jahwe fragte mich: \"Was siehst du, Jeremia?\" Ich antwortete: \"Feigen. Die guten sind sehr gut und die schlechten so schlecht, dass man sie nicht mehr essen kann.\"" },
      { number: 4, text: "Da kam das Wort Jahwes zu mir:" },
      { number: 5, text: "\"So spricht Jahwe, der Gott Israels: 'Die aus Juda Verbannten, die ich von hier ins Land der Chaldäer vertrieben habe, sehe ich wie diese guten Feigen an." },
      { number: 6, text: "Ich werde mich ihnen wieder zuwenden und bringe sie in dieses Land zurück, wo ich sie dann aufbaue und nicht abbreche, sie einpflanze und nicht ausreiße." },
      { number: 7, text: "Ich gebe ihnen das Verständnis, mich zu erkennen, zu begreifen, dass ich es bin, Jahwe. Dann werden sie mein Volk sein und ich ihr Gott, denn sie werden mit ganzem Herzen zu mir umkehren." },
      { number: 8, text: "Aber König Zidkija von Juda und seine hohen Beamten und den Rest der Jerusalemer – ob sie nun im Land geblieben sind oder sich in Ägypten niedergelassen* haben – sehe ich als die schlechten Feigen an, die ungenießbar geworden sind.", footnotes: ["niedergelassen. Das könnten Juden sein, die beim Anmarsch Nebukadnezzars nach Ägypten geflohen waren."] },
      { number: 9, text: "Ich mache sie zum abschreckenden Beispiel des Bösen für alle Königreiche der Erde, wohin ich sie auch vertreibe. Dort werden sie mit Hohn und Spott überschüttet werden und ein Sprichwort sein." },
      { number: 10, text: "Ich lasse das Schwert, den Hunger und die Pest über sie kommen, bis sie aus dem Land verschwunden sind, das ich ihnen und ihren Vorfahren gegeben habe.'\"" },
    ] },
    { number: 25, verses: [
      { number: 1, text: "Im 4. Regierungsjahr* des Königs Jojakim Ben-Joschija von Juda – es war das erste Jahr des Königs Nebukadnezzar von Babylon – kam ein Wort für das ganze jüdische Volk zu Jeremia.", heading: "Warnung an Jojakim (25-26)\n70 Jahre Gefangenschaft", footnotes: ["Im 4. Regierungsjahr. Das war das Jahr 605 v.Chr., in dem König Jojakim sich Nebukadnezzar unterwarf."] },
      { number: 2, text: "Der Prophet Jeremia verkündete es dem Volk von Juda und den Einwohnern von Jerusalem:" },
      { number: 3, text: "\"Seit dem 13. Regierungsjahr von König Joschija Ben-Amon* habe ich 23 Jahre lang bis zum heutigen Tag das Wort Jahwes empfangen. Ich habe zu euch geredet, habe mich beizeiten aufgemacht, geredet und geredet, aber ihr habt einfach nicht zugehört.", footnotes: ["13. Regierungsjahr. Das war 626 v.Chr., als Jeremia zum Propheten berufen wurde."] },
      { number: 4, text: "Immer wieder hat Jahwe seine Diener, die Propheten, zu euch geschickt. Aber niemand von euch hat sich darum gekümmert. Niemand hörte auf ihn," },
      { number: 5, text: "wenn er sie sagen ließ: 'Kehrt doch um von euren bösen Wegen, macht Schluss mit eurem bösen Tun! Dann könnt ihr in dem Land wohnen bleiben, das Jahwe euch und euren Vorfahren für alle Zeiten gegeben hat." },
      { number: 6, text: "Und lauft nicht den fremden Göttern hinterher, um sie zu verehren und sich vor ihnen niederzuwerfen! Fordert nicht meinen Zorn heraus mit euren Machwerken, sonst bringe ich Unheil über euch!" },
      { number: 7, text: "Aber ihr habt ja nicht auf mich gehört', sagt Jahwe. 'Sondern ihr habt mich mit euren Machwerken gereizt und euch damit selbst ins Unglück gestürzt.'\"" },
      { number: 8, text: "Darum spricht Jahwe, der Allmächtige: \"Weil ihr nicht auf meine Worte gehört habt" },
      { number: 9, text: "– Passt auf! – darum hole ich alle Völker des Nordens herbei\", spricht Jahwe, \"auch meinen Diener Nebukadnezzar, den König von Babylon. Ich lasse sie über dieses Land und seine Bewohner herfallen, wie auch über die Nachbarvölker ringsum. Ich vollstrecke den Bann* an ihnen und mache sie zu einem Trümmerfeld, einem Bild des Grauens und der Verachtung.", footnotes: ["Bann. Das bedeutete die vollständige Vernichtung von Menschen, Tieren und Gütern."] },
      { number: 10, text: "Ich lasse jeden Jubelruf und jedes Freudengeschrei verstummen, auch den Ruf von Bräutigam und Braut. Man wird keine Handmühle mehr mahlen hören und kein Öllämpchen mehr leuchten sehen." },
      { number: 11, text: "Das ganze Land wird zu einem wüsten Trümmerfeld. Und all diese Völker werden siebzig Jahre lang dem König von Babylon unterworfen sein." },
      { number: 12, text: "Wenn dann die siebzig Jahre um sind, werde ich den König von Babylon und sein Volk zur Rechenschaft ziehen und ebenso das Land der Chaldäer. Ich mache es für immer zur Wüste." },
      { number: 13, text: "Ich lasse alles über dieses Land kommen, was ich ihm angedroht habe, alles, was in dieser Schriftrolle steht, was Jeremia jedem dieser Völker angekündigt hat." },
      { number: 14, text: "Ja, auch die Chaldäer werden einmal großen Völkern und mächtigen Königen dienen müssen. So lasse ich sie für alles büßen, was sie getan haben.\"" },
      { number: 15, text: "Denn so hat Jahwe, der Gott Israels, zu mir gesprochen: \"Nimm diesen Becher aus meiner Hand und gib ihn all den Völkern zu trinken, zu denen ich dich sende. Er ist voll mit dem Wein meines Zorns.", heading: "Gottes Zornbecher für die Völker" },
      { number: 16, text: "Sie sollen ihn austrinken, ins Taumeln geraten und den Verstand verlieren, wenn ich das Schwert unter ihnen wüten lasse.\"" },
      { number: 17, text: "Da nahm ich den Becher aus der Hand Jahwes und gab ihn all den Völkern zu trinken, zu denen er mich sandte." },
      { number: 18, text: "Jerusalem und die Städte Judas bekamen ihn, ihre Könige und ihre Fürsten, um sie zur Einöde zu machen, zu Stätten des Grauens, der Verachtung und des Fluches, wie es bis heute* der Fall ist.", footnotes: ["bis heute. Das meint den Zeitpunkt, als das Buch verfasst wurde."] },
      { number: 19, text: "Der Pharao, der König von Ägypten, erhielt ihn mit seinem ganzen Hof, seinen Fürsten, seinem Volk" },
      { number: 20, text: "und dem Völkergemisch in seinem Land. Die Könige des Landes Uz* bekamen ihn und alle Könige der Philisterstädte Aschkelon, Gaza, Ekron und das, was von Aschdod noch übrig geblieben ist,", footnotes: ["Uz bezeichnet ein großes Gebiet östlich der Araba, des Jordangrabens, der bis zum Golf von Elat reicht."] },
      { number: 21, text: "Edom, Moab und die Ammoniter," },
      { number: 22, text: "alle Könige von Tyrus und Sidon, und die des Küstenlandes auf der anderen Seite des Meeres." },
      { number: 23, text: "Die Leute von Dedan, Thema und Bus bekamen ihn und alle, die sich die Schläfenlocken stutzen," },
      { number: 24, text: "alle Könige Arabiens und der Wüstenstämme," },
      { number: 25, text: "alle Könige von Simri, Elam und Medien," },
      { number: 26, text: "alle Könige der nahen und fernen Länder im Norden, einer nach dem anderen, kurz, alle Könige der Erde mussten davon trinken, zuletzt der König von Scheschach*.", footnotes: ["Scheschach ist ein verschlüsselter Name für Babylon, siehe Jeremia 51,41."] },
      { number: 27, text: "\"Sag zu ihnen: 'So spricht Jahwe, der Allmächtige, Israels Gott: Trinkt, werdet betrunken und erbrecht euch, fallt hin und steht nicht wieder auf, weil mein Schwert unter euch wütet.'" },
      { number: 28, text: "Und wenn sie sich weigern, den Becher aus deiner Hand anzunehmen, dann sag ihnen: 'So spricht Jahwe, der Allmächtige: Ihr müsst ihn austrinken!" },
      { number: 29, text: "Denn seht, ich beginne mit dem Unheil bei der Stadt, die mein Eigentum ist. Solltet ihr da etwa ungeschoren davonkommen? Nein, auch euch trifft diese Strafe! Ich rufe das Schwert gegen alle Bewohner der Erde herbei, spricht Jahwe, der Allmächtige.'" },
      { number: 30, text: "Und du, weissage ihnen die folgenden Worte:'Jahwe brüllt von der Höhe herab, / es hallt aus seiner heiligen Wohnung. / Laut ruft er über seine Weide hin. / Ein Heißa! wie die Keltertreter stimmt er an / gegen alle Bewohner der Welt." },
      { number: 31, text: "Das Dröhnen dringt bis ans Ende der Erde. / Jahwe macht den Völkern den Prozess, / zieht alle Menschen vor Gericht; / die Gottlosen übergibt er dem Schwert, / spricht Jahwe.'" },
      { number: 32, text: "So spricht Jahwe, der Allmächtige:'Seht, von den Enden der Erde / erhebt sich ein gewaltiger Sturm; / ein Volk nach dem anderen / wird von dem Unheil getroffen.'" },
      { number: 33, text: "Überall auf der Erde werden die Leichen liegen, die Jahwe erschlagen hat. Niemand trauert um sie, keiner sammelt sie ein, keiner begräbt sie. Zum Dünger für die Äcker sollen sie werden." },
      { number: 34, text: "'Heult, ihr Völkerhirten und schreit! / Wälzt euch in der Asche, / ihr Mächtigen der Herde, / denn jetzt seid ihr an der Reihe, / geschlachtet zu werden. / Ich schmettere euch zu Boden / wie ein kostbares Gefäß." },
      { number: 35, text: "Verloren ist die Zuflucht der Hirten, / für die Herrlichen der Völkerherde / gibt es kein Entkommen." },
      { number: 36, text: "Hört das Geschrei der Hirten, / das Heulen der Herrscher der Herde, / denn Jahwe verwüstet ihre Weide." },
      { number: 37, text: "Der Gluthauch seines Zorns / zerstört die Auen des Friedens." },
      { number: 38, text: "Wie ein Löwe verlässt er sein Versteck, / denn ihr Land ist zur Wüste geworden / durch das furchtbare Schwert, / durch Jahwes glühenden Zorn.'\"" },
    ] },
    { number: 26, verses: [
      { number: 1, text: "Kurz nachdem Jojakim Ben-Joschija König über Juda geworden war, kam folgendes Wort Jahwes:", heading: "Jeremias zweite Tempelrede" },
      { number: 2, text: "\"So spricht Jahwe: Stell dich in den Vorhof von Jahwes Haus und rede zu allen, die aus den Städten Judas kommen, um sich im Haus Jahwes niederzuwerfen! Sag ihnen alles, was ich dir befohlen habe! Lass nichts davon aus!" },
      { number: 3, text: "Vielleicht hören sie ja darauf und jeder kehrt von seinem bösen Weg um. Dann wird es mir leidtun und ich werde das Unheil, das ich ihnen wegen der Bosheit ihrer Taten angedroht habe, nicht über sie bringen." },
      { number: 4, text: "Sag ihnen: 'So spricht Jahwe: Wenn ihr nicht auf mich hört und euch nicht an meine Weisungen haltet," },
      { number: 5, text: "wenn ihr auch nicht auf die Worte meiner Diener, der Propheten, hört – auf die ihr nie gehört habt, obwohl ich sie immer wieder zu euch gesandt habe –," },
      { number: 6, text: "dann werde ich mit diesem Haus dasselbe tun wie mit Schilo*. Und diese Stadt werde ich zu einem Fluchwort für alle Völker der Erde machen.'\"", footnotes: ["Schilo. Siehe Jeremia 7,12-14."] },
      { number: 7, text: "Die Priester, die Propheten und das ganze Volk hörten, was Jeremia im Haus Jahwes sagte." },
      { number: 8, text: "Als er zu Ende war und den Auftrag Jahwes ausgeführt hatte, packten sie ihn und schrien: \"Dafür musst du sterben!" },
      { number: 9, text: "Weshalb verkündest du im Namen Jahwes, dass es diesem Haus wie Schilo ergehen und dass diese Stadt in Trümmern liegen und menschenleer sein wird?\" Das ganze Volk rottete sich im Vorhof des Tempels gegen Jeremia zusammen." },
      { number: 10, text: "Als die führenden Männer Judas davon hörten, kamen sie vom Königspalast zum Haus Jahwes hinauf und nahmen am Eingang des Neuen Tores Platz." },
      { number: 11, text: "Die Priester und Propheten klagten Jeremia vor ihnen und dem versammelten Volk an. \"Dieser Mann verdient den Tod!\", sagten sie. \"Er hat gegen diese Stadt geweissagt. Ihr habt es ja selbst gehört.\"" },
      { number: 12, text: "Darauf erwiderte Jeremia: \"Jahwe hat mich beauftragt, gegen dieses Haus und gegen diese Stadt all das zu weissagen, was ihr gehört habt." },
      { number: 13, text: "So bessert nun euer Leben und euer ganzes Tun und hört auf Jahwe, euren Gott. Dann wird es Jahwe leidtun und er wird das Unheil nicht über euch kommen lassen." },
      { number: 14, text: "Ich selbst bin ja in eurer Hand. Macht mit mir, was ihr wollt." },
      { number: 15, text: "Doch eins sollt ihr wissen: Wenn ihr mich tötet, bringt ihr unschuldiges Blut über euch, über diese Stadt und ihre Einwohner. Denn so wahr ich hier stehe: Jahwe hat mich zu euch geschickt, um euch genau diese Worte zu überbringen.\"" },
      { number: 16, text: "Da waren sich die Oberen und das ganze Volk einig: \"Dieser Mann hat auf keinen Fall die Todesstrafe verdient, denn er hat im Namen Jahwes, unseres Gottes, zu uns gesprochen.\"" },
      { number: 17, text: "Es standen auch einige von den Ältesten des Landes auf und sagten:" },
      { number: 18, text: "\"Micha von Moreschet hat zur Zeit des Königs Hiskija von Juda geweissagt und zum ganzen Volk gesagt: 'So spricht Jahwe, der Allmächtige: Zion wird umgepflügt wie ein Acker, Jerusalem wird zu einem Trümmerhaufen und der Tempelberg zu einem bewaldeten Hügel.'*", footnotes: ["Siehe Micha 1,1;3,12."] },
      { number: 19, text: "Haben ihn der König Hiskija und das ganze Volk damals etwa getötet? Nein, Hiskija hat sich Jahwe unterworfen und ihn angefleht, sodass es Jahwe leidtat und er das Unheil nicht über sie brachte. Aber wir sind dabei, durch ein großes Unrecht unser Leben in Gefahr zu bringen!\"" },
      { number: 20, text: "Es gab damals noch einen anderen Propheten, der ganz ähnlich wie Jeremia im Namen Jahwes gegen diese Stadt und das Land Juda weissagte. Es war Urija Ben-Schemaja aus Kirjat-Jearim.", heading: "Hinrichtung des Propheten Urija" },
      { number: 21, text: "Als König Jojakim, seine Heerführer und Oberen dessen Worte hörten, wollte der König ihn töten lassen. Urija erfuhr davon, bekam Angst und floh nach Ägypten." },
      { number: 22, text: "Da schickte Jojakim Elnatan Ben-Achbor mit einigen Männern dorthin." },
      { number: 23, text: "Sie holten Urija aus Ägypten zurück und brachten ihn vor den König. Der ließ ihn mit dem Schwert hinrichten und seine Leiche auf die Gräber des einfachen Volkes werfen." },
      { number: 24, text: "Doch Jeremia entging der Hinrichtung, weil Ahikam Ben-Schafan ihn in Schutz nahm und nicht zuließ, dass er vom Volk getötet wurde." },
    ] },
    { number: 27, verses: [
      { number: 1, text: "Es war noch am Anfang der Regierungszeit des Königs Zidkija* Ben-Joschija von Juda, als ein Wort Jahwes zu Jeremia kam.", heading: "Lektion für falsche Propheten (27-29)\nDas Zeichen des Jochs", footnotes: ["Zidkija. So einige hebräische und syrische Manuskripte. Die meisten hebräischen Manuskripte lesen Jojakim (siehe aber Vers 3 und 12). Die meisten griechischen Manuskripte der LXX lassen den Vers ganz aus."] },
      { number: 2, text: "Jahwe sagte zu mir: \"Mach dir Joche aus Hölzern und Stricken und lege sie dir um den Hals." },
      { number: 3, text: "Dann gib sie den Gesandten von Edom, Moab, Ammon, Tyrus und Sidon, die zu König Zidkija nach Jerusalem gekommen sind, an ihre Könige mit." },
      { number: 4, text: "Lass sie ihren Herren ausrichten: 'So spricht Jahwe, der allmächtige Gott Israels:" },
      { number: 5, text: "Ich habe die Erde, die Menschen und die Tiere, die es auf ihr gibt, geschaffen durch meine gewaltige Kraft und Macht. Ich kann sie geben, wem ich will!" },
      { number: 6, text: "Und jetzt habe ich all diese Länder in die Hand meines Dieners Nebukadnezzar gegeben, des Königs von Babylon. Selbst die wilden Tiere habe ich in seinen Dienst gestellt." },
      { number: 7, text: "Alle Völker sollen ihm, seinem Sohn und seinem Enkel dienen, bis auch die Zeit seines Landes gekommen ist. Dann wird es großen Völkern und mächtigen Königen unterworfen werden." },
      { number: 8, text: "Doch jetzt ist es so: Das Volk oder Reich, das König Nebukadnezzar von Babylon nicht dienen will, das den Hals nicht in sein Joch steckt, spricht Jahwe, über das lasse ich Krieg, Hunger und Pest kommen, bis es ganz in seiner Gewalt ist." },
      { number: 9, text: "Hört nicht auf eure Propheten und Wahrsager, eure Träumer, Zauberer und Beschwörer, die euch einreden, dass ihr dem König von Babylon nicht dienen müsst." },
      { number: 10, text: "Denn sie lügen, wenn sie euch weissagen, und bringen euch so um eure Heimat, indem ich euch vertreibe und ihr umkommt." },
      { number: 11, text: "Aber die Nation, die ihren Hals in das Joch des Königs von Babylon steckt und ihm dient, werde ich auf ihrem heimatlichen Boden lassen, spricht Jahwe. Sie kann ihn bebauen und dort wohnen bleiben." },
      { number: 12, text: "Auch zu König Zidkija von Juda sagte ich dasselbe. Steckt eure Hälse in das Joch des Königs von Babylon und dient ihm und seinem Volk. Dann werdet ihr am Leben bleiben." },
      { number: 13, text: "Warum willst du mit deinem Volk durch Krieg, Hunger und Pest sterben, wie es Jahwe jedem Volk angedroht hat, das sich dem König von Babylon nicht unterwirft?" },
      { number: 14, text: "Hört nicht auf die Propheten, die euch sagen: Ihr werdet dem König von Babylon nicht dienen! Was sie euch weissagen ist Lüge." },
      { number: 15, text: "Denn ich habe sie nicht gesandt, spricht Jahwe. Darum ist es Lüge, was sie in meinem Namen weissagen. Die Folge wird sein, dass ich euch vertreibe und ihr samt den Propheten, die euch weissagen, umkommt.'\"" },
      { number: 16, text: "Zu den Priestern und dem ganzen Volk sagte ich: \"So spricht Jahwe: Hört nicht auf die Worte eurer Propheten, wenn sie weissagen: 'Passt auf! Die Gegenstände aus dem Haus Jahwes werden nun bald aus Babylonien zurückgebracht.' Sie lügen euch an." },
      { number: 17, text: "Hört nicht auf sie! Unterwerft euch dem König von Babylon, dann bleibt ihr am Leben! Warum soll diese Stadt ein Trümmerfeld werden?" },
      { number: 18, text: "Wenn sie wirklich Propheten sind, von denen man das Wort Jahwes erfährt, dann sollten sie Jahwe, den Allmächtigen, bestürmen, damit die Gegenstände nicht nach Babylonien kommen, die im Haus Jahwes, im Königspalast und in Jerusalem noch übrig geblieben sind." },
      { number: 19, text: "Denn so spricht Jahwe, der Allmächtige, über die Säulen, das sogenannte Meer*, die Kesselwagen und die übrigen Gegenstände,", footnotes: ["das sogenannte Meer. Siehe 1. Könige 7,23-26."] },
      { number: 20, text: "die König Nebukadnezzar von Babylon nicht mitgenommen hat, als er König Jechonja Ben-Jojakim von Juda samt den Edelleuten von Juda und Jerusalem als Gefangene nach Babylonien wegführte." },
      { number: 21, text: "Ja, so spricht Jahwe, der allmächtige Gott Israels, über die Gegenstände, die im Haus Jahwes, im Königspalast und in Jerusalem noch übrig geblieben sind:" },
      { number: 22, text: "Sie sollen nach Babylonien gebracht werden und dort so lange bleiben, bis ich mich wieder um sie kümmere, und sie an diesen Ort zurückbringe\", spricht Jahwe." },
    ] },
    { number: 28, verses: [
      { number: 1, text: "Es war noch in der Anfangszeit des Königs Zidkija von Juda, im August* seines vierten Regierungsjahrs, da sagte der Prophet Hananja Ben-Asur von Gibeon im Haus Jahwes vor den Priestern und dem Volk:", heading: "Jeremia und Hananja", footnotes: ["August. Wörtlich: im 5. Monat. Im Jahr 593 v.Chr."] },
      { number: 2, text: "\"So spricht Jahwe, der allmächtige Gott Israels: 'Ich zerbreche das Joch des Königs von Babylon." },
      { number: 3, text: "In zwei Jahren werde ich alle Gegenstände aus dem Haus Jahwes, die König Nebukadnezzar weggenommen und nach Babylonien gebracht hat, an diesen Ort zurückbringen." },
      { number: 4, text: "Auch König Jechonja* Ben-Jojakim und alle anderen, die aus Juda nach Babylonien verschleppt worden sind, bringe ich an diesen Ort zurück', spricht Jahwe, 'denn ich zerbreche das Joch des Königs von Babylon.'\"", footnotes: ["Jechonja ist eine Variante des Namens Jojachin."] },
      { number: 5, text: "Da sagte der Prophet Jeremia öffentlich vor den Priestern und dem Volk, das sich im Haus Jahwes befand, zu dem Propheten Hananja:" },
      { number: 6, text: "\"Amen! Ich wünschte, Jahwe würde das tun! Er lasse deine Worte in Erfüllung gehen und bringe die Gegenstände aus dem Haus Jahwes und alle nach Babylonien Verschleppten an diesen Ort zurück!" },
      { number: 7, text: "Aber jetzt höre, was ich vor dir und dem ganzen Volk zu sagen habe:" },
      { number: 8, text: "Die Propheten, die vor mir und dir seit ältesten Zeiten aufgetreten sind, sagten vielen Ländern und großen Reichen Krieg, Unheil und Pest voraus." },
      { number: 9, text: "Der Prophet, der Frieden ankündigt, wird als echter Prophet erkannt, wenn sein Wort eintrifft. Erst daran erweist sich, dass Jahwe ihn wirklich gesandt hat.\"" },
      { number: 10, text: "Da nahm der Prophet Hananja das Joch vom Hals des Propheten Jeremia ab und zerbrach es." },
      { number: 11, text: "Dann erklärte er vor allen Leuten: \"So spricht Jahwe: 'Ebenso werde ich in zwei Jahren das Joch des Königs Nebukadnezzar von Babylon den Völkern vom Hals nehmen und zerbrechen.'\" Daraufhin ging der Prophet Jeremia weg." },
      { number: 12, text: "Einige Zeit nachdem Hananja das Joch vom Hals Jeremias genommen und zerbrochen hatte, kam das Wort Jahwes zu Jeremia:" },
      { number: 13, text: "\"Geh und sage zu Hananja: 'So spricht Jahwe: Ein Joch aus Holz hast du zerbrochen, doch dafür kommt ein Joch aus Eisen." },
      { number: 14, text: "Denn so spricht Jahwe, der allmächtige Gott Israels: Ein eisernes Joch habe ich auf den Nacken dieser Völker gelegt; sie müssen König Nebukadnezzar von Babylon dienen. Selbst die wilden Tiere gebe ich ihm.'\"" },
      { number: 15, text: "Jeremia sagte außerdem zum Propheten Hananja: \"Hör gut zu, Hananja! Jahwe hat dich nicht gesandt. Du hast das Volk auf eine Lüge vertrauen lassen." },
      { number: 16, text: "Darum spricht Jahwe: 'Pass auf! Ich lasse dich vom Erdboden verschwinden. Dieses Jahr noch wirst du sterben, denn du hast Ungehorsam gegen Jahwe gepredigt.'\"" },
      { number: 17, text: "Der Prophet Hananja starb noch in demselben Jahr, im Oktober*.", footnotes: ["Zwei Monate nach der Weissagung Jeremias."] },
    ] },
    { number: 29, verses: [
      { number: 1, text: "Es folgt der Wortlaut des Briefes, den der Prophet Jeremia von Jerusalem aus an die übrig gebliebenen Ältesten unter den Verbannten, an die Priester, die Propheten und alle anderen schickte, die Nebukadnezzar nach Babylonien verschleppt hatte.", heading: "Ein Brief an die Verbannten" },
      { number: 2, text: "Zuvor hatten König Jechonja und die Königsmutter die Stadt verlassen samt den Hofbeamten, den Oberen von Juda und Jerusalem, den Bauleuten und den Metallhandwerkern." },
      { number: 3, text: "Jeremia schickte den Brief durch Elasa Ben-Schafan und Gemarja Ben-Hilkija, die von König Zidkija nach Babylon zu Nebukadnezzar gesandt worden waren:" },
      { number: 4, text: "\"Jahwe, der allmächtige Gott Israels, lässt allen, die er als Gefangene aus Jerusalem nach Babylonien wegführen ließ, Folgendes sagen:" },
      { number: 5, text: "'Baut euch Häuser und wohnt darin! Legt Gärten an und genießt ihre Früchte!" },
      { number: 6, text: "Heiratet und zeugt Kinder! Verheiratet eure Söhne und Töchter, damit auch sie Kinder bekommen! Eure Zahl dort soll zunehmen und nicht abnehmen." },
      { number: 7, text: "Bemüht euch um das Wohl der Stadt, in die ich euch verbannt habe, und betet für sie zu Jahwe! Denn wenn es ihr gut geht, geht es auch euch gut.'" },
      { number: 8, text: "So spricht Jahwe, der allmächtige Gott Israels: 'Lasst euch nicht täuschen von den Propheten und Wahrsagern, die unter euch sind. Hört auch nicht auf das, was ihr euch von ihnen erträumen lasst!" },
      { number: 9, text: "Denn sie weissagen euch Lügen, und das auch noch in meinem Namen. Ich habe sie nicht gesandt', spricht Jahwe." },
      { number: 10, text: "So spricht Jahwe: 'Erst wenn 70 Jahre für das babylonische Reich vorüber sind, werde ich nach euch sehen und mein gutes Wort erfüllen, euch an diesen Ort zurückzubringen." },
      { number: 11, text: "Denn ich weiß ja, was ich mit euch vorhabe', spricht Jahwe. 'Ich habe Frieden für euch im Sinn und kein Unheil. Ich werde euch Zukunft schenken und Hoffnung geben." },
      { number: 12, text: "Wenn ihr dann zu mir ruft, wenn ihr kommt und zu mir betet, will ich euch hören." },
      { number: 13, text: "Wenn ihr mich sucht, werdet ihr mich finden. Ja, wenn ihr von ganzem Herzen nach mir fragt," },
      { number: 14, text: "werde ich mich von euch finden lassen', spricht Jahwe. 'Dann wende ich euer Schicksal und sammle euch aus allen Völkern und Orten, in die ich euch versprengt habe. Ich bringe euch an den Ort zurück, aus dem ich euch verschleppen ließ.'" },
      { number: 15, text: "Weil ihr aber behauptet: 'Jahwe hat uns in Babylonien Propheten erweckt'," },
      { number: 16, text: "sagt Jahwe über den König, der auf dem Thron Davids sitzt und über das ganze Volk in der Stadt, über eure Brüder, die nicht mit in die Verbannung ziehen mussten:" },
      { number: 17, text: "So spricht Jahwe, der Allmächtige: 'Passt auf! Ich bringe Krieg, Hunger und Pest über sie. Ich behandle sie wie die abscheulichen Feigen, die so schlecht sind, dass man sie nicht mehr essen kann." },
      { number: 18, text: "Ich stelle ihnen nach mit dem Schwert, mit Hunger und Pest. Ich mache sie zu einem Bild des Schreckens für alle Königreiche der Erde, zum Fluch und zum Entsetzen, zum Hohn und Spott für die Völker, unter die ich sie versprengen werde," },
      { number: 19, text: "und zwar weil sie nicht auf mich gehört haben', spricht Jahwe. 'Immer und immer wieder habe ich meine Propheten zu ihnen gesandt, aber ihr wolltet nicht hören', spricht Jahwe." },
      { number: 20, text: "So hört nun das Wort Jahwes, ihr, die ich von Jerusalem nach Babylonien verschleppen ließ:" },
      { number: 21, text: "So spricht Jahwe, der allmächtige Gott Israels, über Ahab Ben-Kolaja und Zidkija Ben-Maaseja, die euch Lügen weissagen, und das auch noch in meinem Namen: 'Passt auf! Ich liefere sie an König Nebukadnezzar aus, damit er sie vor euren Augen hinrichten lässt." },
      { number: 22, text: "Die Verbannten werden ein Fluchwort von ihnen ableiten: Jahwe strafe dich wie Zidkija und Ahab, die der König von Babylon im Feuer rösten ließ!" },
      { number: 23, text: "Denn sie haben schändliche Dinge unter den Israeliten getan: Sie haben mit den Frauen anderer Männer Ehebruch getrieben und in meinem Namen Lügen verbreitet, Worte, die ich ihnen niemals aufgetragen habe. Ich weiß es und bin Zeuge', spricht Jahwe.\"" },
      { number: 24, text: "Zu Schemaja aus Nehelam sollst du sagen:", heading: "Jeremia und Schemaja" },
      { number: 25, text: "\"So spricht Jahwe, der allmächtige Gott Israels: Du hast in deinem eigenen Namen einen Brief an das Volk in Jerusalem geschickt und an den Priester Zefanja Ben-Maaseja und die anderen Priester dort. Du hast geschrieben:" },
      { number: 26, text: "'Jahwe hat dich zum Nachfolger des Priesters Jojada gemacht, damit Aufseher im Haus Jahwes da sind, die dafür sorgen sollen, dass jeder Verrückte, der sich als Prophet ausgibt, in Block und Halseisen gelegt wird." },
      { number: 27, text: "Warum bist du nicht gegen Jeremia aus Anatot vorgegangen, der sich bei euch als Prophet aufspielt?" },
      { number: 28, text: "Hat er uns doch nach Babylon geschrieben, dass wir noch lange hier bleiben müssen. Wir sollten Häuser bauen und darin wohnen, Gärten pflanzen und deren Früchte essen.'\"" },
      { number: 29, text: "Der Priester Zefanja hatte Jeremia diesen Brief vorgelesen." },
      { number: 30, text: "Da war das Wort Jahwes zu Jeremia gekommen:" },
      { number: 31, text: "\"Sende eine Botschaft an alle Verbannten und richte ihnen aus: 'So spricht Jahwe zu Schemaja aus Nehelam: Weil Schemaja sich bei euch als Prophet ausgegeben hat, obwohl ich ihn nicht geschickt habe, und er euch auf Lügen vertrauen ließ," },
      { number: 32, text: "darum werde ich Schemaja aus Nehelam und seine Nachkommen zur Rechenschaft ziehen. Keiner von seinen Leuten soll unter diesem Volk wohnen bleiben und das Gute erleben, das ich meinem Volk tun werde, spricht Jahwe, denn er hat Ungehorsam gegen Jahwe gepredigt.'\"" },
    ] },
    { number: 30, verses: [
      { number: 1, text: "Das Wort, das von Jahwe zu Jeremia kam:", heading: "Verheißung der Erneuerung Judas (30-33)\nBefreiung aus der Gefangenschaft" },
      { number: 2, text: "So spricht Jahwe, der Gott Israels: \"Alles, was ich dir gesagt habe, schreibe in eine Schriftrolle!" },
      { number: 3, text: "Denn seht, es wird eine Zeit kommen, in der ich das Schicksal meines Volkes Israel und Juda wende\", spricht Jahwe. \"Ich werde sie in das Land zurückbringen, das ich ihren Vorfahren gegeben habe; sie sollen es wieder in Besitz nehmen.\"" },
      { number: 4, text: "Folgendes hat Jahwe über Israel und Juda gesagt;" },
      { number: 5, text: "ja, so spricht Jahwe:\"Wir hören Angstgeschrei. / Entsetzen und kein Frieden!" },
      { number: 6, text: "Fragt doch nach und seht: / Bringt ein Mann jemals Kinder zur Welt? / Warum sehe ich da Männer / mit Händen auf den Hüften / wie Gebärende? / Warum sind ihre Gesichter so blass?" },
      { number: 7, text: "Weh, groß ist jener Tag, / keiner ist ihm gleich! / Die Nachkommen Jakobs sind in Not, / doch sie werden daraus befreit.\"" },
      { number: 8, text: "\"Es geschieht an jenem Tag\", spricht Jahwe, der Allmächtige, \"da zerbreche ich das Joch auf dir und zerreiße deine Fesseln. Fremde sollen dich nicht mehr versklaven!" },
      { number: 9, text: "Nur mir werdet ihr dienen, Jahwe, eurem Gott, und eurem König David, den ich euch erstehen lasse." },
      { number: 10, text: "Und du, mein Diener Jakob, hab keine Angst!\", spricht Jahwe. \"Israel, erschrick nicht! Denn ich will dich retten aus dem fernen Land, deine Nachkommen aus der Gefangenschaft. Jakob wird zurückkehren und in Frieden und Sicherheit leben. Niemand schreckt ihn mehr auf." },
      { number: 11, text: "Denn ich bin bei dir\", spricht Jahwe, \"um dir zu helfen. Die Völker, unter die ich euch versprengt habe, werde ich vernichten, nicht aber dich! Dich muss ich nur bestrafen, wie du es verdienst, denn ungestraft kann ich dich nicht lassen.\"" },
      { number: 12, text: "Ja, so spricht Jahwe:\"Unheilbar ist dein Bruch, / eiterig deine Wunde!" },
      { number: 13, text: "Keiner tritt für dich ein, / keiner presst den Eiter aus, / keine Haut wächst über die Wunde." },
      { number: 14, text: "Deine Liebhaber vergaßen dich alle, / sie fragten nicht mehr nach dir. / Denn wie einen Feind habe ich dich verwundet, / grausam habe ich dich bestraft / wegen deiner riesigen Schuld / und deiner zahllosen Sünden." },
      { number: 15, text: "Was schreist du über deinen Bruch / und deinen unheilbaren Schmerz? / Wegen deiner riesigen Schuld / und deiner zahllosen Sünden / tat ich dir das an." },
      { number: 16, text: "Doch alle, die dich fraßen, / werden nun selbst verzehrt; / alle, die dich bedrängten, / müssen nun in Gefangenschaft; / alle, die dich beraubten, / werden nun selbst beraubt; / alle, die dich plünderten, / gebe ich nun der Plünderung preis." },
      { number: 17, text: "Dir lasse ich die Wundhaut wachsen, / dich heile ich von deinen Wunden\", / spricht Jahwe. / \"Sie nannten dich ja schon Verstoßene: / 'Das ist Zion, nach der keiner fragt!'\"" },
      { number: 18, text: "So spricht Jahwe:\"Seht, ich stelle Jakobs Zelte wieder her, / erbarme mich über seine Wohnungen. / Auf Bergen von Schutt ersteht die Stadt neu, / der Palast auf seinem alten Platz." },
      { number: 19, text: "Lobgesang wird dort zu hören sein, / die Stimme fröhlicher Menschen. / Ich lasse mein Volk wachsen, / ihre Zahl nimmt nicht mehr ab. / Ich verschaffe ihnen so viel Ehre, / dass niemand sie mehr verachtet." },
      { number: 20, text: "Es wird ihnen gehen wie früher, / ihre Gemeinschaft besteht vor mir. / Und alle ihre Unterdrücker / ziehe ich zur Rechenschaft." },
      { number: 21, text: "Ihr Führer kommt dann aus ihrer Mitte, / ihr Herrscher stammt von ihnen selbst. / Ich erlaube ihm den Zutritt zu mir, / er darf in meiner Nähe erscheinen. / Denn wer setzt sonst sein Leben aufs Spiel, / um in meine Nähe zu kommen? / Das sagt Jahwe." },
      { number: 22, text: "Dann seid ihr wieder mein Volk, / und ich bin wieder euer Gott.\"" },
      { number: 23, text: "Passt auf! Ein verheerender Sturm Jahwes bricht los: sein Grimm. Ein Wirbelsturm entlädt sich über diese gottlosen Menschen." },
      { number: 24, text: "Der Zorn Jahwes wird nicht nachlassen, bis Jahwe alles ausgeführt hat, was er sich vornahm. Ganz werdet ihr das erst am Ende der von Gott bestimmten Zeit verstehen." },
    ] },
    { number: 31, verses: [
      { number: 1, text: "\"Dann\", spricht Jahwe, \"werde ich wieder der Gott aller Stämme Israels sein, und sie sind dann mein Volk.\"" },
      { number: 2, text: "So spricht Jahwe:\"Das Volk, das dem Schwert entkam, / fand Gnade in der Wüste. / Israel kehrt in sein Land zurück / und kommt dort zur Ruhe." },
      { number: 3, text: "Jahwe ist ihm von fern erschienen: / 'Ich hörte nie auf, dich zu lieben, / ich habe dir Treue gehalten!" },
      { number: 4, text: "Ich baue dich wieder auf, / ja, du wirst aufgebaut, / Israel, du junge Frau! / Schmück dich mit deinen Tamburinen, / geh hinaus zum Reigentanz!" },
      { number: 5, text: "Du legst wieder Weinberge an / im Bergland von Samaria. / Und wer die Pflanzung anlegt, / darf auch die Früchte genießen.'" },
      { number: 6, text: "Denn es kommt der Tag, / da rufen die Wächter auf den Bergen Efraïms: / 'Macht euch auf! / Wir ziehen nach Zion hinauf / zu Jahwe, unserem Gott!'\"" },
      { number: 7, text: "Denn so spricht Jahwe:\"Freut euch über die Nachkommen Jakobs, / jubelt über das führende Volk! / Verkündet, lobsingt und sagt: / 'Gerettet hat Jahwe sein Volk, / alles, was von ihm noch übrig war!'" },
      { number: 8, text: "Seht, ich bringe sie aus dem Norden herbei, / ich sammle sie von den Enden der Erde. / Selbst Blinde und Lahme sind unter ihnen, / Schwangere und Wöchnerinnen. / Eine große Versammlung kommt hierher zurück." },
      { number: 9, text: "Weinend kommen sie herbei. / Während sie beten, führe ich sie. / Ich bringe sie zu Bächen mit Wasser. / Sie gehen auf einem gebahnten Weg, / auf dem sie nicht fallen. / Denn ich bin Israels Vater, / und Efraïm ist mein erstgeborener Sohn.\"" },
      { number: 10, text: "Hört, ihr Völker, was Jahwe euch sagt, / verkündigt es den fernen Inseln: / \"Der Israel zersprengte, wird es wieder sammeln, / er wird es hüten wie ein Hirt seine Herde." },
      { number: 11, text: "Denn Jahwe wird Jakob erlösen, / kauft ihn vom Stärkeren los." },
      { number: 12, text: "Dann kommen sie zum Zionsberg, / jubeln auf der Höhe, / freuen sich über die Gaben Jahwes, / über Korn, Wein und Öl, / über Schafe und Rinder. / Sie sind ein bewässerter Garten, / werden nie mehr verdursten." },
      { number: 13, text: "Dann freut sich das Mädchen am Reigentanz, / Jung und Alt sind fröhlich zusammen. / Ich werde ihre Trauer in Jubel verwandeln, / schenke ihnen Glück nach all ihrem Leid." },
      { number: 14, text: "Die Priester erfreue ich mit bestem Opferfleisch, / und mein Volk mache ich mit guten Dingen satt.\"" },
      { number: 15, text: "So spricht Jahwe:\"In Rama* hört man Totenklage / und bitteres Weinen. / Rahel* weint um ihre Kinder. / Sie lässt sich nicht trösten, / denn ihre Kinder sind nicht mehr da.\"*", footnotes: ["Die Stadt Rama wurde dem Stamm Benjamin zugeteilt und lag 8 km nördlich von Jerusalem.", "Rahel war die Großmutter von Efraïm und Manasse, den Stammvätern der wichtigsten Stämme des Nordreiches Israel.", "Wird im Neuen Testament von Matthäus zitiert: Matthäus 2,18."] },
      { number: 16, text: "So spricht Jahwe:\"Erspar deiner Stimme das Weinen / und deinen Augen die Tränen! / Denn es gibt einen Lohn für deine Mühe, spricht Jahwe: / Sie kommen aus dem Land der Feinde heim." },
      { number: 17, text: "Du darfst auf eine Zukunft hoffen, spricht Jahwe. / Deine Kinder kehren in die Heimat zurück.\"" },
      { number: 18, text: "Ich habe gehört, wie Efraïm klagt: / \"Du hast mich geschlagen, und es musste so sein, / denn ich war wie ein junger störrischer Stier. / Bring mich zurück, so kehre ich um, / denn du bist Jahwe, mein Gott." },
      { number: 19, text: "Ja, nach meiner Umkehr packt mich die Reue, / nachdem ich zur Erkenntnis komme, / schlage ich mir an die Brust*. / Ich schäme mich und bin auch beschämt, / die Schuld meiner Jugend hat mich in Verruf gebracht.\"", footnotes: ["... an die Brust. Wörtlich: ... an die Oberschenkel oder Lenden. Im Orient offenbar ein Zeichen von Kummer und Trauer."] },
      { number: 20, text: "\"Ist Efraïm denn nicht mein Lieblingssohn, / das Kind, an dem ich mich freue? / Denn sooft ich ihm auch Vorwürfe mache, / muss ich immer wieder an ihn denken. / Deshalb schlägt mein Herz für ihn, / ich muss mich über ihn erbarmen\", / spricht Jahwe." },
      { number: 21, text: "\"Stell dir Wegweiser auf, / setze Meilensteine! / Überleg, wie die Straße verlief, / der Weg, den du gegangen bist! / Israel, du junge Frau, kehr heim! / Kehr heim in diese deine Städte!" },
      { number: 22, text: "Wie lange noch willst du dich sträuben, / du widerspenstige Tochter? / Denn etwas Neues erschafft Jahwe im Land: / Die Frau wird ihrem Mann zugetan sein.\"" },
      { number: 23, text: "So spricht Jahwe, der allmächtige Gott Israels: \"Wenn ich das Schicksal meines Volkes wende, wird es im Land Juda und in seinen Städten wieder heißen: 'Jahwe segne dich, du Weide der Gerechtigkeit, du heiliger Berg!'" },
      { number: 24, text: "Dann werden die Städte Judas wieder bevölkert sein. Es wird wieder Bauern geben, und Herden durchziehen das Land." },
      { number: 25, text: "Ja, ich gebe dem Erschöpften zu trinken und dem Verhungernden zu essen.\"" },
      { number: 26, text: "Darüber wachte ich auf und sah mich um. Ich hatte wunderbar geschlafen." },
      { number: 27, text: "\"Seht, es kommt eine Zeit\", spricht Jahwe, \"da säe ich über Israel und Juda eine Saat von Menschen und Vieh." },
      { number: 28, text: "Und so, wie ich darüber gewacht habe, sie auszureißen, einzureißen, abzureißen, zu vernichten und zu verheeren, werde ich nun darüber wachen, sie zu bauen und zu pflanzen\", spricht Jahwe." },
      { number: 29, text: "Dann sagen sie auch nicht mehr: \"Die Väter aßen saure Trauben, und den Söhnen wurden die Zähne stumpf.\"" },
      { number: 30, text: "Nein, jeder stirbt nur wegen seiner eigenen Schuld. Nur wer die sauren Trauben isst, wird stumpfe Zähne bekommen." },
      { number: 31, text: "\"Passt auf! Die Zeit wird kommen\", spricht Jahwe, \"da schließe ich einen neuen Bund mit Israel und Juda.", heading: "Der neue Bund" },
      { number: 32, text: "Er ist nicht mit dem zu vergleichen, den ich damals mit ihren Vätern schloss, als ich sie bei der Hand nahm und aus Ägypten herausführte. Diesen Bund haben sie gebrochen, obwohl ich doch ihr Herr war\", spricht Jahwe." },
      { number: 33, text: "\"Der neue Bund, den ich dann mit dem Volk Israel schließen werde, wird ganz anders sein\", spricht Jahwe. \"Ich schreibe mein Gesetz in ihr Herz, ich lege es tief in sie hinein. So werde ich ihr Gott sein und sie mein Volk." },
      { number: 34, text: "Dann muss keiner mehr den anderen belehren, niemand muss mehr zu seinem Bruder sagen: 'Erkenne doch Jahwe!' Denn alle werden mich erkennen, vom Geringsten bis zum Größten\", spricht Jahwe. \"Denn ich werde ihre Schuld vergeben und an ihre Sünde nie mehr denken.\"*", footnotes: ["Die Verse 31-34 werden im Neuen Testament vom Hebräerbrief zitiert: Hebräer 8,8-12; und die Verse 33-34 in Hebräer 10,16-17."] },
      { number: 35, text: "So spricht Jahwe, der die Sonne zum Licht für den Tag bestimmte und die Gesetze von Mond und Sternen zum Licht für die Nacht, der das Meer aufwühlt, dass seine Wogen dröhnen. Er heißt Jahwe, der Allmächtige." },
      { number: 36, text: "\"Wenn diese Gesetze ihre Gültigkeit verlieren sollten\", spricht Jahwe, \"dann wird auch die Nachkommenschaft Israels nicht mehr mein Volk sein.\"" },
      { number: 37, text: "So spricht Jahwe: \"Wenn man den Himmel ausmessen könnte und die Fundamente der Erde ergründen, dann könnte ich auch die Nachkommenschaft Israels verstoßen – wegen allem, was sie getan haben\", spricht Jahwe." },
      { number: 38, text: "\"Passt auf! Es kommt die Zeit\", spricht Jahwe, \"da wird diese Stadt für Jahwe wieder aufgebaut, vom Hananel-Turm bis zum Ecktor*.", heading: "Jerusalem wird wieder gebaut", footnotes: ["Hananel-Turm ... Ecktor. Das waren der östliche und der westliche Endpunkt der Nordmauer."] },
      { number: 39, text: "Und die Messschnur führt geradeaus weiter über den Gareb-Hügel und biegt dann nach Goa* ab.", footnotes: ["Gareb und Goa lagen wahrscheinlich in Westjerusalem."] },
      { number: 40, text: "Und das ganze Tal, in das man die Altarasche und das Aas hinausschafft, und alle Terrassen bis zum Kidronbach und zum Rosstor im Osten werden für Jahwe heilig sein. Nie mehr wird das alles niedergerissen, und nie wird es zerstört.\"" },
    ] },
    { number: 32, verses: [
      { number: 1, text: "Im 10. Regierungsjahr des Königs Zidkija von Juda – es war das 18. Jahr Nebukadnezzars* – kam das Wort Jahwes zu Jeremia.", heading: "Jeremia kauft ein Stück Land", footnotes: ["18. Jahr Nebukadnezzars. 587 v.Chr., ein Jahr, bevor die Stadt zerstört wurde."] },
      { number: 2, text: "Jerusalem wurde damals vom Heer des babylonischen Königs belagert, und der Prophet Jeremia wurde im Wachthof beim Königspalast gefangen gehalten." },
      { number: 3, text: "König Zidkija hatte ihn verhaften lassen, weil er geweissagt hatte: \"So spricht Jahwe: 'Passt auf! Ich lasse diese Stadt in die Hände des Königs von Babylon fallen. Er wird sie erobern." },
      { number: 4, text: "Auch König Zidkija wird der Gewalt der Chaldäer nicht entkommen, sondern ganz bestimmt dem König von Babylon in die Hände fallen. Er wird ihm Auge in Auge gegenüberstehen und von Mund zu Mund mit ihm sprechen." },
      { number: 5, text: "Nebukadnezzar wird ihn dann nach Babylon bringen, und dort wird er bleiben, bis ich ihn heimsuche*', spricht Jahwe. 'Euer Kampf gegen die Chaldäer wird vergeblich sein.'\"", footnotes: ["heimsuche. Das heißt in diesem Fall: bis zu seinem Tod, siehe Jeremia 52,11."] },
      { number: 6, text: "Jeremia berichtet: Das Wort Jahwes kam zu mir:" },
      { number: 7, text: "\"Pass auf! Hanamel, der Sohn deines Onkels Schallum, wird zu dir kommen und sagen: 'Kauf meinen Acker in Anatot, denn du hast als nächster Verwandter das Vorkaufsrecht.'\"*", footnotes: ["Vorkaufsrecht. Die Vorschriften für dieses Recht stehen in 3. Mose 25,23-31."] },
      { number: 8, text: "Wie Jahwe es angekündigt hatte, kam Hanamel zu mir in den Wachthof und sagte: \"Kauf mir doch meinen Acker in Anatot im Gebiet von Benjamin ab! Denn du hast das Erb- und Vorkaufsrecht. Bitte kauf ihn!\" Da begriff ich, dass es ein Befehl Jahwes war," },
      { number: 9, text: "und kaufte Hanamel den Acker in Anatot für 17 Silberstücke ab." },
      { number: 10, text: "Ich unterschrieb den Kaufvertrag mit den Zeugen, die ich hergebeten hatte, versiegelte das Original und wog das Silber auf der Waage ab." },
      { number: 11, text: "Den Kaufvertrag mit seinen Festlegungen und Bestimmungen, und zwar das versiegelte Original und die offene Abschrift," },
      { number: 12, text: "gab ich Baruch Ben-Nerija, dem Enkel von Machseja. Das geschah in Gegenwart meines Vetters Hanamel, der Zeugen, die den Kaufvertrag unterschrieben hatten, und der anderen Judäer, die sich im Wachthof aufhielten." },
      { number: 13, text: "Dann befahl ich Baruch vor ihnen allen:" },
      { number: 14, text: "\"So spricht Jahwe, der allmächtige Gott Israels: 'Nimm diesen Kaufvertrag, das versiegelte Original und die offene Abschrift, und bewahre sie in einem Tonkrug auf, damit sie lange erhalten bleiben." },
      { number: 15, text: "Denn so spricht Jahwe, der allmächtige Gott Israels: Man wird in diesem Land wieder Häuser, Felder und Weinberge kaufen.'\"" },
      { number: 16, text: "Nachdem ich Baruch Ben-Nerija den Kaufvertrag gegeben hatte, betete ich zu Jahwe:" },
      { number: 17, text: "\"Ach, mein Herr, Jahwe, du hast Himmel und Erde durch deine gewaltige Macht und deine große Kraft geschaffen. Dir ist nichts unmöglich." },
      { number: 18, text: "Tausenden von Generationen erweist du deine Gnade, und die Schuld der Väter zahlst du ihren Kindern heim, du großer und mächtiger Gott, dein Name ist 'Jahwe, der Allmächtige'." },
      { number: 19, text: "Großartig ist dein Rat und gewaltig deine Tat! Du achtest genau auf das, was die Menschen tun, um jedem zu geben, was sein Tun und Lassen verdient." },
      { number: 20, text: "Schon in Ägypten und bis heute hast du Zeichen und Wunder getan an Israel und auch an anderen Menschen. So hast du dir bis heute einen Namen gemacht." },
      { number: 21, text: "Du hast dein Volk Israel mit starker Hand aus Ägypten herausgeführt mit Zeichen und Wundern, mit ausgestrecktem Arm und gewaltigen Schreckenstaten" },
      { number: 22, text: "und hast ihnen dieses Land gegeben, wie du es ihren Vätern unter Eid zugesagt hast, ein Land, das von Milch und Honig überfließt." },
      { number: 23, text: "Sie kamen hinein und nahmen es in Besitz. Doch dann hörten sie nicht mehr auf dich und lebten nicht mehr nach deiner Weisung. Sie taten nichts von dem, was du ihnen befohlen hattest. Da hast du nun dieses Unheil über sie hereinbrechen lassen." },
      { number: 24, text: "Die Angriffsrampen reichen schon bis an die Stadt. Die Eroberung ist vorbereitet. Durch Schwert, Hunger und Pest ist die Stadt ja schon in der Gewalt der Chaldäer, die sie belagern. Es ist eingetroffen, was du gesagt hast, du siehst es ja selbst." },
      { number: 25, text: "Und da sagst du zu mir, ich solle Geld für einen Acker ausgeben und Zeugen dafür benennen, wo doch die Stadt schon in der Gewalt der Chaldäer ist?\"" },
      { number: 26, text: "Da kam das Wort Jahwes zu Jeremia:" },
      { number: 27, text: "\"Sieh doch, ich bin Jahwe, der Gott alles Lebendigen. Sollte mir irgendetwas unmöglich sein?" },
      { number: 28, text: "Darum pass auf! So spricht Jahwe: 'Ich lasse diese Stadt in die Hände der Chaldäer fallen, ich gebe sie in die Gewalt des Königs Nebukadnezzar von Babylon." },
      { number: 29, text: "Die Chaldäer, die diese Stadt belagern, werden sie einnehmen und in Brand stecken. Sie werden sie samt allen Häusern niederbrennen, auf deren Dachterrassen man dem Götzen Baal Räucheropfer gebracht und anderen Göttern Trankopfer gespendet hat, um mich zu beleidigen." },
      { number: 30, text: "Denn die Leute von Israel und Juda taten von ihrer Jugend an nur das, was mir missfällt. Ja, die Israeliten haben mich durch ihr Verhalten immer nur zornig gemacht', spricht Jahwe." },
      { number: 31, text: "Denn diese Stadt hat mich vom Tag ihrer Gründung an bis heute zur Weißglut gebracht, sodass ich sie nun aus meinen Augen wegschaffen muss." },
      { number: 32, text: "Es geschieht wegen der ganzen Bosheit, mit der die Leute von Israel und Juda mich herausgefordert haben, sie und ihre Könige, ihre hohen Beamten, ihre Priester und Propheten, die Männer von Juda und die Bewohner Jerusalems." },
      { number: 33, text: "Sie haben mir den Rücken zugekehrt und nicht das Gesicht. Obwohl ich sie immer wieder belehrte, hörten sie nicht und nahmen keine Belehrung an." },
      { number: 34, text: "Sie haben ihre Scheusale in das Haus gestellt, das meinen Namen trägt, und haben es so entweiht." },
      { number: 35, text: "Im Hinnomtal haben sie die Opferhöhe des Baal gebaut, um ihre Söhne und Töchter für den Moloch zu verbrennen, was ich ihnen nie befohlen habe. Niemals ist es mir in den Sinn gekommen, solche abscheulichen Taten zu verlangen und Juda in Sünde zu stürzen.\"" },
      { number: 36, text: "Nun aber spricht Jahwe, der Gott Israels, über diese Stadt, von der ihr sagt: Sie wird durch das Schwert, durch Hunger und Pest dem König von Babylon in die Hände fallen:" },
      { number: 37, text: "\"Seht, ich sammle sie aus allen Ländern, in die ich sie mit Zorn, Grimm und Wut versprengt habe. Ich bringe sie wieder an diesen Ort zurück und lasse sie hier in Sicherheit wohnen." },
      { number: 38, text: "Dann werden sie mein Volk sein und ich ihr Gott." },
      { number: 39, text: "Ich werde es bewirken, dass sie nur eins im Sinn haben und nur eins erstreben: mich allezeit zu fürchten, ihnen und ihren Kindern zum Guten." },
      { number: 40, text: "Und ich werde einen ewigen Bund mit ihnen schließen, dass ich nie aufhören werde, ihnen Gutes zu tun. Ich lege ihnen Ehrfurcht vor mir ins Herz, sodass sie sich nicht mehr von mir abwenden." },
      { number: 41, text: "Dann wird es mir ein Vergnügen sein, ihnen Gutes zu tun. Ganz gewiss pflanze ich sie in dieses Land ein und tue es von ganzem Herzen und mit ganzer Kraft.\"" },
      { number: 42, text: "Denn so spricht Jahwe: \"So wie ich all das große Unheil über dieses Volk gebracht habe, werde ich auch all das Gute über sie bringen, das ich ihnen versprach." },
      { number: 43, text: "Man wird wieder Felder kaufen in diesem Land, von dem ihr sagt: 'Es ist Ödland, ohne Menschen und Vieh, und es gehört ja schon den Chaldäern.'" },
      { number: 44, text: "Ja, man wird wieder Geld ausgeben für Äcker, man wird Kaufverträge ausstellen und vor Zeugen versiegeln. Man wird es im Gebiet von Benjamin tun, in der Umgebung von Jerusalem und in den Städten Judas, ob sie auf dem Gebirge liegen, in der Schefela* oder im Negev*. Denn ich werde ihr Schicksal wenden, spricht Jahwe.\"", footnotes: ["Schefela.Niedriges, sehr fruchtbares Hügelland, das sich in nordsüdlicher Richtung zwischen dem Gebirge und der Küstenebene des Mittelmeeres erstreckt.", "Negev. Das heiße Südland Israels, zum Teil gebirgige Wüste."] },
    ] },
    { number: 33, verses: [
      { number: 1, text: "Als Jeremia im Wachthof eingeschlossen war, kam das Wort Jahwes noch ein zweites Mal zu ihm.", heading: "Dem Ende folgt ein neuer Anfang" },
      { number: 2, text: "So spricht Jahwe, der alles geschaffen, Jahwe, der alles geformt und bereitgestellt hat, Jahwe ist sein Name:" },
      { number: 3, text: "\"Rufe mich an, dann antworte ich dir und teile dir große, unfassbare Dinge mit, von denen du nichts weißt.\"" },
      { number: 4, text: "Denn so spricht Jahwe, der Gott Israels, über die Häuser dieser Stadt und die Paläste der Könige von Juda, die abgebrochen werden, um sie gegen die Sturmwälle und für andere Kriegszwecke zu verwenden:" },
      { number: 5, text: "\"Man kommt nur, um gegen die Chaldäer zu kämpfen und die Häuser mit den Leichen der Menschen zu füllen, die ich in meiner Zornglut erschlug, weil ich mich wegen der Bosheit dieser Stadt von ihr abgewandt habe:" },
      { number: 6, text: "Seht, ich lasse eine Haut über ihre Wunde wachsen und bringe ihr Heilung. Ich stelle sie wieder her und bringe ihr echten, dauerhaften Frieden." },
      { number: 7, text: "Ich wende das Schicksal Judas und Israels und baue sie auf wie am Anfang." },
      { number: 8, text: "Ich reinige sie von all ihren Sünden, die sie gegen mich begingen, und vergebe ihnen die bösen Taten ihrer Auflehnung gegen mich." },
      { number: 9, text: "Dann werde ich mich über Jerusalem freuen, denn diese Stadt wird mir bei allen Völkern der Welt Ruhm und Ehre einbringen. Sie werden von Ehrfurcht überwältigt sein, wenn sie hören, wie viel Gutes und welchen Frieden ich dieser Stadt schenke.\"" },
      { number: 10, text: "So spricht Jahwe: \"An diesen Ort, von dem ihr sagt: 'Er ist verwüstet, ohne Menschen und Vieh', in die Städte Judas und die Straßen Jerusalems, die menschenleer sind, in denen man kein Tier mehr findet," },
      { number: 11, text: "dorthin kehren Jubel und Freude zurück. Man wird den Ruf von Bräutigam und Braut wieder hören, und das Lob von denen, die ins Haus Jahwes einziehen und sagen: 'Preist Jahwe, den Allmächtigen, denn Jahwe ist gütig und seine Gnade besteht ewig!' Denn ich werde das Schicksal des Landes wenden, und es wird sein wie am Anfang\", spricht Jahwe." },
      { number: 12, text: "So spricht Jahwe, der Allmächtige: \"An diesem Ort, der verwüstet ist, wo es keinen Menschen und kein Tier mehr gibt, und in allen umliegenden Städten wird es wieder Weideland geben, auf dem die Hirten mit ihren Herden lagern." },
      { number: 13, text: "Auch die Städte im Bergland und in der Schefela, im Land Benjamin, in der Umgebung von Jerusalem und in ganz Juda sehen wieder Herden vorüberziehen, die von den Hirten gezählt werden\", spricht Jahwe." },
      { number: 14, text: "\"Es kommt eine Zeit\", spricht Jahwe, \"da lasse ich das gute Wort in Erfüllung gehen, das ich über Israel und Juda geredet habe." },
      { number: 15, text: "In diesen Tagen, zu dieser Zeit werde ich aus der Nachkommenschaft Davids einen gerechten Mann hervorkommen lassen. Er wird im Land für Recht und Gerechtigkeit sorgen." },
      { number: 16, text: "Dann ist Juda und Jerusalem frei und sicher. Jerusalem wird dann den Namen tragen: 'Jahwe, unsere Gerechtigkeit'.\"" },
      { number: 17, text: "Denn so spricht Jahwe: \"Nie soll es dem Haus Davids an einem Mann fehlen, der auf dem Thron Israels sitzt." },
      { number: 18, text: "Auch den Priestern aus dem Stamm Levi soll es nie an einem Mann fehlen, der mir Brandopfer bringt, der das Speisopfer in Rauch aufgehen lässt und das Freudenopfer schlachtet.\"" },
      { number: 19, text: "Das Wort Jahwes kam zu Jeremia." },
      { number: 20, text: "So spricht Jahwe: \"Wenn ihr meinen Bund mit Tag und Nacht brechen könnt, sodass Tag und Nacht nicht mehr zu ihrer Zeit eintreten werden," },
      { number: 21, text: "dann könnte auch mein Bund mit meinem Diener David gebrochen werden, dass er keinen Nachkommen mehr hätte, der als König regiert. Ebenso ist es mit meinen Dienern, den levitischen Priestern." },
      { number: 22, text: "So, wie man die Sterne am Himmel nicht zählen und den Sand am Meer nicht messen kann, so werde ich die Nachkommen meines Dieners David und die Leviten zahlreich machen, die mir dienen.\"" },
      { number: 23, text: "Das Wort Jahwes kam zu Jeremia:" },
      { number: 24, text: "\"Hast du gehört, was die Leute sagen? 'Jahwe hat die beiden Stammesverbände verstoßen, die er doch selbst erwählt hatte.' So verachten sie mein Volk, als hätte es aufgehört, ein Volk zu sein.\"" },
      { number: 25, text: "So spricht Jahwe: \"Wenn ich meinen Bund mit Tag und Nacht und die Gesetze von Himmel und Erde nicht mehr bestehen ließe," },
      { number: 26, text: "dann würde ich auch die Nachkommen Jakobs und die meines Dieners David verwerfen, sodass niemand mehr aus Davids Familie über die Nachkommen von Abraham, Isaak und Jakob herrscht. Denn ich werde Erbarmen mit ihnen haben und ihr Schicksal wenden.\"" },
    ] },
    { number: 34, verses: [
      { number: 1, text: "Als König Nebukadnezzar von Babylon mit seinem ganzen Heer und den Hilfstruppen der von ihm unterworfenen Völker gegen Jerusalem und die umliegenden Städte kämpfte, kam das Wort Jahwes zu Jeremia:", heading: "Begründung für die Bestrafung durch Babel (34-39)\nZidkija vor der Entscheidung" },
      { number: 2, text: "\"So spricht Jahwe, der Gott Israels: Geh zu König Zidkija von Juda und sage ihm: 'So spricht Jahwe: Pass auf! Ich lasse diese Stadt dem König von Babylon in die Hände fallen. Er wird sie in Brand stecken." },
      { number: 3, text: "Und du, du wirst ihm auch nicht entkommen. Man wird dich fassen, du wirst in seine Hände fallen. Du wirst ihm Auge in Auge Rede und Antwort stehen müssen. Dann wirst du nach Babylon gebracht." },
      { number: 4, text: "Doch höre das Wort Jahwes, Zidkija, König von Juda! So spricht Jahwe zu dir: Sie werden dich nicht umbringen!" },
      { number: 5, text: "Du wirst in Frieden sterben, und man wird dir zu Ehren ein Feuer anzünden*, wie man es bei deinen Vorfahren tat, den früheren Königen von Juda. Und mit 'Weh, Herr!' wird man dich beklagen.' Das sage ich, Jahwe.\"", footnotes: ["Feuer anzünden. Das war keine Leichenverbrennung, sondern eine von den Nachbarvölkern übernommene Sitte, bei der Gewürze und Aromastoffe, aber auch vom Herrscher benutzte Gebrauchsgegenstände verbrannt wurden. Diese Sitte hielt sich bis zu Herodes, dem Großen."] },
      { number: 6, text: "Der Prophet Jeremia überbrachte diese Botschaft König Zidkija von Juda in Jerusalem," },
      { number: 7, text: "als das Heer des Königs von Babylon gegen Jerusalem, Lachisch und Aseka kämpfte, die Städte Judas, die noch nicht gefallen waren." },
      { number: 8, text: "Nachdem König Zidkija einen Vertrag mit den Einwohnern von Jerusalem geschlossen hatte, kam wieder ein Wort Jahwes zu Jeremia. Es war nämlich beschlossen worden,", heading: "Wortbruch an den Sklaven" },
      { number: 9, text: "dass jeder seine hebräischen Sklaven und Sklavinnen freilassen würde. Keiner sollte mehr einen jüdischen Stammesgenossen als Sklaven halten." },
      { number: 10, text: "Die Oberen und alle, die zu dem Vertrag standen, schenkten ihren Sklaven die Freiheit." },
      { number: 11, text: "Doch dann überlegten sie es sich anders und holten sie wieder zum Dienst zurück." },
      { number: 12, text: "Da kam das Wort Jahwes zu Jeremia." },
      { number: 13, text: "So spricht Jahwe, der Gott Israels: \"Als ich eure Vorfahren aus dem Sklavenhaus Ägypten herausführte, hatte ich einen Bund mit ihnen geschlossen und verlangt:" },
      { number: 14, text: "'Nach sieben Jahren soll jeder von euch seinen hebräischen Stammesbruder, der sich ihm verkauft hat, freilassen. Sechs Jahre darf er dein Sklave sein, aber dann musst du ihn in die Freiheit entlassen.' Doch eure Vorfahren hörten nicht auf mich und hielten sich nicht daran." },
      { number: 15, text: "Nun hattet ihr euch anders besonnen und habt getan, was mir gefällt. Jeder verfügte die Freilassung für seinen Nächsten. Dazu habt ihr sogar einen Vertrag in dem Haus geschlossen, das meinen Namen trägt." },
      { number: 16, text: "Aber dann habt ihr eure Meinung wieder geändert und dadurch meinen Namen geschändet. Ihr habt eure Sklaven und Sklavinnen wieder zurückgeholt, die ihr gerade in die Freiheit entlassen hattet, und habt sie erneut zum Dienst gezwungen.\"" },
      { number: 17, text: "Darum spricht Jahwe so: \"Ihr habt nicht auf mich gehört und keiner von euch hat für seinen Stammesbruder und seinen Nächsten die Freilassung bewirkt. Passt auf! Jetzt rufe ich eine Freilassung für euch aus\", spricht Jahwe. \"Ich gebe euch frei für das Schwert, die Pest und den Hunger und mache euch zu einem Bild des Schreckens für alle Völker der Welt." },
      { number: 18, text: "Und den Männern, die den Bund brachen, den sie vor mir geschlossen hatten, als sie zwischen den beiden Hälften des zerteilten Stierkalbs hindurchgingen, soll es so geschehen wie diesem Tier.*", footnotes: ["diesem Tier. Vergleiche 1. Mose 15,10."] },
      { number: 19, text: "Ich werde die führenden Männer von Juda und Jerusalem, die Hofbeamten und Priester und alle anderen, die zwischen den beiden Hälften des Stierkalbs hindurchgegangen sind," },
      { number: 20, text: "ihren Todfeinden in die Hände fallen lassen. Ihre Leichen werden den Vögeln und den wilden Tieren zum Fraß dienen." },
      { number: 21, text: "Auch König Zidkija von Juda und seine Minister liefere ich ihren Feinden aus, die nur darauf warten, sie umzubringen. Sie werden dem Heer des Königs von Babylon in die Hände fallen, das jetzt von euch abgezogen ist." },
      { number: 22, text: "Passt auf! Ich werde ihm befehlen, zu dieser Stadt zurückzukehren\", spricht Jahwe, \"um gegen sie zu kämpfen, sie zu erobern und niederzubrennen. Und die Städte Judas mache ich zu einer menschenleeren Wüste.\"" },
    ] },
    { number: 35, verses: [
      { number: 1, text: "Als König Jojakim Ben-Joschija in Juda regierte, kam das Wort Jahwes zu Jeremia:", heading: "Rechab, die vorbildliche Sippe" },
      { number: 2, text: "\"Geh zu den Männern der Sippe Rechab und lade sie in einen der Versammlungsräume im Haus Jahwes ein. Biete ihnen dort Wein an!\"" },
      { number: 3, text: "Da ging ich zu Jaasanja Ben-Jirmea, dem Enkel von Habazzinja, und holte ihn mit seinen Brüdern und Söhnen und allen Mitgliedern der Sippe Rechab" },
      { number: 4, text: "ins Haus Jahwes in den Raum, in dem sich gewöhnlich die Schüler des Gottesmannes Hanan Ben-Jigdalja versammeln. Er liegt neben dem Raum der Oberen im ersten Stock und über dem von Maaseja Ben-Schallum, dem Torwächter." },
      { number: 5, text: "Ich stellte den Männern der Sippe Rechab einige Weinkrüge hin, gab ihnen Becher und lud sie zum Weintrinken ein." },
      { number: 6, text: "Doch sie erwiderten: \"Wir trinken keinen Wein! Unser Stammvater Jonadab Ben-Rechab hat uns und unseren Nachkommen befohlen, niemals Wein zu trinken." },
      { number: 7, text: "Außerdem sagte er uns: 'Ihr dürft kein Haus bauen, keine Felder beackern und keinen Weinberg besitzen. Ihr sollt ausschließlich in Zelten wohnen, damit ihr lange lebt in dem Land, in dem ihr euch als Fremde aufhaltet.'" },
      { number: 8, text: "Wir haben auf unseren Stammvater Jonadab Ben-Rechab gehört und alle seine Weisungen befolgt. Deshalb trinken wir unser Leben lang keinen Wein, auch unsere Frauen, unsere Söhne und unsere Töchter nicht." },
      { number: 9, text: "Wir bauen uns auch keine Wohnhäuser und besitzen weder Weinberge noch Felder noch Saatgut." },
      { number: 10, text: "So haben wir in Zelten gewohnt und uns genau an das gehalten, was unser Stammvater Jonadab uns befohlen hat." },
      { number: 11, text: "Und als König Nebukadnezzar von Babylon gegen dieses Land zog, sagten wir uns: 'Kommt, wir bringen uns in Jerusalem vor dem Heer der Chaldäer und Aramäer in Sicherheit!' Nur deshalb sind wir jetzt in Jerusalem.\"" },
      { number: 12, text: "Da kam das Wort Jahwes zu Jeremia:" },
      { number: 13, text: "\"So spricht Jahwe, der allmächtige Gott Israels: Geh und verkünde den Leuten von Juda und Jerusalem: 'Soll euch das nicht eine Lehre sein, dass ihr endlich auf mich hört?' spricht Jahwe." },
      { number: 14, text: "'Was Jonadab Ben-Rechab seinen Söhnen befohlen hat, das haben sie eingehalten. Er verbot ihnen das Weintrinken, und sie haben sich bis heute daran gehalten. Sie gehorchten der Anweisung ihres Stammvaters. Ich aber habe zu euch geredet, habe beizeiten damit angefangen, habe geredet und geredet, aber ihr habt einfach nicht gehört." },
      { number: 15, text: "Immer wieder habe ich meine Diener, die Propheten, zu euch gesandt und euch sagen lassen: Kehrt doch um von euren bösen Wegen, macht Schluss mit eurem bösen Tun! Und lauft nicht den fremden Göttern nach, um ihnen zu dienen und sie anzubeten! Dann könnt ihr in dem Land wohnen bleiben, das ich euch und euren Vorfahren gegeben habe. Aber ihr habt nicht einmal zugehört, geschweige denn gehorcht!" },
      { number: 16, text: "Ja, die Nachkommen von Jonadab Ben-Rechab haben sich an die Weisung ihres Stammvaters gehalten, aber dieses Volk hat nicht auf mich gehört.'" },
      { number: 17, text: "Darum spricht Jahwe, der allmächtige Gott, der Gott Israels: 'Passt auf! Ich bringe alles Unheil über die Leute von Juda und Jerusalem, das ich ihnen angekündigt habe. Denn ich habe zu ihnen geredet, aber sie haben nicht gehört, ich habe sie angerufen, aber sie haben nicht geantwortet.'\"" },
      { number: 18, text: "Aber zu den Leuten der Sippe Rechab sagte Jeremia: \"So spricht Jahwe, der allmächtige Gott Israels: 'Weil ihr die Weisung eures Stammvaters Jonadab befolgt, seinen Anordnungen gehorcht und alles getan habt, was er euch befohlen hat," },
      { number: 19, text: "darum soll es Jonadab Ben-Rechab nie an einem männlichen Nachkommen fehlen, der mir dient', spricht Jahwe, der allmächtige Gott Israels.\"" },
    ] },
    { number: 36, verses: [
      { number: 1, text: "Im 4. Regierungsjahr* des Königs Jojakim Ben-Joschija von Juda kam das Wort Jahwes zu Jeremia:", heading: "Verbrennung der Schriftrolle", footnotes: ["4. Regierungsjahr. 605 v.Chr., ein kritisches Jahr in Judas Geschichte."] },
      { number: 2, text: "\"Nimm dir eine Schriftrolle und schreib alles hinein, was ich dir über Israel, Juda und all die anderen Völker gesagt habe, und zwar von dem Tag an, als ich zur Zeit Joschijas das erste Mal zu dir geredet habe, bis heute." },
      { number: 3, text: "Vielleicht werden die Judäer umkehren, wenn sie hören, welches Unheil ich über sie bringen will. Vielleicht geben sie ihr verkehrtes Leben auf, und ich kann ihnen ihre Schuld und Sünde vergeben.\"" },
      { number: 4, text: "Da rief Jeremia Baruch Ben-Nerija herbei und diktierte ihm alles, was Jahwe ihm gesagt hatte. Baruch schrieb es in die Rolle." },
      { number: 5, text: "Dann gab Jeremia ihm folgenden Auftrag: \"Mir wurde es untersagt, das Haus Jahwes zu betreten." },
      { number: 6, text: "Darum geh du am nächsten Fasttag* hin und lies aus der Schriftrolle die Worte Jahwes vor, die ich dir diktiert habe. Auch die Judäer, die aus ihren Städten kommen, sollen es hören.", footnotes: ["am nächsten Fasttag. Vor dem Fall Jerusalems gab es keine regelmäßigen Fasttage, sondern man rief sie in Zeiten besonderer Not aus, siehe Vers 9 und 2. Chronik 20,3; Joel 2,15."] },
      { number: 7, text: "Vielleicht werden sie den Herrn anflehen und von ihren bösen Wegen umkehren, denn Jahwe ist voller Zorn über sie und hat diesem Volk furchtbare Strafen angedroht.\"" },
      { number: 8, text: "Baruch Ben-Nerija tat alles, was der Prophet Jeremia ihm befohlen hatte, und las die Worte Jahwes im Tempel vor." },
      { number: 9, text: "Es war im Dezember* des fünften Regierungsjahres von König Jojakim. Das ganze Volk von Jerusalem und aus den Städten Judas war zu einem Fasten vor Jahwe in Jerusalem zusammengerufen worden.", footnotes: ["Dezember. Wörtlich: im 9. Monat."] },
      { number: 10, text: "Baruch las im Haus Jahwes die Worte Jeremias vor. Das geschah öffentlich im Aufenthaltsraum des Staatsschreibers Gemarja Ben-Schafan, der sich im oberen Vorhof des Tempels am Eingang des neuen Tores befand." },
      { number: 11, text: "Als Michaja, der Sohn Gemarjas und Enkel Schafans, die Worte Jahwes aus der Schriftrolle hörte," },
      { number: 12, text: "lief er zum Königspalast hinunter. Im Zimmer des Staatsschreibers saßen gerade alle Oberen zusammen: der Staatsschreiber Elischama, Delaja Ben-Schemaja, Elnatan Ben-Achbor, Gemarja Ben-Schafan, Zidkija Ben-Hananja und weitere hohe Beamte." },
      { number: 13, text: "Michaja berichtete ihnen, was Baruch dem Volk aus der Schriftrolle vorgelesen hatte." },
      { number: 14, text: "Da schickten die Oberen Jehudi Ben-Netanja, den Enkel von Schelemja Ben-Kuschi, zu Baruch mit dem Befehl: \"Nimm die Rolle, aus der du dem Volk vorgelesen hast, und komm mit!\" Baruch gehorchte und kam mit der Schriftrolle zu den Oberen." },
      { number: 15, text: "Die sagten zu ihm: \"Setz dich doch und lies uns die Schriftrolle vor.\"" },
      { number: 16, text: "Als sie alles gehört hatten, sahen sie einander erschrocken an und sagten zu Baruch: \"Das müssen wir dem König unbedingt berichten!\"" },
      { number: 17, text: "Sie fragten ihn noch: \"Wie bist du dazu gekommen, dies alles von Jeremia aufzuschreiben?\"" },
      { number: 18, text: "Baruch erwiderte: \"Er hat mir jedes Wort diktiert, und ich schrieb alles mit Tinte in die Rolle!\"" },
      { number: 19, text: "\"Ihr müsst euch verstecken, du und Jeremia\", sagten die Oberen. \"Niemand darf wissen, wo ihr seid!\"" },
      { number: 20, text: "Dann gingen sie in den Innenhof zum König und berichteten ihm alles. Die Rolle hatten sie aber im Zimmer des Staatsschreibers Elischama gelassen." },
      { number: 21, text: "Der König schickte Jehudi, um sie zu holen. Der tat es und las die Schriftrolle dem König und den Würdenträgern vor, die um ihn herum standen." },
      { number: 22, text: "Weil es Dezember war, hielt sich der König im Winterhaus auf. Vor ihm stand ein Kohlenbecken, in dem ein Feuer brannte." },
      { number: 23, text: "Immer wenn Jehudi drei oder vier Spalten gelesen hatte, schnitt der König sie mit einem scharfen Messer ab und warf sie ins Feuer, bis die ganze Schriftrolle verbrannt war." },
      { number: 24, text: "Weder der König noch seine Würdenträger erschraken über das, was sie hörten. Keiner riss sein Obergewand ein.*", footnotes: ["riss sien Obergewand ein. Als Zeichen von Trauer und Entsetzen riss man vom Halsausschnitt an das Gewand mit einem heftigen Ruck etwa eine Handlänge ein."] },
      { number: 25, text: "Dabei hatten Elnatan, Delaja und Gemarja den König dringend gebeten, die Rolle nicht zu verbrennen. Aber er hörte nicht auf sie," },
      { number: 26, text: "sondern befahl seinem Sohn Jerachmeël sowie Seraja Ben-Asriël und Schelemja Ben-Abdeel, den Propheten Jeremia und seinen Schreiber Baruch festzunehmen. Doch Jahwe hielt sie verborgen." },
      { number: 27, text: "Nachdem der König die Schriftrolle verbrannt hatte, auf der die Worte standen, die Baruch nach dem Diktat Jeremias niedergeschrieben hatte, kam das Wort Jahwes zu Jeremia:", heading: "Die neue Schriftrolle" },
      { number: 28, text: "\"Nimm dir eine neue Rolle und schreib alles hinein, was in der ersten stand, die König Jojakim verbrannt hat." },
      { number: 29, text: "Über König Jojakim von Juda aber sollst du sagen: 'So spricht Jahwe: Du hast die Schriftrolle verbrannt und dich darüber empört, dass Jeremia geschrieben hat, der König von Babylon würde dieses Land ganz bestimmt verwüsten und Menschen und Vieh daraus vertreiben." },
      { number: 30, text: "Darum spricht Jahwe über König Jojakim von Juda: Er wird keinen Nachkommen haben, der ihm auf dem Thron Davids folgt, und seine Leiche wird einfach irgendwo hingeworfen werden und der Hitze des Tages und der Kälte der Nacht ausgesetzt sein." },
      { number: 31, text: "Ich werde ihn, seine Nachkommen und seine Diener wegen ihrer Schuld zur Rechenschaft ziehen. Ich werde all das Unglück über die Bewohner Jerusalems und die Leute von Juda bringen, das ich ihnen angedroht habe, ohne dass sie darauf reagiert hätten.'\"" },
      { number: 32, text: "Da gab Jeremia seinem Schreiber Baruch eine neue Schriftrolle. Dieser schrieb nach dem Diktat Jeremias noch einmal alles auf, was schon in der ersten Rolle stand, die König Jojakim ins Feuer geworfen hatte. Und es wurden noch viele ähnliche Worte hinzugefügt." },
    ] },
    { number: 37, verses: [
      { number: 1, text: "König Nebukadnezzar von Babylon hatte Zidkija Ben-Joschija anstelle von Konja* Ben-Jojakim zum König über Juda eingesetzt.", heading: "Botschaft an König Zidkija", footnotes: ["Konja. Siehe Fußnote zu Jeremia 22,24."] },
      { number: 2, text: "Aber weder Zidkija noch seine Hofleute oder das Volk des Landes hörten auf das, was Jahwe ihnen durch den Propheten Jeremia sagen ließ." },
      { number: 3, text: "Einmal schickte König Zidkija Juchal Ben-Schelemja und den Priester Zefanja Ben-Maaseja zum Propheten Jeremia und ließ ihm sagen: \"Bete doch für uns zu Jahwe, unserem Gott!\"" },
      { number: 4, text: "Damals konnte Jeremia sich noch frei bewegen. Man hatte ihn noch nicht ins Gefängnis geworfen." },
      { number: 5, text: "Das Heer des Pharao war gerade aus Ägypten aufgebrochen, und die Chaldäer, die Jerusalem belagerten, hatten die Nachricht davon bekommen und waren von Jerusalem abgezogen." },
      { number: 6, text: "Da kam das Wort Jahwes zu dem Propheten Jeremia:" },
      { number: 7, text: "\"So spricht Jahwe, der Gott Israels: 'Richtet dem König von Juda aus, der euch zu mir geschickt hat, um mich zu befragen: Passt auf! Das Heer des Pharao, das zu eurer Hilfe ausgezogen ist, wird wieder nach Ägypten umkehren." },
      { number: 8, text: "Und die Chaldäer werden zurückkommen und diese Stadt angreifen. Sie werden sie erobern und niederbrennen.'\"" },
      { number: 9, text: "So spricht Jahwe: \"Redet euch nicht ein, dass die Chaldäer endgültig von euch abgezogen sind. Nein, sie werden nicht abziehen." },
      { number: 10, text: "Selbst wenn ihr das ganze Heer der Chaldäer schlagen könntet und nur ein paar Verwundete von ihnen in den Zelten übrig blieben, dann würden diese noch aufstehen und die Stadt niederbrennen.\"" },
      { number: 11, text: "Als das Heer der Chaldäer wegen dem anrückenden ägyptischen Heer von Jerusalem abgezogen war,", heading: "Jeremia kommt ins Gefängnis" },
      { number: 12, text: "wollte Jeremia die Stadt verlassen, um im Stammesgebiet von Benjamin an einer Erbteilung in seiner Verwandtschaft teilzunehmen." },
      { number: 13, text: "Im Benjamintor hielt ihn der wachhabende Offizier fest. Es war Jirija Ben-Schelemja, der Enkel Hananjas. \"Halt!\", rief er. \"Du willst zu den Chaldäern überlaufen.\"" },
      { number: 14, text: "\"Das ist nicht wahr!\", sagte Jeremia. \"Ich bin kein Überläufer!\" Doch Jirija glaubte ihm nicht, sondern nahm ihn fest und brachte ihn zu den Oberen." },
      { number: 15, text: "Diese wurden wütend auf Jeremia; sie schlugen ihn und ließen ihn in das Haus des Staatsschreibers Jonatan bringen, das man zum Gefängnis gemacht hatte." },
      { number: 16, text: "So kam Jeremia in einen gewölbten Keller, der vorher als Zisterne gedient hatte. Dort musste er viele Tage bleiben." },
      { number: 17, text: "Eines Tages ließ König Zidkija ihn heimlich in seinen Palast holen und fragte ihn: \"Hast du ein Wort Jahwes für mich?\" – \"Ja\", erwiderte Jeremia, \"es lautet: Du wirst dem König von Babylon in die Hände fallen.\"" },
      { number: 18, text: "Dann fragte Jeremia den König: \"Welches Verbrechen habe ich gegen dich, deine Hofleute oder das Volk begangen, dass ihr mich ins Gefängnis geworfen habt?" },
      { number: 19, text: "Wo sind denn jetzt die Propheten, die euch geweissagt haben, dass der König von Babylon euch und euer Land nicht angreifen wird?" },
      { number: 20, text: "Doch hör mich an, mein Herr und König! Ich flehe dich an! Schick mich bitte nicht ins Haus Jonatans zurück! Das wäre mein Tod.\"" },
      { number: 21, text: "Da ordnete König Zidkija an, Jeremia in den Wachthof zu verlegen. Dort bekam er täglich ein Lochbrot* aus der Bäckergasse, bis es in der Stadt kein Brot mehr gab. So blieb Jeremia im Wachthof.", footnotes: ["Lochbrot. Ein runder Brotlaib, der in der Mitte durchstoßen ist und so auf einer Stange aufgehängt werden kann zum Schutz gegen Schimmel und Tierfraß."] },
    ] },
    { number: 38, verses: [
      { number: 1, text: "Einige der Oberen des Königs, nämlich Schefatja Ben-Mattan, Gedalja Ben-Paschhur, Juchal Ben-Schelemja und Paschhur Ben-Malkija hörten, wie Jeremia im Wachthof öffentlich sagte:", heading: "Jeremia soll sterben" },
      { number: 2, text: "\"So spricht Jahwe: 'Wer in dieser Stadt bleibt, wird entweder durch das Schwert, durch den Hunger oder die Pest sterben. Wer aber hinausgeht und sich den Chaldäern ergibt, kommt mit dem Leben davon.'" },
      { number: 3, text: "So spricht Jahwe: 'Das Heer des Königs von Babylon wird diese Stadt ganz gewiss in die Hand bekommen und erobern.'\"" },
      { number: 4, text: "Die Oberen sagten zum König: \"Dieser Mann muss getötet werden! Wenn er so weiterredet, raubt er den Soldaten, die in der Stadt noch übrig sind, und dem ganzen Volk den letzten Mut. Dieser Mensch sucht nicht das Wohl des Volkes, sondern seinen Untergang.\"" },
      { number: 5, text: "\"Macht mit ihm, was ihr wollt\", sagte der König. \"Ich kann euch nicht daran hindern.\"" },
      { number: 6, text: "Da brachten sie Jeremia zur Zisterne des Prinzen Malkija und ließen ihn an Stricken hinunter. In der Zisterne war kein Wasser mehr, sondern nur Schlamm. Jeremia sank tief darin ein." },
      { number: 7, text: "Im Königspalast lebte ein Eunuch aus Nubien* namens Ebed-Melech; der hörte, dass sie Jeremia in die Zisterne gebracht hatten. Der König hielt sich gerade im Benjamintor auf.", footnotes: ["Nubien. Hebräisch: Kusch. Land am Oberlauf des Nil, südlich von Ägypten."] },
      { number: 8, text: "Da verließ Ebed-Melech den Palast und ging zum König." },
      { number: 9, text: "\"Mein Herr und König\", sagte er, \"diese Männer haben dem Propheten Jeremia übel mitgespielt. Sie haben ihn in die Zisterne geworfen. Er wird dort verhungern, denn es gibt kein Brot mehr in der Stadt.\"" },
      { number: 10, text: "Da befahl der König: \"Nimm dir dreißig Männer von hier mit und hole ihn aus der Zisterne, bevor er stirbt.\"" },
      { number: 11, text: "Ebed-Melech ging in Begleitung dieser Männer in den Königspalast und holte aus der Vorratskammer Lumpen und zerrissene Kleider. Dann ließ er diese an Stricken zu Jeremia hinunter" },
      { number: 12, text: "und rief ihm zu: \"Leg die zerlumpten Kleider unter deine Achseln, damit die Stricke nicht einschneiden.\" Jeremia tat es." },
      { number: 13, text: "Nun zogen sie ihn an den Stricken hoch und holten ihn aus der Zisterne. Jeremia blieb von da an wieder im Wachthof." },
      { number: 14, text: "Dann ließ König Zidkija den Propheten Jeremia zu sich in den dritten Eingang vom Haus Jahwes holen. Er sagte: \"Ich frage dich, ob du eine Botschaft für mich hast. Verschweige mir nichts!\"", heading: "Letzte Warnung an den König" },
      { number: 15, text: "Jeremia erwiderte: \"Wenn ich es dir sage, lässt du mich bestimmt umbringen. Und wenn ich dir einen Rat gebe, hörst du ja doch nicht darauf.\"" },
      { number: 16, text: "Da schwor der König Jeremia heimlich: \"So wahr Jahwe lebt, der uns das Leben gegeben hat: Ich lasse dich nicht töten und liefere dich auch nicht den Männern aus, die dich umbringen wollen!\"" },
      { number: 17, text: "Da sagte Jeremia zu Zidkija: \"So spricht Jahwe, der allmächtige Gott, der Gott Israels: 'Wenn du hinausgehst und dich den Heerführern des Königs von Babylon ergibst, wirst du mit deiner Familie am Leben bleiben, und diese Stadt wird nicht in Brand gesteckt." },
      { number: 18, text: "Wenn du aber nicht hinausgehst, wird die Stadt den Chaldäern in die Hände fallen und sie werden sie niederbrennen. Auch du wirst ihnen dann nicht entkommen.'\"" },
      { number: 19, text: "Der König entgegnete: \"Ich fürchte, dass die Chaldäer mich den Judäern ausliefern, die schon zu ihnen übergelaufen sind. Die würden mir sicher übel mitspielen.\"" },
      { number: 20, text: "\"Nein\", sagte Jeremia, \"man wird dich nicht ausliefern. Hör doch auf das, was Jahwe dir durch mich sagen lässt; dann geschieht dir nichts und du bleibst am Leben!" },
      { number: 21, text: "Doch wenn du dich nicht ergibst, wird geschehen, was Jahwe mir gezeigt hat." },
      { number: 22, text: "Du wirst sehen: Alle Frauen, die im Palast des Königs von Juda übrig geblieben sind, werden zu den Heerführern des Königs von Babylon hinausgeführt. Sie werden klagen:'Verführt und betrogen haben sie dich, / die Männer deines Vertrauens. / Deine Füße versanken im Sumpf, / doch sie machten sich alle davon!'" },
      { number: 23, text: "Man wird alle deine Frauen und Kinder zu den Chaldäern hinausführen. Auch du wirst ihnen nicht entkommen, sondern dem König von Babylon gefangen ausgeliefert werden. Und du wirst schuld daran sein, dass diese Stadt niedergebrannt wird.\"" },
      { number: 24, text: "Zidkija sagte noch zu Jeremia: \"Niemand darf erfahren, was wir hier besprochen haben, sonst bringen sie dich um." },
      { number: 25, text: "Und wenn die Oberen hören, dass ich mit dir geredet habe, werden sie zu dir kommen und dich ausfragen: 'Was hast du zum König gesagt? Was hat dir der König erwidert? Verschweige uns nichts, sonst bringen wir dich um!'" },
      { number: 26, text: "Dann sage ihnen nur: 'Ich habe den König dringend gebeten, mich nicht ins Haus Jonatans zurückzuschicken, denn dort würde ich sterben.'\"" },
      { number: 27, text: "Tatsächlich kamen alle Oberen zu Jeremia und fragten ihn aus. Er antwortete ihnen genauso, wie der König es ihm befohlen hatte. Da ließen sie ihn in Ruhe, denn die Sache war sonst nicht bekannt geworden." },
      { number: 28, text: "Jeremia blieb im Wachthof bis zu dem Tag, an dem Jerusalem erobert wurde." },
    ] },
    { number: 39, verses: [
      { number: 1, text: "Die Eroberung Jerusalems ging so vor sich: Es war Januar* im neunten Regierungsjahr des Königs Zidkija von Juda, als König Nebukadnezzar von Babylon mit seinem ganzen Heer begann, Jerusalem zu belagern.", heading: "Der Fall Jerusalems", footnotes: ["Januar. Nach Jeremia 52,4 war es genau am 10. Januar (wörtlich: am 10. des 10. Monats) 589 v.Chr."] },
      { number: 2, text: "Als am 9. Juli* im elften Jahr Zidkijas die Stadt aufgebrochen war,", footnotes: ["Juli. Wörtlich: 4. Monat. Im Jahr 586 v.Chr."] },
      { number: 3, text: "hielten die Heerführer des Königs von Babylon ihren Einzug und richteten ihr Hauptquartier beim Mitteltor ein. Unter ihnen waren Nergal-Sarezer* von Samgar, Nebu-Sar-Sechim*, der Palastvorsteher, und Nergal-Sarezer, der oberste königliche Berater.", footnotes: ["Nergal-Sarezer war der Schwiegersohn Nebukadnezzars und wurde unter dem Namen Nergilissar sein Nachfolger.", "Nebu-Sar-Sechim. Im Jahr 2007 wurde auf einer Lehmtafel im Britischen Museum der Name dieses babylonischen Beamten entdeckt."] },
      { number: 4, text: "Als König Zidkija und seine Soldaten das sahen, flohen sie. In der Nacht verließen sie die Stadt durch den Torweg zwischen den beiden Mauern am Königsgarten und versuchten, in Richtung der Araba* zu entkommen.", footnotes: ["Als Araba wird der Jordangraben bezeichnet, der sich von Norden nach Süden durch ganz Israel zieht, sogar noch über das Tote Meer hinaus bis nach Elat. Er ist zwischen 12,5 und 22,5 km breit und befindet sich fast überall unterhalb des Meeresspiegels, im Toten Meer 394 Meter unter NN."] },
      { number: 5, text: "Doch die chaldäischen Truppen nahmen die Verfolgung auf und holten Zidkija in der Araba bei Jericho* ein. Sie nahmen den König gefangen und brachten ihn nach Ribla* in die Provinz Hamat vor den König von Babylon, der dort das Urteil über ihn sprach.", footnotes: ["bei Jericho. Das war eine Strecke von etwa 25 km bei einem Höhenunterschied von mehr als 1000 Meter.", "Ribla. Siehe 2. Könige 23,33."] },
      { number: 6, text: "Zidkija musste zusehen, wie seine Söhne abgeschlachtet wurden. Auch die Oberen von Juda wurden in Ribla hingerichtet." },
      { number: 7, text: "Danach wurden Zidkija die Augen ausgestochen, und man brachte ihn in Ketten nach Babylon." },
      { number: 8, text: "In Jerusalem brannten die Chaldäer den Königspalast und alle anderen Häuser nieder und rissen die Stadtmauern ein." },
      { number: 9, text: "Dann ließ Nebusaradan, der Befehlshaber der Leibwache, den Rest der Einwohner und alle, die zum König von Babylon übergelaufen waren, gefangen nehmen und in die Verbannung nach Babylonien führen." },
      { number: 10, text: "Nur einige Leute vom einfachen Volk, die nichts besaßen, ließ er in Juda zurück. Ihnen gab er Äcker und Weinberge." },
      { number: 11, text: "Für Jeremia hatte König Nebukadnezzar Nebusaradan die Anweisung gegeben:", heading: "Jeremias Befreiung" },
      { number: 12, text: "\"Lass ihn holen und kümmere dich um ihn! Nimm ihn unter deinen Schutz und tu ihm ja nichts Böses an! Erfüll ihm alles, worum er dich bittet!\"" },
      { number: 13, text: "Die Oberen des Königs von Babylon – es waren Nebusaradan, der Oberbefehlshaber, Nebuschasban, der Palastvorsteher und Nergal-Sarezer, der oberste königliche Berater –" },
      { number: 14, text: "gaben den Befehl, Jeremia aus dem Wachthof zu holen. Sie übergaben ihn Gedalja Ben-Ahikam, dem Enkel Schafans, damit er ihn sicher nach Hause geleite. So blieb Jeremia beim Volk." },
      { number: 15, text: "Als Jeremia noch im Wachthof eingeschlossen war, hatte er folgende Botschaft Jahwes erhalten:" },
      { number: 16, text: "\"Geh zu Ebed-Melech, dem Nubier, und sag zu ihm: 'So spricht Jahwe, der allmächtige Gott Israels: Du wirst sehen, wie meine Worte über diese Stadt in Erfüllung gehen und das Unheil über sie hereinbricht. Du wirst es selbst miterleben." },
      { number: 17, text: "Aber dich werde ich an jenem Tag retten, spricht Jahwe. Du wirst den Leuten, vor denen du Angst hast, nicht in die Hände fallen." },
      { number: 18, text: "Ich lasse dich entkommen, damit du nicht getötet wirst. Du sollst dein Leben als Beute davontragen, weil du mir vertraut hast', spricht Jahwe.\"" },
    ] },
    { number: 40, verses: [
      { number: 1, text: "Jeremia erhielt weitere Botschaften Jahwes, nachdem Nebusaradan, der Befehlshaber der Leibwache, ihn von Rama* entlassen hatte. Jeremia hatte sich nämlich mit gefesselten Händen unter den anderen Gefangenen befunden, die nach Babylonien gebracht werden sollten.", heading: "40-45: Rebellischer Rest – falsches Asyl\nDer Überrest in Juda (40-42)\nJeremia bleibt in Juda", footnotes: ["Die Stadt Rama war dem Stamm Benjamin zugeteilt worden und lag 8 km nördlich von Jerusalem."] },
      { number: 2, text: "Der Befehlshaber der Leibwache hatte Jeremia holen lassen und zu ihm gesagt: \"Jahwe, dein Gott, hat das Unheil über diesen Ort angedroht." },
      { number: 3, text: "Nun hat er es kommen lassen, weil ihr euch an Jahwe versündigt und nicht auf ihn gehört habt." },
      { number: 4, text: "Aber dir nehme ich jetzt die Fesseln von den Händen ab. Du bist frei! Wenn du willst, kannst du mit mir nach Babylonien kommen und würdest dort unter meinem Schutz stehen. Wenn du das nicht willst, dann bleib. Das ganze Land steht dir offen, du kannst gehen, wohin du willst.\"" },
      { number: 5, text: "Weil er sich aber nicht entscheiden konnte, sagte Nebusaradan zu ihm: \"Dann geh zu Gedalja Ben-Ahikam, dem Enkel Schafans, den der König von Babylon als Statthalter über die Städte Judas eingesetzt hat! Bleib bei ihm wohnen, mitten unter deinem Volk. Du musst es aber nicht; du kannst gehen, wohin du willst.\" Der Befehlshaber der Leibwache gab ihm Verpflegung und ein Geschenk und entließ ihn." },
      { number: 6, text: "Jeremia ging zu Gedalja Ben-Ahikam nach Mizpa* und lebte dort bei den Leuten, die im Land übrig geblieben waren.", footnotes: ["Mizpa. Die Festungsstadt war dem Stamm Benjamin zugeteilt worden und lag 12 km nördlich von Jerusalem."] },
      { number: 7, text: "Einige Offiziere aus Juda waren mit ihren Männern im Landesinnern verstreut. Sie hörten, dass der König von Babylon Gedalja Ben-Ahikam zum Statthalter über Juda eingesetzt hatte und dass ihm die Männer, Frauen und Kinder der armen Landbevölkerung unterstellt worden waren, die nicht mit in die Verbannung nach Babylonien ziehen mussten.", heading: "Gedalja als Statthalter" },
      { number: 8, text: "So kamen sie zu Gedalja nach Mizpa. Es waren Jischmaël Ben-Netanja, Johanan und Jonatan Ben-Kareach, Seraja Ben-Tanhumet, die Söhne von Efai aus Netofa und Jesanja aus Maacha mit ihren Männern." },
      { number: 9, text: "Gedalja schwor ihnen und ihren Männern: \"Wenn ihr euch den Chaldäern unterwerft, habt ihr nichts zu befürchten. Bleibt im Land und dient dem König von Babylon, dann wird es euch gut gehen." },
      { number: 10, text: "Ich selbst bleibe hier in Mizpa und vertrete euch vor den Chaldäern, die zu uns kommen. Ihr könnt in den Ortschaften bleiben, wo ihr euch niedergelassen habt. Kümmert euch um die Weinlese, sammelt das Sommerobst und die Oliven ein und legt euch Vorräte an!\"" },
      { number: 11, text: "Viele Judäer waren nach Moab, zu den Ammonitern und nach Edom geflohen. Als sie hörten, dass der König von Babylon einen Rest der Bevölkerung in Juda gelassen und Gedalja zum Statthalter über sie eingesetzt hatte," },
      { number: 12, text: "kamen auch sie nach Juda zurück und meldeten sich bei Gedalja in Mizpa. Sie konnten noch eine reiche Wein- und Obsternte einbringen." },
      { number: 13, text: "Eines Tages kamen Johanan Ben-Kareach und die anderen Offiziere, die im Land geblieben waren, zu Gedalja nach Mizpa" },
      { number: 14, text: "und sagten zu ihm: \"Weißt du auch, dass Baalis, der König der Ammoniter Jischmaël Ben-Netanja losgeschickt hat, um dich zu ermorden?\" Aber Gedalja glaubte ihnen nicht." },
      { number: 15, text: "Johanan machte Gedalja sogar heimlich ein Angebot: \"Erlaube mir doch, Jischmaël Ben-Netanja umzubringen. Niemand wird es erfahren. Wir dürfen nicht zulassen, dass er dich tötet und dass alle Judäer, die sich um dich gesammelt haben, wieder zerstreut werden. So wird auch der letzte Rest von Juda zugrunde gehen.\"" },
      { number: 16, text: "Aber Gedalja erwiderte Johanan: \"Das darfst du auf keinen Fall tun, denn was du über Jischmaël sagst, ist nicht wahr.\"" },
    ] },
    { number: 41, verses: [
      { number: 1, text: "Im Oktober desselben Jahres kam Jischmaël Ben-Netanja, der Enkel Elischamas, in Begleitung von zehn anderen Männern zu Gedalja nach Mizpa. Jischmaël gehörte zur königlichen Familie und war einer von den Oberen des Königs gewesen. Als sie zusammen beim Gastmahl saßen,", heading: "Die Ermordung Gedaljas" },
      { number: 2, text: "fielen Jischmaël und seine zehn Männer plötzlich mit gezogenen Schwertern über Gedalja Ben-Ahikam her. Sie töteten den Enkel Schafans, den doch der König von Babylon als Statthalter für das Land eingesetzt hatte." },
      { number: 3, text: "Jischmaël ließ auch alle Judäer, die sich bei Gedalja in Mizpa aufhielten, niedermachen und ebenso die chaldäischen Soldaten, die er dort fand." },
      { number: 4, text: "Am nächsten Tag, als noch niemand von der Ermordung Gedaljas erfahren hatte," },
      { number: 5, text: "näherten sich 80 Männer aus Sichem, Schilo und Samaria. Sie hatten ihre Bärte abgeschnitten, ihre Gewänder eingerissen und ihre Haut blutig geritzt und wollten nach Jerusalem, um Weihrauch und Speisopfer in das Haus Jahwes zu bringen." },
      { number: 6, text: "Jischmaël Ben-Netanja ging ihnen von Mizpa aus weinend entgegen und lud sie ein: \"Kommt zu Gedalja Ben-Ahikam!\"" },
      { number: 7, text: "Als sie aber in der Stadt waren, stachen er und seine Männer sie nieder und warfen ihre Leichen in eine Zisterne." },
      { number: 8, text: "Nur zehn von ihnen ließ Jischmaël am Leben, denn sie hatten ihn angefleht: \"Töte uns nicht! Wir geben dir alle unsere Vorräte an Weizen, Gerste, Öl und Honig, die wir auf dem Feld draußen versteckt haben.\"" },
      { number: 9, text: "Die Zisterne, in die Jischmaël die Leichen jener Männer geworfen hatte, die er durch die Täuschung im Zusammenhang mit Gedalja umbringen konnte, war jene große Zisterne, die König Asa wegen der Bedrohung durch König Bascha von Israel hatte aushauen lassen. Jetzt füllte Jischmaël Ben-Netanja sie mit Leichen." },
      { number: 10, text: "Dann führte er den ganzen Rest des Volkes, der sich in Mizpa befand, gefangen weg, auch die Königstöchter, die Nebusaradan, der Befehlshaber der Leibwache, seinerzeit in die Obhut Gedaljas gegeben hatte. Jischmaël wollte mit ihnen ammonitisches Gebiet erreichen." },
      { number: 11, text: "Als Johanan Ben-Kareach und die anderen Offiziere von den Verbrechen Jischmaëls erfuhren," },
      { number: 12, text: "riefen sie ihre Truppen zusammen und verfolgten ihn. Am großen Teich von Gibeon holten sie ihn ein." },
      { number: 13, text: "Als das Volk, das bei Jischmaël war, Johanan und die anderen Offiziere sah, freuten sie sich." },
      { number: 14, text: "Und alle, die Jischmaël von Mizpa verschleppt hatte, liefen zu Johanan über." },
      { number: 15, text: "Jischmaël Ben-Netanja selbst konnte allerdings mit acht Männern entkommen und floh zu den Ammonitern." },
      { number: 16, text: "Johanan Ben-Kareach und die Offiziere bei ihm übernahmen nun die Verantwortung für den Rest des Volkes, den sie Jischmaël Ben-Netanja bei Gibeon abgejagt hatten, nachdem dieser Gedalja erschlagen und das Volk von Mizpa entführt hatte. Es waren Männer, Frauen und Kinder, auch einige Soldaten und Hofbeamte.", heading: "Der Fluchtplan" },
      { number: 17, text: "Sie zogen mit ihnen fort und machten erst vor Bethlehem bei der Herberge Kimhams Halt, um von dort aus weiter nach Ägypten zu fliehen," },
      { number: 18, text: "aus Angst vor den Chaldäern. Denn Jischmaël Ben-Netanja hatte den vom babylonischen König eingesetzten Statthalter Gedalja Ben-Ahikam erschlagen." },
    ] },
    { number: 42, verses: [
      { number: 1, text: "Da kamen alle Offiziere, auch Johanan Ben-Kareach und Jesanja* Ben-Hoschaja und das ganze Volk vom Kleinsten bis zum Größten", footnotes: ["Jesanja. Die LXX liest hier wie Kapitel 43,2 Asarja."] },
      { number: 2, text: "zum Propheten Jeremia. Sie baten ihn: \"Wir flehen dich an: Bete für uns zu Jahwe, deinem Gott! Bete für den Rest dieses Volkes, denn du siehst, wie wenige von uns übrig geblieben sind!" },
      { number: 3, text: "Bitte Jahwe, deinen Gott, dass er uns sagt, wohin wir gehen und was wir tun sollen!\"" },
      { number: 4, text: "Jeremia antwortete ihnen: \"Ich habe es gehört und will eure Bitte vor Jahwe, euren Gott, bringen, so wie ihr es gesagt habt. Und ich verspreche, dass ich euch alles mitteilen werde, was Jahwe euch antwortet; ich werde euch nichts verschweigen.\"" },
      { number: 5, text: "Sie versicherten ihm: \"Jahwe soll als wahrhaftiger und zuverlässiger Zeuge gegen uns auftreten, wenn wir uns nicht genau nach dem richten, was Jahwe, dein Gott, uns durch dich sagen lässt." },
      { number: 6, text: "Egal, ob es uns gut oder schlecht erscheint, wir wollen auf Jahwe, unseren Gott, hören, zu dem wir dich senden. Denn wenn wir auf Jahwe, unseren Gott, hören, wird es uns gut gehen.\"" },
      { number: 7, text: "Zehn Tage später kam das Wort Jahwes zu Jeremia." },
      { number: 8, text: "Da rief er Johanan Ben-Kareach, die Offiziere und das ganze Volk vom Kleinsten bis zum Größten zusammen" },
      { number: 9, text: "und sagte zu ihnen: \"So spricht Jahwe, der Gott Israels, zu dem ihr mich mit eurem Anliegen geschickt habt:" },
      { number: 10, text: "Wenn ihr in diesem Land wohnen bleibt, werde ich euch aufbauen und nicht abreißen, euch einpflanzen und nicht ausreißen. Denn das Unglück, das ich über euch hereinbrechen ließ, tut mir weh." },
      { number: 11, text: "Ihr habt jetzt Angst vor dem König von Babylon, aber ihr müsst euch nicht vor ihm fürchten\", spricht Jahwe, \"denn ich bin bei euch und werde euch aus seiner Hand retten." },
      { number: 12, text: "Ich bringe ihn dazu, dass er Erbarmen mit euch hat und euch in eurem Land bleiben lässt." },
      { number: 13, text: "Wenn ihr aber sagt: 'Nein, wir wollen nicht in diesem Land bleiben!', wenn ihr nicht auf Jahwe, euren Gott, hört" },
      { number: 14, text: "und sagt: 'Nein, wir wollen nach Ägypten ziehen und dort bleiben, wo wir nichts mehr vom Krieg sehen, keine Alarmsignale hören und nicht hungern müssen!' –" },
      { number: 15, text: "Dann höre das Wort Jahwes, Rest von Juda: So spricht Jahwe, der allmächtige Gott Israels: Wenn ihr wirklich darauf besteht, nach Ägypten auszuwandern," },
      { number: 16, text: "dann wird euch das Schwert, das ihr fürchtet, dort in Ägypten erreichen. Der Hunger, der euch Angst macht, wird dort in Ägypten hinter euch her sein und ihr werdet dort sterben." },
      { number: 17, text: "Alle Männer, die sich entschlossen haben, nach Ägypten auszuwandern, werden dort durch Schwert, Hunger und Pest sterben. Keiner wird dem Unheil entkommen, das ich über sie bringen werde." },
      { number: 18, text: "Denn so spricht Jahwe, der allmächtige Gott Israels: Genauso wie mein wütender Zorn die Bewohner Jerusalems getroffen hat, wird er auch über euch kommen, wenn ihr nach Ägypten zieht. Ihr werdet dort zum Fluch werden und zu einem Bild des Entsetzens. Man wird euer Schicksal zur Verwünschung und Beschimpfung benutzen. Und dieses Land werdet ihr nie wieder sehen.\"" },
      { number: 19, text: "\"Jahwe hat zu euch gesprochen, Rest von Juda! Zieht nicht nach Ägypten! Ihr sollt genau wissen, dass ich euch heute gewarnt habe." },
      { number: 20, text: "Ihr setzt nur euer Leben aufs Spiel! Erst schickt ihr mich zu Jahwe, eurem Gott, und sagt: 'Bete für uns zu Jahwe, unserem Gott, und teile uns dann alles mit, was er gesagt hat. Wir werden uns danach richten!'" },
      { number: 21, text: "Heute habe ich euch den Bescheid gegeben, aber ihr wollt nicht hören, was Jahwe, euer Gott, euch durch mich sagen lässt." },
      { number: 22, text: "Jetzt sollt ihr wissen, dass ihr in dem Land, in das ihr auswandern wollt, durch Schwert, Hunger und Pest sterben werdet.\"" },
    ] },
    { number: 43, verses: [
      { number: 1, text: "Als Jeremia dem Volk alles ausgerichtet hatte, was Jahwe, ihr Gott, ihm aufgetragen hatte, und zwar alle seine Worte,", heading: "Der Überrest in Ägypten (43-44)\nJeremia wird nach Ägypten verschleppt" },
      { number: 2, text: "da sagten Asarja Ben-Hoschaja und Johanan Ben-Kareach und alle überheblichen Männer: \"Du lügst! Jahwe, unser Gott, spricht nicht durch dich! Er kann nicht gesagt haben, dass wir nicht nach Ägypten auswandern sollen!" },
      { number: 3, text: "Baruch Ben-Nerija hat dich gegen uns aufgehetzt. Er will, dass wir den Chaldäern in die Hände fallen, damit sie uns umbringen oder uns nach Babylonien verschleppen.\"" },
      { number: 4, text: "So hörten Johanan Ben-Kareach, die Offiziere und das ganze Volk nicht auf den Befehl Jahwes, im Land Juda zu bleiben." },
      { number: 5, text: "Unter der Führung von Johanan und den anderen Offizieren machten sich alle auf den Weg: die Leute aus Juda, die in die Nachbarländer geflohen und dann zurückgekehrt waren," },
      { number: 6, text: "die Männer, Frauen und Kinder, die Königstöchter und alle übrigen Leute, die Nebusaradan, der Befehlshaber der Leibwache, bei Gedalja Ben-Ahikam, dem Enkel Schafans, zurückgelassen hatte. Auch Jeremia und Baruch nahmen sie mit." },
      { number: 7, text: "Sie zogen nach Ägypten, weil sie nicht auf die Anordnung Jahwes hören wollten. So kamen sie nach Tachpanhes." },
      { number: 8, text: "In Tachpanhes kam das Wort Jahwes zu Jeremia:", heading: "Nebukadnezzar wird auch nach Ägypten kommen" },
      { number: 9, text: "\"Nimm einige große Steine und vergrabe sie vor den Augen jüdischer Männer in die Sandbettung der Ziegelterrasse am Eingang zum Palast des Pharao." },
      { number: 10, text: "Dann sag zu ihnen: 'So spricht Jahwe, der allmächtige Gott Israels: Passt auf! Ich werde meinen Diener Nebukadnezzar, den König von Babylon, hierher holen. Über diesen Steinen hier, die ich vergraben habe, werde ich ihn seinen Thron stellen lassen. Und darüber wird er sein Prunkzelt spannen." },
      { number: 11, text: "Ja, er wird in Ägypten einfallen und es besiegen. Wer dann für den Tod bestimmt ist, wird sterben, wer für die Gefangenschaft bestimmt ist, wird in die Verbannung müssen, und wer für das Schwert bestimmt ist, verfällt dem Schwert." },
      { number: 12, text: "Ich werde Feuer an die Tempel der ägyptischen Götter legen. Nebukadnezzar wird sie niederbrennen und wegschaffen. Wie ein Hirt sein Gewand entlaust, wird er Ägypten von seinen Göttern entlausen. Dann zieht er sich unbehelligt wieder zurück." },
      { number: 13, text: "Auch die Obelisken, die spitzen Säulen von Hierapolis, wird er zertrümmern, wenn er die Häuser der Götter Ägyptens verbrennt.'\"" },
    ] },
    { number: 44, verses: [
      { number: 1, text: "Wort Jahwes, das zu Jeremia kam und für alle Judäer bestimmt war, die sich in Migdol*, Tachpanhes, Memphis* und in Oberägypten niedergelassen hatten:", heading: "Die Rede in Ägypten", footnotes: ["Migdol war eine Stadt im Norden Unterägyptens, in der auch Juden lebten.", "Memphis. Siehe Fußnote zu Jeremia 2,16."] },
      { number: 2, text: "So spricht Jahwe, der allmächtige Gott Israels: \"Ihr habt das ganze Unheil gesehen, das ich über Jerusalem und alle Städte Judas gebracht habe. Nun liegen sie in Trümmern und sind menschenleer." },
      { number: 3, text: "Das haben ihre Bewohner durch ihre Bosheit verschuldet. Sie haben fremden Göttern Räucheropfer gebracht und ihnen gedient, obwohl weder sie noch ihre Vorfahren sie kannten. So haben sie mich zum Zorn gereizt." },
      { number: 4, text: "Immer wieder habe ich meine Diener, die Propheten, zu euch geschickt, immer wieder von neuem. 'Tut doch nicht diese abscheulichen Dinge, die ich hasse!', sagte ich." },
      { number: 5, text: "Aber niemand hörte auf mich. Sie haben sich nicht darum gekümmert und sind nicht umgekehrt, sondern haben weiterhin diesen Göttern Räucheropfer gebracht." },
      { number: 6, text: "Da ließ ich meinem Zorn freien Lauf. Sie bekamen meinen Ärger zu spüren. Er brannte in den Städten Judas und auf den Straßen von Jerusalem. Noch heute liegt alles in Trümmern, niemand wohnt mehr dort.\"" },
      { number: 7, text: "Und nun spricht Jahwe, der allmächtige Gott Israels: \"Warum richtet ihr solch ein großes Unheil gegen euch selbst an? Warum rottet ihr euch selber aus: Männer, Frauen, Kinder, Säuglinge, bis keiner von euch mehr übrig bleibt?" },
      { number: 8, text: "Mit eurem Tun schaufelt ihr euch das eigene Grab. Auch hier in Ägypten, wohin ihr ausgewandert seid, bringt ihr fremden Göttern Räucheropfer. Ihr selbst rottet euch aus und macht euch für alle Völker der Erde zum Fluch und zum Gespött." },
      { number: 9, text: "Habt ihr denn all das Böse vergessen, das eure Väter getan haben, die bösen Taten der Könige von Juda und ihrer Frauen? Habt ihr auch eure eigenen bösen Taten vergessen, die ihr und eure Frauen in Juda und auf den Straßen Jerusalems getan habt?" },
      { number: 10, text: "Bis heute haben sie sich nicht gebeugt. Sie fürchten sich nicht und leben nicht nach meinen Weisungen und Geboten, die ich euch und euren Vorfahren gegeben habe.\"" },
      { number: 11, text: "Darum spricht Jahwe, der allmächtige Gott Israels: \"Passt auf! Ich bin entschlossen, Unglück über euch zu bringen, das zur Ausrottung von ganz Juda führt." },
      { number: 12, text: "Ich werde den Rest von Juda wegraffen, nämlich alle, die unbedingt nach Ägypten auswandern wollten. Hier im Land Ägypten sollen sie fallen. Durch Schwert und Hunger sollen sie aufgerieben werden, vom Kleinsten bis zum Größten, durch Schwert und Hunger sollen sie sterben! Sie sollen zum Fluch und zu einem Bild des Entsetzens werden, zur Verwünschung und zum Gespött." },
      { number: 13, text: "So wie ich Jerusalem bestraft habe mit Schwert, Hunger und Pest, werde ich es auch mit denen tun, die in Ägypten wohnen." },
      { number: 14, text: "Unter dem Rest von Juda, der nach Ägypten ausgewandert ist, wird es keine Überlebenden geben, keine Entkommenen, die nach Juda zurückkehren, obwohl sie sich danach sehnen, wieder dort zu wohnen. Nur Einzelne werden es schaffen.\"" },
      { number: 15, text: "Alle Männer, die wussten, dass ihre Frauen fremden Göttern Räucheropfer brachten, und alle Frauen, von denen viele dabeistanden, und das ganze Volk, das jetzt in Oberägypten wohnte, erwiderten Jeremia:", heading: "Der offene Abfall" },
      { number: 16, text: "\"Was du uns da im Namen Jahwes gesagt hast, wollen wir nicht hören." },
      { number: 17, text: "Nein, wir werden genau das tun, was wir versprochen haben. Wir werden der Himmelskönigin* Räucheropfer bringen und Trankopfer spenden, wie wir es früher in den Städten Judas und auf den Straßen Jerusalems getan haben, genauso wie unsere Väter, unsere Könige und Oberen. Damals ging es uns gut. Wir hatten genug zu essen und blieben von Unglück verschont.", footnotes: ["Himmelskönigin. Siehe Fußnote zu Jeremia 7,18."] },
      { number: 18, text: "Seitdem wir aber aufgehört haben, der Himmelskönigin Räucheropfer zu bringen und Trankopfer zu spenden, geht es uns in jeder Hinsicht schlecht und wir werden durch Schwert und Hunger aufgerieben." },
      { number: 19, text: "Und wenn wir der Himmelskönigin Räucheropfer gebracht und Trankopfer gespendet haben, haben wir das dann etwa ohne unsere Männer getan? Haben wir vielleicht ohne ihre Zustimmung Opferkuchen nach dem Bild der Himmelskönigin gebacken und ihr Trankopfer gespendet?\"" },
      { number: 20, text: "Jeremia erwiderte dem Volk, den Männern und Frauen, die ihm so geantwortet hatten:" },
      { number: 21, text: "\"Eben dieses Räucheropfer ist es, das ihr in den Städten Judas und auf den Straßen Jerusalems gebracht habt, genauso wie eure Väter, eure Könige und Oberen und das ganze Volk des Landes. Das ist es, was Jahwe bis ins Herz getroffen hat. Er hat es wohl gemerkt" },
      { number: 22, text: "und konnte euer abscheuliches und bösartiges Tun nicht mehr ertragen. Darum ist das Land ein menschenleeres Trümmerfeld geworden, zum Fluch und zum Entsetzen." },
      { number: 23, text: "Gerade weil ihr Räucheropfer gebracht und gegen Jahwe gesündigt habt, weil ihr nicht auf Jahwes Weisung gehört, euch nicht nach seinem Gesetz, seinen Ordnungen und Mahnungen gerichtet habt, ist dieses Unheil bis heute über euch gekommen.\"" },
      { number: 24, text: "Jeremia sagte zum ganzen Volk, besonders zu den Frauen: \"Hört das Wort Jahwes hier in Ägypten, ihr Leute aus Juda:" },
      { number: 25, text: "So spricht Jahwe, der allmächtige Gott Israels: Ihr Männer und Frauen, ihr haltet, was ihr versprochen habt. Ihr sagt: 'Wir wollen unsere Gelübde erfüllen, die wir abgelegt haben: Wir wollen der Himmelskönigin Räucheropfer bringen und Trankopfer spenden!' Nun gut, dann haltet eure Versprechen und erfüllt eure Gelübde!" },
      { number: 26, text: "Aber hört auch, was Jahwe euch sagt, ihr Judäer in Ägypten: Passt auf! Ich habe bei meinem großen Namen geschworen, spricht Jahwe: Keiner von euch in Ägypten soll je wieder meinen Namen in den Mund nehmen und sagen: 'So wahr Jahwe, der Herr, lebt!'" },
      { number: 27, text: "Denn ich wache über sie, aber nicht mehr zum Guten, sondern zum Bösen! Alle Judäer in Ägypten sollen durch Schwert und Hunger aufgerieben werden, bis sie vernichtet sind." },
      { number: 28, text: "Nur wenige werden dem Schwert entkommen und aus Ägypten wieder nach Juda zurückkehren; es wird ein ganz kleines Häuflein sein. Doch der ganze Rest von Juda, der nach Ägypten ausgewandert ist, wird erkennen, welches Wort sich bestätigt, meins oder ihres." },
      { number: 29, text: "An folgendem Zeichen, spricht Jahwe, werdet ihr erkennen, dass ich euch an diesem Ort zur Rechenschaft ziehe und dass meine Drohungen ganz gewiss eintreffen werden." },
      { number: 30, text: "So spricht Jahwe: Passt auf! Ich werde Pharao Hofra, den König von Ägypten, seinen Todfeinden in die Hände fallen lassen, so wie ich König Zidkija von Juda seinem Todfeind, König Nebukadnezzar von Babylon, ausgeliefert habe.\"" },
    ] },
    { number: 45, verses: [
      { number: 1, text: "Es war im vierten Regierungsjahr des Königs Jojakim Ben-Joschija, als Baruch die von Jeremia diktierten Worte in die Schriftrolle schrieb, da erhielt der Prophet Jeremia eine Botschaft für Baruch.", heading: "Der übrig gebliebene Baruch (45)\nEine Botschaft für Baruch" },
      { number: 2, text: "\"So spricht Jahwe, der Gott Israels, über dich, Baruch:" },
      { number: 3, text: "'Du klagst: Ich unglücklicher Mensch. Jahwe bringt auch noch Kummer in meinen Schmerz! Vom vielen Stöhnen bin ich erschöpft und finde keine Ruhe!'" },
      { number: 4, text: "Du sollst ihm Folgendes sagen: 'So spricht Jahwe: Schau her, was ich gebaut habe, breche ich ab; was ich gepflanzt habe, reiße ich aus, und zwar im ganzen Land." },
      { number: 5, text: "Und da hoffst du auf große Dinge für dich? Tu das nicht! Schau, ich bringe Unheil über alle Menschen, spricht Jahwe, aber du darfst dein Leben als Beute davontragen, wohin du auch kommst.'\"" },
    ] },
    { number: 46, verses: [
      { number: 1, text: "Wort Jahwes, das zu dem Propheten Jeremia kam und gegen die Völker gerichtet war:", heading: "46-51: Rebellische Nachbarn – Gottes Gericht\nEs trifft die Ägypter (46)\nÄgyptens Niederlage am Euphrat" },
      { number: 2, text: "Über Ägypten: Gegen das Heer des Pharao Necho, des Königs von Ägypten, das bei Karkemisch am Euphrat stand und das König Nebukadnezzar von Babylon geschlagen hat. Es war im vierten Regierungsjahr* des Königs Jojakim Ben-Joschija von Juda.", footnotes: ["im vierten Regierungsjahr. Im Jahr 605 v.Chr. machte Pharao Necho den zweiten Versuch, das vom Untergang bedrohte Assyrien gegen die Babylonier zu stützen, und zog mit einem Heer bis an den Euphrat. Er musste eine vernichtende Niederlage bei Karkemisch hinnehmen und dann noch einmal bei Hamat."] },
      { number: 3, text: "\"Haltet die Rund- und Langschilde bereit! / Rückt heran zum Kampf!" },
      { number: 4, text: "Spannt die Pferde an, / sitzt auf, ihr Reiter! / Tretet an mit Helm / und schärft die Speere! / Legt die Panzer an!" },
      { number: 5, text: "– Weshalb muss ich das sehen? / Sie weichen bestürzt zurück. / Ihre Helden zerstreuen sich, / sie ergreifen die Flucht, / sehen sich nicht um. / 'Schrecken ringsum!', spricht Jahwe." },
      { number: 6, text: "Auch der Schnellste kann nicht fliehen, / der Stärkste sich nicht retten. / Im Norden, am Ufer des Euphrat, / da sind sie gestürzt und gefallen." },
      { number: 7, text: "Wer schwoll da an wie der Nil, / dessen Ströme das Land überfluten?" },
      { number: 8, text: "Ägypten schwoll an wie der Nil, / seine Wasser wogten wie Ströme. / Es sagte: 'Ich steige an und bedecke die Erde, / vernichte Städte und ihre Bewohner!'" },
      { number: 9, text: "Ihr Pferde, bäumt euch auf! / Stürmt los, ihr Wagen! / Ihr Helden, rückt aus: / Ihr Männer mit Schilden / aus Nubien und Libyen, / ihr Bogenschützen Afrikas." },
      { number: 10, text: "- Doch dieser Tag gehört Jahwe, / dem allmächtigen Gott. / Es ist ein Rachetag für ihn. / Er rächt sich an seinen Feinden. / Da frisst das Schwert sich satt, / betrinkt sich an ihrem Blut. / Denn ein Schlachtfest hält Jahwe, der Herr, / der allmächtige Gott, am Euphrat, / im Land des Nordens." },
      { number: 11, text: "Geh nach Gilead und hole dir Salbe, / du junge Frau und Tochter von Ägypten! / Doch vergeblich häufst du dir Heilmittel auf, / deine Wunde heilt nicht mehr zu!" },
      { number: 12, text: "Die Völker haben von deiner Schande gehört, / die Welt vernahm dein Klagegeschrei. / Ein Kriegsheld ist über den anderen gestürzt, / keiner kam mit dem Leben davon.\"" },
      { number: 13, text: "Als König Nebukadnezzar von Babylon anrückte, um Ägypten zu erobern, sprach Jahwe zum Propheten Jeremia:", heading: "Die Eroberung Ägyptens" },
      { number: 14, text: "\"Sagt es den Ägyptern, / lasst es Migdol und Memphis / und Tachpanhes hören! / Sagt: Stell dich auf und mach dich bereit! / Denn schon frisst das Schwert alles um dich weg!" },
      { number: 15, text: "Warum sind deine Starken niedergestreckt? / Sie hielten nicht stand, / weil Jahwe sie zu Boden stieß." },
      { number: 16, text: "Er hat viele stürzen lassen, / einer fiel über den anderen. / Da riefen sie einander zu: / Auf, zurück zu unserem Volk in unsere Heimat! / Nur weg aus diesem grausamen Kampf!" },
      { number: 17, text: "Gebt dem Pharao als neuen Namen: / 'Großmaul, dessen Zeit vorüber ist'!\"" },
      { number: 18, text: "\"So wahr ich lebe\", spricht der König, / er heißt Jahwe, der allmächtige Gott, / \"wie der Tabor über den Bergen, / wie der Karmel über dem Meer, / so wird der sein, der gegen dich kommt!" },
      { number: 19, text: "Pack dein Fluchtgepäck, / du sesshafte Tochter Ägyptens! / Denn Memphis wird zur Wüste werden, / verbrannt und ohne Bewohner.\"" },
      { number: 20, text: "\"Ägypten ist wie eine prachtvolle Kuh, / die Bremse aus dem Norden fällt über sie her." },
      { number: 21, text: "Auch seine Söldner sind wie gemästete Kälber, / auch sie ergreifen die Flucht, / keiner von ihnen hält stand. / Ihr Unglückstag ist gekommen, / die Zeit der Abrechnung ist da." },
      { number: 22, text: "Ägypten zischt wie eine fliehende Schlange, / denn die Feinde ziehen mit Heeresmacht heran. / Sie kommen wie Holzfäller mit Äxten" },
      { number: 23, text: "und holzen den ganzen Wald ab\", spricht Jahwe, / \"den Wald, der undurchdringlich ist. / Zahlreicher als Heuschrecken sind sie, / niemand kann sie zählen." },
      { number: 24, text: "Ägypten erntet Verachtung, / es fällt dem Volk des Nordens in die Hände.\"" },
      { number: 25, text: "Es spricht Jahwe, der allmächtige Gott Israels: \"Seht, ich rechne ab mit Amon, dem Gott von Theben, mit Ägypten und seinen Göttern, mit dem Pharao und allen, die auf ihn vertrauen." },
      { number: 26, text: "Ich liefere sie ihren Todfeinden aus: Nebukadnezzar, dem König von Babylon, und seinen Soldaten. Doch später soll Ägypten wieder bewohnt sein wie in alten Zeiten\", spricht Jahwe." },
      { number: 27, text: "\"Habt keine Angst, ihr Nachkommen Jakobs, / Israel, lass dir nicht bange sein! / Denn seht, ich rette euch aus fernem Land, / eure Kinder aus dem Land, in dem sie Gefangene sind. / Jakob wird wieder Frieden und Sicherheit haben, / niemand schreckt ihn mehr auf.", heading: "Trost für Israel" },
      { number: 28, text: "Hab keine Angst, mein Diener Jakob!\", spricht Jahwe. / \"Denn du stehst unter meinem Schutz! / Ja, ich vernichte alle Völker, unter die ich euch zerstreute. / Doch dich werde ich niemals vernichten. / Dich muss ich nur bestrafen, wie du es verdienst, / denn ungestraft kannst du nicht bleiben!\"" },
    ] },
    { number: 47, verses: [
      { number: 1, text: "Noch bevor der Pharao Gaza angriff*, empfing der Prophet Jeremia eine Botschaft für die Philister.", heading: "Es trifft Israels Nachbarn (47-49)\nBotschaft gegen die Philister", footnotes: ["Gaza angriff. Das bezieht sich wahrscheinlich auf das Jahr 609 v.Chr., als Pharao Necho nach Norden zog, um gegen die Babylonier zu kämpfen."] },
      { number: 2, text: "So spricht Jahwe:\"Seht, aus dem Norden droht eine Flut. / Das Wasser wird zum reißenden Strom. / Es überschwemmt das Land und die Felder, / die Städte und ihre Bewohner. / Die Menschen schreien um Hilfe, / im ganzen Land schreien sie laut, /" },
      { number: 3, text: "denn sie hören das Stampfen der Pferde, / das Getöse der Wagen, / das Rasseln der Räder. / Da sehen sich die Väter nicht nach ihren Söhnen um, / so hat die Angst sie gepackt" },
      { number: 4, text: "vor dem kommenden Tag, der alle Philister vernichtet, / der für Tyrus und Sidon die letzten Helfer erschlägt. / Denn Jahwe vernichtet die Philister, / den Rest dieser Leute von Kreta. /" },
      { number: 5, text: "Gaza hat sich kahl geschoren, / und Aschkelon, die letzte Stadt der Ebene, / ist ganz verstummt. / Wie lange noch ritzt du dich vor Trauer wund?" },
      { number: 6, text: "Weh, du Schwert Jahwes, / wie lange noch willst du nicht rasten? / Kehr zurück in deine Scheide, / raste und bleib still!\"" },
      { number: 7, text: "Doch wie soll es ruhig bleiben? / Denn Jahwe gab ihm den Befehl. / Er hat es an die Küste bestellt / und auch gegen die von Aschkelon." },
    ] },
    { number: 48, verses: [
      { number: 1, text: "Über Moab*. So spricht Jahwe, der allmächtige Gott Israels:\"Weh den Bewohnern von Nebo, / ihre Stadt ist verwüstet. / Schande über Kirjatajim, / denn es wurde besiegt. / Die Felsburg ist beschämt und geschleift.", heading: "Botschaft gegen Moab", footnotes: ["Die Moabiter lebten östlich vom Toten Meer zwischen den Flüssen Arnon und Zered. Die genaue Lage der nachfolgend genannten moabitischen Städte ist unbekannt."] },
      { number: 2, text: "Mit Moabs Ruhm ist es vorbei! / In Heschbon* hat man seinen Untergang geplant: / 'Kommt, wir rotten sie aus der Völkerwelt aus!' / Auch du, Madmen, wirst bald verschwinden, / das Schwert kommt hinter dir her.", footnotes: ["Heschbon gehörte einmal zum Stamm Ruben und wurde auch von Leuten aus dem Stamm Gad bewohnt. Zur Zeit Jeremias gehörte die Stadt den Ammonitern (Jeremia 49,3)."] },
      { number: 3, text: "Horch! Aus Horonajim hört man Geschrei: / 'Alles ist verwüstet, ein großer Trümmerhaufen!'" },
      { number: 4, text: "Moab ist gebrochen, / die Kleinen hört man schreien." },
      { number: 5, text: "Beim Aufstieg nach Luhit weinen sie laut, / am Hang von Horonajim hört man entsetzliches Geschrei." },
      { number: 6, text: "Flieht und rettet euer Leben! / Seid wie ein Wacholder in der Wüste!" },
      { number: 7, text: "Weil du auf deine Werke und Schätze vertrautest, / wirst auch du bezwungen werden. / Dein Gott Kemosch wird in die Verbannung geführt, / seine Priester und die Oberen dazu." },
      { number: 8, text: "Der Verwüster kommt in jede Stadt, / keine kommt davon. / Im Jordantal wird alles vernichtet / und die Hochebene völlig zerstört, / wie Jahwe es befohlen hat." },
      { number: 9, text: "Gebt Moab Flügel, damit es entfliehe im Flug. / Seine Städte werden zu Wüsten, in denen keiner mehr wohnt." },
      { number: 10, text: "Verflucht, wer Jahwes Werk nachlässig tut, / verflucht, wer sein Schwert beim Blutvergießen hemmt.\"" },
      { number: 11, text: "Von Jugend an war Moab sorgenfrei, / wie Wein durfte es ungestört lagern, / niemals umgegossen von Fass zu Fass, / nie musste es in die Gefangenschaft. / So ist ihm sein Geschmack geblieben, / sein Geruch veränderte sich nicht." },
      { number: 12, text: "\"Deshalb ist jetzt der Tag nicht mehr fern\", spricht Jahwe, / \"da schicke ich ihm Kellermeister. / Diese füllen Moab um. / Sie leeren seine Fässer aus / und zerschlagen seine Krüge." },
      { number: 13, text: "Von Kemosch, seinem Gott, wird Moab bitter enttäuscht, / wie Israel von dem Stierbild in Bet-El*, auf das es sich verließ.\"", footnotes: ["Bet-El = Haus Gottes. Jakob hatte hier einen Altar gebaut (1. Mose 35,1-15). Der Ort lag etwa 19 km nördlich von Jerusalem im Gebirge Efraïm."] },
      { number: 14, text: "Wie könnt ihr sagen: \"Wir sind Helden, / Männer, zum Kampf geboren\"?" },
      { number: 15, text: "Moab ist verwüstet, / seine Städte wurden erstürmt, / und seine besten jungen Männer / wurden zur Schlachtbank geführt. / Das sagt der König. / Er heißt \"Jahwe, der allmächtige Gott\"." },
      { number: 16, text: "Moabs Untergang steht nahe bevor, / sein Unglück kommt sehr schnell herbei." },
      { number: 17, text: "Sprecht ihm euer Beileid aus, / ihr Nachbarn und alle Bekannten, und klagt: / \"Wie schnell zerbrachen ihm Ruhm und Macht!\"" },
      { number: 18, text: "Steig herab von deinem Ehrenplatz / und setz dich in den Staub, / du Einwohnerin, Tochter von Dibon! / Denn Moabs Verwüster kommt auch gegen dich, / und wird deine Festungen zerstören." },
      { number: 19, text: "Stellt euch an die Straße / und schaut, was da kommt, / ihr Leute von Aroer! / Fragt die Flüchtlinge, / sprecht die Entkommenen an! / Fragt: \"Was ist passiert?\"" },
      { number: 20, text: "Sie werden euch sagen: \"Mit Moab ist es aus! / Es ist schmachvoll zerbrochen. / Heult und schreit um Hilfe! / Sagt auch den Leuten am Arnonfluss: / 'Moab ist vernichtet!'\"" },
      { number: 21, text: "Das Strafgericht kam über das Hochland, / über Holon, Jahaz und Mefaat," },
      { number: 22, text: "über Dibon, Nebo und Bet-Diblatajim," },
      { number: 23, text: "über Kirjatajim, Bet-Gamul und Bet-Meon," },
      { number: 24, text: "über Kerijot und Bozra und alle Städte Moabs, / die fernen und die nahen." },
      { number: 25, text: "\"Die stolze Macht Moabs brach ab wie ein Horn, / seine Kraft ist gebrochen wie ein Arm\", spricht Jahwe." },
      { number: 26, text: "Macht Moab betrunken – denn gegen Jahwe spielte es sich auf –, damit es hinklatscht in sein Erbrochenes / und selber zum Gelächter wird!" },
      { number: 27, text: "Oder diente Israel dir nicht zum Gespött? / Hast du es denn beim Diebstahl erwischt, / dass du spöttisch den Kopf geschüttelt hast, / sooft du von ihm sprachst?" },
      { number: 28, text: "Verlasst die Städte und wohnt in den Felsen, / ihr Bewohner von Moab! / Macht es wie die Tauben, die nisten / an den Wänden der offenen Schlucht." },
      { number: 29, text: "Wir haben gehört von Moabs Stolz – denn stolz ist es über jedes Maß –, von seinem Hochmut, seinem Geltungsdrang / und seiner Überheblichkeit." },
      { number: 30, text: "\"Auch mir ist seine Überheblichkeit bekannt\", spricht Jahwe, / \"und sein unaufrichtiges Geschwätz, / das seinen Taten nicht entspricht.\"" },
      { number: 31, text: "Darum klage ich laut über Moab, / ich schreie um Hilfe für dieses Volk. / Ja, man stöhnt über Kir-Heres." },
      { number: 32, text: "Und mehr als über Jaser / weine ich über dich, / du Weinstock von Sibma. / Deine Ranken reichten bis ans Meer, / bis ans Meer von Jaser. / Doch über Sommerobst und Weinernte kam der Verwüster." },
      { number: 33, text: "Verschwunden sind Freude und Jubelgeschrei / aus dem Garten und dem ganzen Land. / Kein Traubensaft fließt in die Fässer, / kein Winzer keltert, / der laute Ruf ist kein Jubelruf mehr." },
      { number: 34, text: "In Heschbon rufen die Menschen um Hilfe, man hört sie bis Elale und Jahaz. Man klagt von Zoar bis nach Horonajim, ja, bis nach Eglat-Schelischija, denn auch das Wasser der Oase von Nimrim wird zur Wüste werden." },
      { number: 35, text: "\"So beende ich in Moab\", spricht Jahwe, \"den Aufstieg zur Opferhöhe und den Götzendienst.\"" },
      { number: 36, text: "Mein Herz ist tief erschüttert um Moab, es klagt wie eine Trauerflöte um die Leute von Kir-Heres. Sie haben alles verloren, was sie besaßen." },
      { number: 37, text: "Jeder Kopf ist kahl vor Trauer, und jeder Bart ist geschoren. Alle Hände sind blutig geritzt, der Trauersack ist angezogen." },
      { number: 38, text: "Über allen Dachterrassen Moabs und auf allen Plätzen hört man es klagen. \"Ich habe Moab zerschlagen wie ein Gefäß, das keiner mehr will\", spricht Jahwe." },
      { number: 39, text: "Ach, wie ist Moab zerbrochen! Wie hat es sich schmachvoll zur Flucht gewandt. So ist es allen seinen Nachbarn zum Gespött und zum Entsetzen geworden." },
      { number: 40, text: "Denn so spricht Jahwe:\"Seht! Wie ein Adler schießt er heran, / breitet seine Flügel gegen Moab aus. /" },
      { number: 41, text: "Genommen ist die Stadt, / die Festung ist erobert. / Die tapferen Männer bekommen Angst / wie eine Frau in den Wehen." },
      { number: 42, text: "Moab wird als Volk vernichtet, / weil es sich gegen Jahwe erhob." },
      { number: 43, text: "Grauen und Grube und Garn über dich, / Bewohner von Moab\", spricht Jahwe." },
      { number: 44, text: "\"Wer vor dem Grauen flieht, / fällt in die Grube. / Und wer es schafft herauszukommen, / verfängt sich im Netz. / Denn ich bringe über sie / das Jahr ihrer Abrechnung\", / spricht Jahwe." },
      { number: 45, text: "Erschöpfte Flüchtlinge / suchen in Heschbon Schutz. / Doch Feuer geht von Heschbon aus, / eine Flamme schlägt aus Sihons Palast. / Sie hat die Schläfen Moabs versengt, / den Scheitel der lärmenden Schreier." },
      { number: 46, text: "Weh dir Moab! / Du bist verloren, Volk des Kemosch, / denn deine Söhne kommen in Gefangenschaft, / deine Töchter in die Verbannung." },
      { number: 47, text: "\"Doch am Ende der bestimmten Zeit / wende ich Moabs Schicksal\", spricht Jahwe.Bis hierher geht das Gerichtswort über Moab." },
    ] },
    { number: 49, verses: [
      { number: 1, text: "Über die Ammoniter. So spricht Jahwe:\"Hat Israel denn keine Söhne, / besitzt es keine Erben? / Warum nahm ihr König Gad* in Besitz? / Warum hat sein Volk dessen Städte besetzt?", heading: "Botschaft gegen Ammon", footnotes: ["Gad meint das Gebiet im Ostjordanland, das dem israelitischen Stamm Gad gehörte."] },
      { number: 2, text: "Darum seht, es kommen Tage\", spricht Jahwe, / \"da lasse ich den Kriegslärm dröhnen / gegen Rabba* in Ammon. / Es soll zu einem Schutthaufen werden, / und seine Tochterstädte gehören den Flammen. / Dann wird Israel die beerben, / die an sein Erbe wollten\", / spricht Jahwe.", footnotes: ["Rabba war die Hauptstadt der Ammoniter, 38 km östlich vom Jordan, heute: Amman."] },
      { number: 3, text: "Heule, Heschbon, / denn verwüstet ist Ai. / Schreit, ihr Töchter von Rabba, / und zieht den Trauersack an! / Rennt klagend in den Mauern umher, / denn der König geht in die Gefangenschaft, / die Priester und die Oberen dazu." },
      { number: 4, text: "Was rühmst du dich deiner fruchtbaren Täler, du abtrünnige Tochter? Du vertraust auf deine Schätze und sagst: \"Wer kommt schon gegen mich an?\"" },
      { number: 5, text: "\"Pass auf! Ich bringe Schrecken von allen Seiten über dich\", spricht Jahwe, der Herr, der allmächtige Gott. \"Ihr sollt vertrieben werden, und zwar jeder für sich. Niemand wird die Flüchtigen sammeln." },
      { number: 6, text: "Doch später wende ich das Schicksal der Ammoniter\", spricht Jahwe." },
      { number: 7, text: "Über Edom. So spricht Jahwe, der allmächtige Gott:\"Ist keine Weisheit mehr in Teman? / Fällt den Klugen dort nichts mehr ein? / Ist ihr Verstand denn verrostet?", heading: "Botschaft gegen Edom" },
      { number: 8, text: "Flieht, kehrt um, / verkriecht euch in die Höhlen, / ihr Bewohner von Dedan! / Jetzt rechne ich mit Esau ab / und lasse sein Verhängnis über ihn kommen." },
      { number: 9, text: "Wenn Winzer über dich kommen, / lassen sie nichts für die Nachlese übrig; / sind es Diebe in der Nacht, / zerstören sie nach Herzenslust." },
      { number: 10, text: "Denn ich holte Esau aus dem Versteck, / ich gab seine Schlupfwinkel preis; / er kann sich nicht mehr verstecken. / Vernichtet wird seine Nachkommenschaft, / auch Brüder und Nachbarn gibt es nicht mehr." },
      { number: 11, text: "Überlass mir deine Waisen, ich sorge für sie; / deine Witwen können mir vertrauen!\"" },
      { number: 12, text: "Denn so spricht Jahwe: \"Seht! Die nicht verurteilt waren, mussten den Becher austrinken. Und da solltest ausgerechnet du verschont bleiben? Nein, du kommst nicht ungestraft davon, du musst ihn leeren!" },
      { number: 13, text: "Denn ich habe bei mir selbst geschworen\", spricht Jahwe, \"dass Bozra* zu einem Bild des Grauens werden soll, zum Gegenstand des Spotts, zum Inbegriff der Verwüstung, zum Anlass eines Fluchs, zum ewigen Trümmerhaufen.\"", footnotes: ["Bozra, nicht zu verwechseln mit dem aus Kapitel 48,24, war zur Zeit Jeremias vermutlich die Hauptstadt von Edom."] },
      { number: 14, text: "Ich erhielt die Botschaft von Jahwe: / Ein Bote ist zu den Völkern gesandt: / \"Sammelt euch und zieht gegen Edom, / tretet an zum Kampf!\"" },
      { number: 15, text: "\"Ja, ich mache dich klein unter den Völkern, / lasse dich von den Menschen verachten!" },
      { number: 16, text: "Deine Furcht erweckende Macht / und dein Übermut verführten dich. / Ja, du wohnst in Felsenklüften, / hältst die hohen Berge besetzt. / Und baust du dein Nest so hoch wie der Adler, / ich stürze dich dennoch hinab!\", spricht Jahwe." },
      { number: 17, text: "\"Edom wird zu einem Ort des Grauens werden. Wer an ihm vorüberzieht, erschrickt und schüttelt über seine Wunden den Kopf." },
      { number: 18, text: "Wie nach dem Untergang von Sodom und Gomorra und ihren Nachbarstädten\", spricht Jahwe, \"wird niemand mehr in Edom wohnen. Kein Mensch wird sich dort aufhalten." },
      { number: 19, text: "Seht, wie ein Löwe komme ich aus dem Jordandickicht zum immergrünen Weideplatz. Ich jage sie plötzlich davon und setze meinen Erwählten dort ein. Denn wer ist mir gleich und wer lädt mich vor Gericht? Und welcher Hirt könnte sich mir widersetzen?\"" },
      { number: 20, text: "Darum hört, was Jahwe über Edom beschlossen hat, was er über die Bewohner von Teman denkt:Wie eine Herde schleppt man sie fort, / selbst die Kinder und die Schwachen. / Ihr eigenes Land ist entsetzt über sie." },
      { number: 21, text: "Vom Dröhnen ihres Falls erbebt die Erde. / Noch am Schilfmeer hört man ihr Geschrei." },
      { number: 22, text: "Seht! Wie ein Adler schießt er heran, / breitet seine Flügel gegen Bozra aus. / Und tapfere Männer bekommen Angst an jenem Tag, / wie eine Frau in den Wehen." },
      { number: 23, text: "Über Damaskus.\"Bestürzt sind Hamat und Arpad. / Sie erhielten eine schlimme Nachricht, / und sie vergehen vor Angst. / Auch an der Küste ist man sehr besorgt. / Niemand kommt mehr zur Ruhe.", heading: "Botschaft gegen Damaskus" },
      { number: 24, text: "Damaskus ist mutlos geworden, / es wendet sich zur Flucht. / Panik ist in der Stadt. / Von Angst und Wehen sind sie gepackt / wie eine gebärende Frau." },
      { number: 25, text: "Man hätte sie verlassen sollen, / die Stadt des Ruhmes, / die Burg meiner Freude." },
      { number: 26, text: "Darum werden ihre jungen Männer / auf ihren Plätzen fallen. / Alle Krieger kommen um an jenem Tag\", / spricht Jahwe, der allmächtige Gott." },
      { number: 27, text: "\"Ich lege ein Feuer / an die Mauern von Damaskus; / es verzehrt die Paläste Ben-Hadads.\"" },
      { number: 28, text: "Über die Beduinen von Kedar* und die Königreiche von Hazor, die König Nebukadnezzar von Babylon schlug*. So spricht Jahwe:\"Auf, zieht gegen Kedar! / Bezwingt die Beduinen im Osten!\"", heading: "Botschaft gegen arabische Stämme", footnotes: ["Kedar. Nomadenstamm in der syrisch-arabischen Wüste, bekannt durch seine Herden.", "Königreiche ... schlug. Die Stämme der syrisch-arabischen Wüste wurden 598 v.Chr. von Nebukadnezzar angegriffen und ausgeplündert."] },
      { number: 29, text: "Man raubt ihre Zelte und Herden, / ihre Decken und den Hausrat. / Auch ihre Kamele nimmt man mit / und ruft dabei: \"Schrecken überall!\"" },
      { number: 30, text: "\"Flieht! Bringt euch schnell in Sicherheit! Haltet euch in Höhlen versteckt, Bewohner von Hazor\", spricht Jahwe. \"Denn König Nebukadnezzar von Babylon hat es auf euch abgesehen. Sein Plan gegen euch steht fest!\"" },
      { number: 31, text: "Denn Jahwe hat gesprochen: \"Auf, zieht gegen das sorglose Volk, das in Sicherheit wohnt! Es lebt allein und hat weder Tore noch Riegel." },
      { number: 32, text: "Nun werden ihre Kamele zur Beute, und alle ihre Herden werden geraubt. Ich werde die mit den gestutzten Schläfenlocken in alle Himmelsrichtungen zerstreuen und lasse von allen Seiten her das Verderben über sie kommen." },
      { number: 33, text: "In Hazor werden dann nur noch Schakale leben, es wird für immer eine Wüste sein. Niemand wird sich mehr dort niederlassen, und kein Mensch wird dort wohnen bleiben.\"" },
      { number: 34, text: "Es war am Anfang der Regierungszeit des Königs Zidkija* von Juda, als Jeremia ein Wort Jahwes gegen Elam* empfing.", heading: "Botschaft gegen Elam", footnotes: ["Zidkija regierte von 597-586 v.Chr.", "Elam war die persische Provinz um die Hauptstadt Susa."] },
      { number: 35, text: "So spricht Jahwe, der allmächtige Gott: \"Passt auf! Ich zerbreche Elams Bogen, seine stärkste Waffe." },
      { number: 36, text: "Aus allen Himmelsrichtungen lasse ich Stürme gegen Elam los und zerstreue es in alle Winde. Dann wird es kein Volk mehr geben, in dem man nicht auf versprengte Elamiter stößt." },
      { number: 37, text: "Ich werde Elam vor seinen Todfeinden mutlos machen und bringe Unheil über sie, meinen glühenden Zorn\", spricht Jahwe. \"Ich verfolge sie mit dem Schwert, bis sie vernichtet sind." },
      { number: 38, text: "Ich werde den König und seine Oberen von dort verschwinden lassen und meinen eigenen Thron errichten\", spricht Jahwe." },
      { number: 39, text: "\"Doch am Ende der bestimmten Zeit wende ich das Schicksal Elams\", spricht Jahwe." },
    ] },
    { number: 50, verses: [
      { number: 1, text: "Diese Botschaft hat Jahwe durch den Propheten Jeremia an Babylonien, das Land der Chaldäer, gerichtet:", heading: "Es trifft den Vollstrecker Babylon (50-51)\nBotschaft gegen Babylon" },
      { number: 2, text: "Verkündet es den Völkern! / Ruft die Botschaft aus! / Richtet Feldzeichen auf! / Lasst es hören, / verschweigt es nicht: / \"Babylon ist gefallen! / Bel ist blamiert / und Merodach* am Boden zerstört. / Mit ihren Bildern ist es aus, / ihre Götzen sind von Schrecken erfüllt.\"", footnotes: ["Bel und Merodach sind Bezeichnungen für Marduk, den Hauptgott Babylons."] },
      { number: 3, text: "Von Norden her rückt ein Volk heran, das Babylonien verwüstet, sodass niemand mehr darin wohnt. Mensch und Vieh ergreifen die Flucht und laufen davon." },
      { number: 4, text: "\"Wenn diese Zeit gekommen ist\", spricht Jahwe, \"kehren die Israeliten und Judäer gemeinsam zurück. Weinend kommen sie heim und suchen Jahwe, ihren Gott.\"" },
      { number: 5, text: "Sie fragen nach Zion, das ist ihr Ziel. / \"Kommt mit und schließt euch Jahwe an, / in einem ewigen Bund, den wir nie mehr vergessen!\"" },
      { number: 6, text: "Mein Volk war wie eine verlorene Herde, / irregeführt von den eigenen Hirten, / auf Höhen geführt und verführt. / So zogen sie von Berg zu Berg / und vergaßen, wohin sie gehörten." },
      { number: 7, text: "Alle, die sie fanden, fraßen sie. / Und ihre Bedränger sagten: / \"Wir haben keine Schuld, / denn sie haben gegen Jahwe gesündigt, / gegen die Weide der Gerechtigkeit / und die Hoffnung ihrer Väter.\"" },
      { number: 8, text: "\"Flieht aus dem Machtbereich von Babylon, / flieht aus dem Land der Chaldäer! / Seid wie die Leitböcke der Herde!" },
      { number: 9, text: "Denn seht, ich biete Heere gegen Babylon auf. / Ich führe große Völker aus dem Nordland herbei. / Sie stellen sich gegen die Stadt und erobern sie von dort. / Ihre Pfeile sind wie siegreiche Helden, keiner verfehlt sein Ziel." },
      { number: 10, text: "So wird Chaldäa zur Beute. / Alle, die es plündern, bekommen genug\", / spricht Jahwe." },
      { number: 11, text: "Ja, freut euch nur und jubelt, / ihr Räuber meines Eigentums! / Hüpft wie ein Kalb über Stroh, / und wiehert wie die Hengste!" },
      { number: 12, text: "Sehr beschämt wird eure Mutter sein, / ihre ganze Hoffnung ist dahin. / Seht! Ihr seid das Letzte der Völker, / verwüstet, verödet, zur Steppe gemacht. /" },
      { number: 13, text: "Es ist unbewohnt durch Jahwes Zorn, / es bleibt verödet liegen. / Jeder, der an Babylon vorbeikommt, / schüttelt über seine Wunden entsetzt den Kopf." },
      { number: 14, text: "Stellt euch rings um Babylon auf, / all ihr Bogenschützen! / Schießt und spart die Pfeile nicht! / Denn es hat sich an Jahwe vergangen." },
      { number: 15, text: "Schreit und lärmt gegen die Stadt! / Da! Sie hat sich ergeben. / Ihre Türme stürzen ein, / ihre Mauern zerbersten. / Das ist die Rache Jahwes. / Rächt euch an ihr! / Zahlt ihr heim, / was sie anderen tat." },
      { number: 16, text: "Lasst niemand am Leben, / der ein Feld bestellen, / und niemand, der es ernten kann. / Vor dem rasenden Schwert / flieht jeder zu seinem eigenen Volk / und kehrt in seine Heimat zurück." },
      { number: 17, text: "Israel war ein versprengtes Schaf, / von Löwen verscheucht.Zuerst fiel der König von Assyrien darüber her, dann kam König Nebukadnezzar von Babylon und hat ihm noch die Knochen abgenagt." },
      { number: 18, text: "Darum spricht Jahwe, der allmächtige Gott Israels: \"Seht, jetzt ziehe ich den König von Babylon genauso zur Rechenschaft, wie ich das bei dem König von Assyrien tat." },
      { number: 19, text: "Und Israel bringe ich an seinen Weideplatz zurück. Es soll wieder auf dem Karmel* weiden und in Baschan*, im Bergland von Efraïm und in Gilead.", footnotes: ["Karmel. Fruchtbares Gartenland an den Hängen des Karmelberges am Mittelmeer.", "Baschan. Fruchtbares Weideland nordöstlich vom See Gennesaret."] },
      { number: 20, text: "Wenn die Zeit gekommen ist\", spricht Jahwe, \"wird man die Schuld Israels suchen, doch sie ist nicht mehr da. Auch die Sünden Judas findet man nicht mehr. Denn ich vergebe denen, die ich übrig lasse.\"" },
      { number: 21, text: "Gegen das Land Meratajim*: \"Zieht gegen sie hinauf und gegen die Bewohner von Pekod! Macht sie nieder und vernichtet sie samt ihrem Besitz\", spricht Jahwe. \"Tut es genau nach meinem Befehl!\"", heading: "Völlige Zerstörung", footnotes: ["Meratajim und Pekod waren Landschaften in Babylonien. Ihre Namen erinnern an die hebräischen Begriffe für \"Doppeltrotz\" und \"Strafe\"."] },
      { number: 22, text: "Kriegslärm im Land, / gewaltiger Zusammenbruch!" },
      { number: 23, text: "Wie sehr ist zerhauen, zerbrochen der Hammer der ganzen Welt! / Was für ein Bild des Entsetzens ist Babylon unter den Völkern!" },
      { number: 24, text: "\"Ich habe dir eine Falle gestellt, Babylon, / und du hast es nicht gemerkt. / Du wurdest gefunden und gepackt, / weil du Krieg mit Jahwe anfingst.\"" },
      { number: 25, text: "Jahwe hat sein Arsenal geöffnet / und die Waffen seines Zorns herausgeholt. / Es gibt Arbeit für den Herrn, / für Jahwe, den allmächtigen Gott, / und zwar im Land der Chaldäer." },
      { number: 26, text: "\"Fallt von allen Seiten darüber her! / Brecht seine Vorratshäuser auf! / Werft alles auf einen Haufen, / so, wie man Garbenhaufen macht! / Und dann vernichtet alles, / ohne den kleinsten Rest!" },
      { number: 27, text: "Stecht seine Stiere alle nieder, / schlachtet sie ab! / Weh über sie, denn der Tag ist gekommen, / die Zeit der Abrechnung ist da.\"" },
      { number: 28, text: "Horcht! Flüchtlinge aus Babylon. / Sie sind entkommen, um in Zion zu verkünden / die Rache von Jahwe, unserem Gott, / die Vergeltung für die Zerstörung des Tempels." },
      { number: 29, text: "Ruft Schützen gegen Babylon zusammen, / Leute, die den Bogen spannen! / Schließt den Belagerungsring! / Niemand darf entkommen! / Vergeltet der Stadt ihr Tun, / zahlt ihr heim, was sie getan hat! / Denn sie hat vermessen gehandelt, / hat sich gegen Jahwe gestellt, / gegen Israels heiligen Gott." },
      { number: 30, text: "\"Darum fallen ihre jungen Männer auf den Plätzen, / ihre Krieger kommen um an jenem Tag\", spricht Jahwe." },
      { number: 31, text: "\"Pass auf! / Jetzt gehe ich gegen dich vor, / du stolze Stadt\", / spricht Jahwe, der Herr, / der allmächtige Gott, / \"denn jetzt ist dein Tag gekommen, / die Zeit der Abrechnung ist da." },
      { number: 32, text: "Dann wird die Stolze stürzen / und niemand hilft ihr auf. / Ich lege Feuer an ihre Städte, / das ringsum alles verzehrt.\"" },
      { number: 33, text: "So spricht Jahwe, der allmächtige Gott: \"Israeliten und Judäer wurden unterdrückt. Und die, die sie in die Verbannung führten, haben sich geweigert, sie wieder loszulassen." },
      { number: 34, text: "Doch ihr Erlöser ist stark. Er heißt Jahwe, der allmächtige Gott. Er wird ihnen zum Recht verhelfen, um ihrem Land Ruhe zu bringen. Unruhe verschafft er nur Babylons Bewohnern.\"" },
      { number: 35, text: "\"Ein Schwert über die Chaldäer\", spricht Jahwe, \"und über die Bewohner von Babylon, über ihre Oberen und Weisen!" },
      { number: 36, text: "Ein Schwert über die Orakelpriester, dass sie zu Narren werden! Ein Schwert über ihre Helden, dass sie vor Angst vergehen." },
      { number: 37, text: "Ein Schwert über ihre Pferde und Streitwagen, über ihre Söldnertruppen, die zu ängstlichen Frauen werden. Ein Schwert über ihre Schätze, die geplündert werden." },
      { number: 38, text: "Ein Schwert über ihre Gewässer, die austrocknen werden. Denn es ist ein Land der Götzenbilder. Deren Fratzen machen sie verrückt." },
      { number: 39, text: "Darum werden Wüstentiere dort hausen, Schakale und Strauße sich tummeln, aber Menschen sollen niemals mehr dort wohnen." },
      { number: 40, text: "So wie Gott Sodom und Gomorra und die ganze Gegend umgestürzt hat, so wird auch hier kein Mensch mehr wohnen und sich aufhalten wollen.\"" },
      { number: 41, text: "Seht, ein Volk, es kommt von Norden, / eine große Nation. / Viele Könige brechen auf, / sie kommen vom Ende der Erde." },
      { number: 42, text: "Sie kommen mit Bogen und Langschwert, / sind grausam und ohne Erbarmen. / Auf Pferden reiten sie heran, /es klingt wie das Donnern der Brandung. / Es sind Krieger, zum Kampf gerüstet / gegen dich, du Tochter Babylons." },
      { number: 43, text: "Als dein König die Nachricht erhielt, / sanken seine Hände herab. / Angst hat ihn gepackt, / Wehen, wie eine gebärende Frau." },
      { number: 44, text: "Seht, er kommt wie ein Löwe aus dem Jordandickicht. Zum immergrünen Weideplatz steigt er herauf. \"Ja, ich jage sie plötzlich davon und setze meinen Erwählten dort ein. Denn wer ist mir gleich, und wer lädt mich vor Gericht? Und welcher Hirt könnte sich mir widersetzen?\"" },
      { number: 45, text: "Darum hört, was Jahwe über Babylon beschlossen hat, was er über das Land der Chaldäer denkt:Wie eine Herde schleppt man sie fort, / selbst die Kinder und die Schwachen. / Ihr eigenes Land ist entsetzt über sie." },
      { number: 46, text: "Vom Ruf \"Babylon ist erobert!\" / erbebt die ganze Erde. / Unter den Völkern hört man ihr Geschrei." },
    ] },
    { number: 51, verses: [
      { number: 1, text: "So spricht Jahwe: \"Passt auf! Ich lasse einen Sturm gegen Babylon los, gegen alle, die im Zentrum des Aufruhrs gegen mich wohnen.", heading: "Gottes Gericht über Babylon" },
      { number: 2, text: "Ich werde Fremde nach Babylon schicken, die es so hoch in den Wind werfen, dass das Land leer wird. An seinem Unheilstag wird Babylon von allen Seiten angegriffen." },
      { number: 3, text: "Lasst keinen Schützen seinen Bogen spannen, lasst keinen sich in seiner Rüstung erheben! Habt kein Mitleid mit den jungen Männern von Babylon! Vernichtet das gesamte Heer!\"" },
      { number: 4, text: "Überall im Land der Chaldäer sollen Erschlagene liegen, die Straßen sollen voll mit Erstochenen sein." },
      { number: 5, text: "Denn Israel und Juda sind nicht verwitwet von ihrem Gott, von Jahwe, dem Allmächtigen. Doch das Chaldäerland ist voll von Schuld gegen den Heiligen Israels." },
      { number: 6, text: "Flieht aus dem Land hinaus und rettet euer Leben, dass ihr nicht mit umkommt, wenn Babylonien wegen seiner Schuld bestraft wird. Denn die Zeit der Vergeltung ist da. Jahwe zahlt ihm heim, was es getan hat." },
      { number: 7, text: "Ein Goldbecher in Jahwes Hand war Babylon, / und es berauschte die ganze Welt. / Die Völker tranken von seinem Wein, / und deshalb sind sie rasend geworden." },
      { number: 8, text: "Babylon fällt plötzlich zu Boden und zerbricht. / Trauert um Babylon, / holt Balsam für seine Wunde! / Vielleicht wird es geheilt." },
      { number: 9, text: "\"Wir wollten Babylon heilen, / doch ihm war nicht zu helfen. / Verlasst es! Jeder ziehe in sein Land! / Denn dieses Strafgericht reicht bis an den Himmel / und türmt sich auf bis zu den Wolken.\"" },
      { number: 10, text: "\"Jahwe hat ans Licht gebracht / unsere gerechte Sache. / Kommt, lasst uns in Zion erzählen, / was Jahwe getan hat, unser Gott!\"" },
      { number: 11, text: "\"Schärft die Pfeile, fasst die Schilde!\" Jahwe gab es den Königen von Medien* ein, gegen Babylon Krieg zu führen und es zu vernichten. Das ist die Rache Jahwes für die Zerstörung seines Tempels.", footnotes: ["Medien. Die Meder bewohnten ein Gebiet, das im heutigen nordwestlichen Iran liegt."] },
      { number: 12, text: "\"Richtet das Feldzeichen gegen die Mauern von Babylon auf! Verschärft die Belagerung! Stellt Posten auf! Legt Truppen in den Hinterhalt!\" Wie Jahwe es sich vorgenommen hat und was er den Babyloniern androhte, das führt er nun aus." },
      { number: 13, text: "Ja, du wohnst an großen Wassern, / du bist unermesslich reich. / Dein Ende ist gekommen, / du hast nun genug geraubt." },
      { number: 14, text: "Jahwe, der allmächtige Gott, schwor bei sich selbst: \"Wenn ich dich auch mit Menschen angefüllt habe wie mit Heuschrecken, so wird man doch das Triumphgeschrei über dich erheben.\"" },
      { number: 15, text: "Durch seine Kraft hat er die Erde gemacht, / durch seine Weisheit die Welt errichtet, / durch seine Klugheit die Himmel ausgespannt.", heading: "Gottes Größe" },
      { number: 16, text: "Auf seinen Befehl hin / sammelt sich das Wasser am Himmel, / steigen Wolken am Horizont auf, / öffnen Blitze dem Regen die Bahn, / bricht der Wind aus seinen Kammern hervor." },
      { number: 17, text: "Wie dumm steht jeder Mensch davor, begreift es nicht, / und jeder Goldschmied schämt sich für sein Götzenbild. / Denn diese Bilder sind Betrug, sie haben kein Leben." },
      { number: 18, text: "Nichtse sind sie, Figuren zum Spott. / Wenn abgerechnet wird, sind sie verloren!" },
      { number: 19, text: "Wie anders ist da Jakobs Gott, / denn er hat das Weltall geschaffen / und Israel zu seinem Eigentum gemacht. / Jahwe, der Allmächtige, heißt er." },
      { number: 20, text: "Du warst mein Hammer, meine Waffe im Krieg. / Mit dir zerhämmerte ich Völker, / mit dir zerschlug ich Königreiche.", heading: "Babylon als Gottes Hammer" },
      { number: 21, text: "Mit dir zermalmte ich Pferd und Reiter, / mit dir zertrümmerte ich Lenker und Wagen." },
      { number: 22, text: "Mit dir zerschmetterte ich Mann und Frau, / zermalmte junge Männer und Frauen." },
      { number: 23, text: "Mit dir zerdrosch ich Hirt samt Herde, / den Bauer samt seinem Gespann, / selbst Statthalter und Befehlshaber zerschlug ich mit dir." },
      { number: 24, text: "\"Jetzt aber werde ich Babylon und allen Chaldäern das Böse heimzahlen, das sie an Zion verübt haben. Vor euren Augen werde ich es tun\", spricht Jahwe." },
      { number: 25, text: "\"Pass auf! Jetzt gehe ich gegen dich vor\", spricht Jahwe, \"du Berg des Verderbens, der die ganze Erde verdarb. Ich werde dich fassen und wälze dich von den Felsen hinab. Ich mache einen Berg von Schutt und Asche aus dir," },
      { number: 26, text: "sodass man in dir keinen Stein mehr findet, der noch als Grund- oder Eckstein taugt. Für alle Zeiten sollst du ein Schutthaufen sein\", spricht Jahwe." },
      { number: 27, text: "Richtet überall das Feldzeichen auf, stoßt ins Kriegshorn unter den Völkern! Ruft sie zum Kampf gegen Babylon auf: die Königreiche von Ararat, von Mini und Aschkenas*. Bestellt Offiziere, die Truppen ausheben, lasst Reiterscharen anrücken, furchtbar wie die kriechenden Heuschrecken.", heading: "Babylons Ende", footnotes: ["Ararat, Mini und Aschkenas sind Gegenden in und um Armenien."] },
      { number: 28, text: "Ruft die Völker auf zum Kampf, die Könige von Medien, seine Statthalter und Befehlshaber und die Völker, die sie kommandieren!" },
      { number: 29, text: "Da zittert und bebt die Erde. Denn die Pläne Jahwes gegen Babylon gehen in Erfüllung. Babylonien soll zu einer Wüste werden, in der kein Mensch mehr wohnt." },
      { number: 30, text: "Babyloniens Helden haben den Kampf aufgegeben. Sie hocken in ihren Burgen, und ihr Mut ist geschwunden. Wie Frauen vergehen sie vor Angst. Schon stehen ihre Häuser in Flammen, die Stadttore sind aufgebrochen." },
      { number: 31, text: "Ein Läufer nach dem anderen stürmt heran, ein Bote trifft den anderen, um dem König von Babylon zu melden: \"Die Stadt ist von allen Seiten eingenommen." },
      { number: 32, text: "Alle Furten sind besetzt, die Festungsanlagen in Brand gesteckt und die Soldaten vor Schreck wie erstarrt.\"" },
      { number: 33, text: "Denn so spricht Jahwe, der allmächtige Gott Israels:Die Tochter Babylons gleicht einem Dreschplatz, / wenn er gerade festgestampft wird. / Ein Weilchen noch, / dann kommt die Zeit der Ernte für sie." },
      { number: 34, text: "Nebukadnezzar, Babylons König, / hat mich gefressen und mich aufgezehrt, / mich weggeschoben wie ein leeres Gefäß. / Er verschlang mich wie ein Drache, / füllte den Bauch mit meinen Leckerbissen / und stieß mich dann fort." },
      { number: 35, text: "Darum soll Jerusalem sagen: / \"Was ich an Gewalt und Zerfleischung erlitt, / das komme nun über Babylon! / Mein Blut komme über die Chaldäer!\"" },
      { number: 36, text: "Darum spricht Jahwe: / \"Schau, ich verhelfe dir zum Recht! / Ich vollziehe deine Rache! / Ich trockne sein Meer aus, / lasse seine Quellen versiegen." },
      { number: 37, text: "Zum Trümmerhaufen wird Babylon, / zur Wohnung der Schakale, / einem Ort des Grauens und der Verachtung. / Und es wird menschenleer sein.\"" },
      { number: 38, text: "\"Sie brüllen wie die jungen Löwen, / knurren wie ein Löwinnenwurf." },
      { number: 39, text: "Ihrer Gier bereite ich das Gelage / und mache sie betrunken. / Sie sollen lustig werden und dann betäubt / und in ewigen Schlaf versinken, / aus dem sie nie mehr erwachen\", / spricht Jahwe." },
      { number: 40, text: "\"Wie Lämmer führe ich sie zum Schlachten hinab, / wie Schaf- und Ziegenböcke.\"" },
      { number: 41, text: "Wie ist Scheschach* erobert, / besiegt der Ruhm der ganzen Welt! / Was für ein Schreckensbild / bietet Babel den Völkern.", footnotes: ["Scheschach. Wie in Jeremia 25,26 verschlüsselter Name für Babylon."] },
      { number: 42, text: "Ein Meer hat Babylonien überflutet, / hat es mit tosenden Wellen bedeckt." },
      { number: 43, text: "Seine Städte wurden verwüstet. / Das Land ist verdorrt, eine Steppe, / ein Land, in dem niemand mehr wohnt; / kein Mensch reist da mehr hindurch." },
      { number: 44, text: "\"Jetzt werde ich mit Bel, dem Gott von Babylon, abrechnen! Was er verschlungen hat, reiße ich ihm aus dem Maul. Die Völker strömen ihm nicht mehr zu. Auch die Mauer von Babylon ist gefallen.\"" },
      { number: 45, text: "\"Mein Volk, zieh weg aus seiner Mitte! Rette dein Leben vor dem glühenden Zorn Jahwes." },
      { number: 46, text: "Und verliere nicht den Mut! Fürchte dich nicht vor den Nachrichten, die man im Land hört. Denn in einem Jahr hört man dieses, im anderen jenes Gerücht. Überall herrscht die Gewalt, ein Herrscher bekämpft den anderen." },
      { number: 47, text: "Denn es wird der Tag kommen, an dem ich mit den Götzen Babylons abrechne. Mit Babylonien ist es aus, überall liegen Erschlagene herum." },
      { number: 48, text: "Himmel und Erde und alles, was in ihnen lebt, werden in Jubel ausbrechen. Denn von Norden her kommen die Zerstörer über Babylon\", spricht Jahwe." },
      { number: 49, text: "Nun ist Babylon im Begriff zu fallen, ihr Erschlagenen Israels, denn wegen Babylon fielen Menschen in aller Welt." },
      { number: 50, text: "Doch ihr, die dem Schwert entkommen sind, bleibt nicht stehen! Denkt an Jahwe in der Ferne und tragt Jerusalem in eurem Herzen!" },
      { number: 51, text: "Wir schämen uns, denn wir haben den Spott gehört. Schamrot sind wir geworden, denn Fremde drangen in die Heiligtümer des Hauses Jahwes ein." },
      { number: 52, text: "\"Darum seht, es kommen Tage\", spricht Jahwe, \"da rechne ich mit den Götzen Babylons ab. Das Stöhnen tödlich Verwundeter wird das ganze Land erfüllen." },
      { number: 53, text: "Auch wenn Babylon bis zum Himmel aufsteigen würde, wenn es sich in unzugänglicher Höhe verschanzte, würden die Zerstörer doch vor mir her nach Babylon kommen\", spricht Jahwe." },
      { number: 54, text: "Horch! Ein Geschrei ist aus Babylon zu hören. Das Land der Chaldäer bricht zusammen." },
      { number: 55, text: "Denn Jahwe verwüstet Babylon, macht seinem lärmenden Treiben ein Ende. Wie tobende und brüllende Meereswogen donnern seine Wassermassen heran." },
      { number: 56, text: "Ein Verwüster ist über Babylon gekommen. Seine Helden werden gefangen genommen, ihre Bogen sind zerbrochen. Jahwe ist ein Gott der Vergeltung, er rechnet gründlich ab!" },
      { number: 57, text: "\"Ich mache seine Oberen und Weisen betrunken, all seine Statthalter, Befehlshaber und Kriegshelden. Sie sollen betäubt in ewigen Schlaf versinken, aus dem sie nie mehr erwachen\", spricht der König, er heißt Jahwe, der Allmächtige." },
      { number: 58, text: "So spricht Jahwe, der allmächtige Gott: \"Die Mauer des großen Babylon wird bis auf den Grund zerstört, seine stolzen Tore werden in Brand gesteckt. So haben sich die Völker, die sie bauten, für nichts gemüht, ganze Völkerschaften haben sich nur fürs Feuer geplagt.\"" },
      { number: 59, text: "Folgenden Auftrag erteilte der Prophet Jeremia Seraja Ben-Nerija*, dem Enkel Machsejas: Es war im vierten Regierungsjahr des Königs Zidkija von Juda, als dieser nach Babylon reiste. Er wurde von seinem Quartiermeister Seraja begleitet.", heading: "Jeremias Auftrag an Seraja", footnotes: ["Seraja war ein Bruder von Jeremias Schreiber Baruch (siehe Jeremia 32,12)."] },
      { number: 60, text: "Jeremia hatte all die Unheilsankündigungen gegen Babylon in eine einzige Schriftrolle geschrieben" },
      { number: 61, text: "und sagte nun zu Seraja: \"Wenn du nach Babylon kommst, sieh zu, dass du alles, was in dieser Schriftrolle steht, vorliest" },
      { number: 62, text: "und dann sagst: 'Jahwe, du hast dieser Stadt die Vernichtung angekündigt, dass kein Mensch und kein Tier mehr darin wohnt und sie für immer zu einem Trümmerhaufen wird.'" },
      { number: 63, text: "Dann sollst du einen Stein an die Schriftrolle binden und sie in den Euphrat werfen." },
      { number: 64, text: "Rufe dabei: 'So wird Babylon versinken und nicht mehr auftauchen wegen des Unheils, das ich über die Stadt bringe. Mit ihr ist es aus.'\"Hier enden die Worte Jeremias.*", footnotes: ["Worte Jeremias. Offenbar wurde das letzte Kapitel von anderer Hand hinzugefügt. Wahrscheinlich war es derjenige, der auch das 2. Buch der Könige zusammenstellte, eventuell Baruch."] },
    ] },
    { number: 52, verses: [
      { number: 1, text: "Als Zidkija die Herrschaft antrat, war er 21 Jahre alt. Er regierte elf Jahre in Jerusalem. Seine Mutter hieß Hamutal; sie war eine Tochter von Jirmeja und stammte aus Libna.", heading: "52: Rebellischer König – das Ende der Stadt\nDas Ende Zidkijas" },
      { number: 2, text: "Und so wie König Jojakim tat Zidkija, was Jahwe verabscheute." },
      { number: 3, text: "Doch jetzt war das Maß voll. Jahwe war so zornig über die Leute von Juda und Jerusalem, dass er sie aus seinen Augen wegschaffen ließ. – Dann lehnte sich Zidkija gegen den König von Babylon auf." },
      { number: 4, text: "Es geschah am 10. Januar* im neunten Regierungsjahr des Königs Zidkija von Juda, dass König Nebukadnezzar von Babylon mit seinem ganzen Heer begann, Jerusalem zu belagern. Er ließ einen Belagerungswall rings um die Stadt aufschütten.", footnotes: ["Januar. Wörtlich: des 10. Monats. Im Jahr 588 v.Chr."] },
      { number: 5, text: "Die Belagerung dauerte bis ins elfte Regierungsjahr Zidkijas.*", footnotes: ["Zidkijas. Bis Mitte 586 v. Chr."] },
      { number: 6, text: "Zuletzt hatte der Hunger in der Stadt überhand genommen. Am 9. Juli* war für das einfache Volk nichts mehr zu essen da.", footnotes: ["Juli. Wörtlich: im 4. Monat."] },
      { number: 7, text: "Da wurde eine Bresche in die Stadtmauer geschlagen. In der Nacht darauf flohen die Soldaten durch den Torweg zwischen den beiden Mauern am Königsgarten und durchbrachen den Belagerungsring. Sie versuchten, in Richtung der Araba* zu entkommen.", footnotes: ["Als Araba wird der Jordangraben bezeichnet, der sich von Norden nach Süden durch ganz Israel zieht, sogar noch über das Tote Meer hinaus bis nach Elat. Er ist zwischen 12,5 und 22,5 km breit und befindet sich fast überall unter dem Meeresspiegel, im Toten Meer 394 Meter unter NN."] },
      { number: 8, text: "Doch die chaldäischen Truppen nahmen die Verfolgung auf und holten Zidkija in der Araba bei Jericho* ein. Sein Heer ließ ihn im Stich und zerstreute sich.", footnotes: ["bei Jericho. Das war eine Strecke von etwa 25 km bei einem Höhenunterschied von mehr als 1000 m."] },
      { number: 9, text: "So nahmen sie den König gefangen und brachten ihn nach Ribla* vor den König von Babylon, wo das Urteil über ihn gesprochen wurde.", footnotes: ["Ribla. Siehe 2. Könige 23,33!"] },
      { number: 10, text: "Der König ließ Zidkija zusehen, wie seine Söhne abgeschlachtet wurden. Auch die Oberen von Juda wurden in Ribla hingerichtet." },
      { number: 11, text: "Danach wurden Zidkija die Augen ausgestochen, und der König ließ ihn in Ketten nach Babylon bringen, wo er bis zu seinem Tod in Gefangenschaft blieb." },
      { number: 12, text: "Am 10. August* im 19. Regierungsjahr des Königs Nebukadnezzar von Babylon, traf Nebusaradan, der Befehlshaber der königlichen Leibwache, einer der engsten Vertrauten des Königs, in Jerusalem ein.", footnotes: ["August. Wörtlich: des 5. Monats. Im Jahr 586 v. Chr. Die Parallele in 2. Könige 25,8 hat allerdings den 7. August. Eine der beiden Zahlen ist offenbar ein Fehler späterer Abschreiber."] },
      { number: 13, text: "Er ließ den Tempel Jahwes, den Königspalast und alle großen Häuser niederbrennen." },
      { number: 14, text: "Seine Truppen zerstörten auch die ganze Stadtmauer." },
      { number: 15, text: "Dann ließ Nebusaradan den Rest der Einwohner, die einfachen Leute und alle, die zum König von Babylon übergelaufen waren, und den Rest der Handwerker gefangen nehmen und in die Verbannung führen." },
      { number: 16, text: "Nur einige Leute vom einfachen Volk ließ der Befehlshaber der Leibwache zurück, um die Äcker und Weinberge zu bestellen." },
      { number: 17, text: "Die Chaldäer zertrümmerten die beiden Bronzesäulen, die vor dem Haus Jahwes standen, ebenso die Kesselwagen und das bronzene \"Meer\"* und schafften das Metall nach Babylon.", footnotes: ["Meer. Siehe 2. Könige 16,17."] },
      { number: 18, text: "Sie nahmen auch die Töpfe und Schaufeln, die Messer, die Schalen zum Auffangen des Blutes und alle anderen Schalen und Bronzegegenstände mit, die für den Tempeldienst gebraucht worden waren." },
      { number: 19, text: "Auch die Becken, die Feuerpfannen und Sprengschalen, die Töpfe, die Leuchter, die Schalen und die Opferschalen und überhaupt alles, was aus reinem Gold und Silber war, nahm der Befehlshaber der Leibwache mit." },
      { number: 20, text: "Für die beiden Säulen, das \"Meer\", die zwölf Bronzerinder darunter und die Kesselwagen im Haus Jahwes hatte König Salomo eine ungeheure Menge Bronze verarbeitet." },
      { number: 21, text: "Jede der Säulen war neun Meter hoch. Ihr Umfang betrug sechs Meter. Sie waren innen hohl und hatten eine Wanddicke von acht Zentimetern." },
      { number: 22, text: "Auf jeder ruhte ein Kapitell aus Bronze von zweieinhalb Meter Höhe*, das ringsum mit einem Gitterwerk und mit Granatäpfeln verziert war, alles aus Bronze.", footnotes: ["zweieinhalb Meter Höhe. Wenn man diese Angaben und die aus 1. Könige 7 zugrunde legt, betrug das Gewicht jeder Säule insgesamt etwa 40 Tonnen."] },
      { number: 23, text: "Es waren 96 frei hängende Granatäpfel an dem Gitterwerk befestigt, insgesamt 100." },
      { number: 24, text: "Der Befehlshaber der Leibwache ließ den obersten Priester Seraja festnehmen, dazu seinen Stellvertreter Zefanja und die drei für die Torwache verantwortlichen Priester." },
      { number: 25, text: "In der Stadt fanden sich noch der Hofbeamte, der für die Soldaten zuständig gewesen war, sieben* Männer, die zu den Vertrauten des Königs gehört hatten, der Beamte, der für die Musterung des Heeres verantwortlich war und 60 seiner Männer.", footnotes: ["sieben. Die Parallele in 2. Könige 25,19 hat \"fünf\". Siehe Fußnote zu Vers 12."] },
      { number: 26, text: "Nebusaradan, der Befehlshaber der Leibwache, brachte sie nach Ribla zum König von Babel." },
      { number: 27, text: "Dieser ließ sie dort, in der Provinz Hamat, hinrichten. – So wurde das Volk von Juda in die Verbannung geführt." },
      { number: 28, text: "Hier ist die Zahl der von Nebukadnezzar Weggeführten: In seinem 7. Regierungsjahr 3023 Judäer," },
      { number: 29, text: "in seinem 18. Regierungsjahr 832 Einwohner von Jerusalem." },
      { number: 30, text: "Im 23. Regierungsjahr Nebukadnezzars führte Nebusaradan, der Befehlshaber der Leibwache, 745 Judäer fort. Insgesamt waren es 4 600 Männer, die in die Gefangenschaft geführt wurden.*", footnotes: ["geführt wurden. Bei den hier angegebenen Wegführungen handelt es sich offenbar um kleinere Deportationen, die vor den eigentlichen Eroberungszügen Nebukadnezzars stattfanden, deshalb die unterschiedlichen Jahres- und Zahlenangaben im Vergleich zu 2. Könige 24 und 25."] },
      { number: 31, text: "In dem Jahr, als Ewil-Merodach König von Babylonien wurde, begnadigte er König Jojachin von Juda und holte ihn aus dem Gefängnis. Das geschah im 37. Jahr seiner Gefangenschaft, am 25. März*.", heading: "Begnadigung von König Jojachin", footnotes: ["März. Wörtlich: im 12. Monat. Die Parallele in 2. Könige 25,27 liest \"am 27. Tag\". Siehe Fußnote zu Vers 12! Es war im Jahr 561 v.Chr."] },
      { number: 32, text: "Er behandelte ihn freundlich und gab ihm eine Ehrenstellung unter den Königen, die nach Babylon gebracht worden waren." },
      { number: 33, text: "Jojachin durfte seine Gefängniskleidung ablegen und zeitlebens an der Tafel des Königs speisen." },
      { number: 34, text: "Der König sorgte auch sonst für seinen Unterhalt. Bis zu seinem Lebensende bekam er täglich, was er brauchte.*", footnotes: ["... was er brauchte. Damit erfüllte sich, was Jeremia 37 Jahre vorher vorausgesagt hatte (Jeremia 22,30)."] },
    ] },
  ],
};